window.JASTROW_CHUNKS[31]={"12400":{"h":"כִּילּוּי","r":"K00538","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּלָה\">כָּלָה</a>) </div><div class=\"sense\"><b>1)</b> <i>finishing</i>. Sifra K’dosh. ch. I; <span class=\"citation\">Y. Peah IV, 18ᵇ</span> <span dir=\"rtl\">בשעת הכ׳</span> at the time when the end of the field is cut (with ref. to <span dir=\"rtl\">תכלה</span>, <span class=\"citation\">Lev. XIX, 9</span>); a. e.</div><div class=\"sense\"><b>—2)</b> <i>extinction, destruction</i>. <span class=\"citation\">Lev. R. s. 7</span>, beg. (ref. to <span dir=\"rtl\">שמד</span>, <span class=\"citation\">Deut. IX, 20</span>) <span dir=\"rtl\">כ׳ בנים וכ׳</span> the extinction of his family; ib. s. 10. Mekh. Bo s. 8 <span dir=\"rtl\">מצות כִּילּוּייוֹ בכל דבר</span> it (the leavened bread) may be destroyed in any manner, opp. <span dir=\"rtl\">מצות כ׳ בשריפה</span> it must be destroyed by fire.</div>","alt":[]},"12401":{"h":"כִּילּוּיָא","r":"K00539","html":"<div class=\"sense\">, <i>destruction</i>.—*<span dir=\"rtl\">כּילּוּי סִילְוֵי</span> (or <a href=\"#\" data-headword=\"סִילֵי\">סִילְיֵי</a>) <i>destruction of thistles</i>, name of an insect, prob. <i>caterpillar</i> (or <i>bruchus</i> (?), v. Sm. Ant. s. v.). <span class=\"citation\">Gen. R. s. 51</span>, beg. (expl. <a href=\"#\" data-headword=\"שַׁבְּלוּל\">שבלול</a>, <span class=\"citation\">Ps. LVIII, 9</span>) [read:] <span dir=\"rtl\">כהדין כ׳ סיליי כשלשול וכ׳</span> [<a href=\"#\" data-headword=\"*לימצא\">לימצא</a> is a gloss borrowed from a comment. to Ps. l. c. and absent in <span class=\"citation\">Yalk. Ps. 776</span>] like the caterpillar, like the abdominal secretion &amp;c. <span class=\"citation\">Y. Shek. VI, 50ᵃ</span> top <span dir=\"rtl\">כקרני סיליי וכיליי</span> (Bab. ed. to VI, 2 Ms. M. <span dir=\"rtl\">סילוי וכילוי</span>, early ed. only <a href=\"#\" data-headword=\"ס׳\">ס׳</a>) the water coming forth from the Temple (<span class=\"citation\">Zech. XIV, 8</span>) will be … as minute as the horns (feelers) of the caterpillar (thinner than those of <span dir=\"rtl\">חגבים</span>).</div>","alt":[]},"12402":{"h":"כִּילּוּלָא","r":"K00540","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">כלל</span>) <i>crowning, finishing</i>; <span dir=\"rtl\">כִּילּוּל בָּתֵּי</span> <i>house-finishing</i>, the reception given on the finishing of a house. Tanḥ. <span class=\"citation\">B’resh. 2</span> (Sh’ilt. 1 <span dir=\"rtl\">הילול בתי</span>).</div>","alt":[]},"12403":{"h":"כִּילוֹן","r":"K00541","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אוּבְלָא II\"><span dir=\"rtl\">אוּבְלָא</span> II</a>) <i>one whose head has the shape of a basket</i> (calathus), <i>wedge-shaped</i>. <span class=\"citation\">Bekh. VII, 1</span>, expl. <span class=\"citation\">ib. 43ᵇ</span>. [Mus. refers to Lat. cilo.]</div>","alt":["(בִּילוֹן)"]},"12404":{"h":"כילוס","r":"K00542","html":"<div class=\"sense\">, <span class=\"citation\">Y. Sabb. VII, 10ᵇ</span> bot., v. <a href=\"#\" data-headword=\"*בילוס\">בילוס</a></div>","alt":[]},"12405":{"h":"כילוף","r":"K00543","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כּוֹלֵף\">כּוֹלֵף</a></div>","alt":[]},"12406":{"h":"*כילופיס","r":"K00544","html":"<div class=\"sense\">, <span class=\"citation\">Pesik. R. s. 23</span> <span dir=\"rtl\">כשהן כ׳</span>, read: <span dir=\"rtl\">כשהוא פִּילוֹטִימוֹס</span> (φιλότιμος) when he is <i>liberal</i> (v. <span dir=\"rtl\">פילוטמיא</span>).</div>","alt":["כילסופיס"]},"12407":{"h":"כִּילִי","r":"K00545","html":"<div class=\"sense\"> (χιλι-) <i>one thousand</i>-. Pesik. Baḥod., p. 107ᵇ; <span class=\"citation\">Pesik. R. s. 21</span>; <span class=\"citation\">Yalk. Ps. 796</span> [read:] <span dir=\"rtl\">כילי כיליאדין מירי מיריאדין</span> (χιλι-χιλιάδες, μυρι-μυρίαδες) a thousand times thousand, a myriad of myriads.</div>","alt":[]},"12408":{"h":"כִּילְיָא","r":"K00546","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּלְיָה\">כִּלְיָה</a></div>","alt":["כִּילְיָה"]},"12409":{"h":"כִּילְיָאדִין","r":"K00547","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (χιλιάδες) <i>thousands</i>, v. <a href=\"#\" data-headword=\"כִּילִי\">כִּילִי</a>.</div>","alt":[]},"12410":{"h":"כִּילְיוֹן","r":"K00548","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"כִּילָה\">כִּילָה</a>, <i>enclosure, partition, curtain</i>. <span class=\"citation\">Y. Ber. III, 6ᵈ</span></div>","alt":[]},"12411":{"h":"כיליונין","r":"K00549","html":"<div class=\"sense\">, <span class=\"citation\">Lam. R. to I, 4</span> quot. in Ar., prob. a corrupt. of <span dir=\"rtl\">בִּירְיוֹנִין</span> (v. <a href=\"#\" data-headword=\"בִּירְיוֹן\">בִּירְיוֹן</a>); ed. <span dir=\"rtl\">בוליוטין</span>, v. <a href=\"#\" data-headword=\"בּוּלֶבְטֵס\">בּוּלֶבְטֵס</a>.</div>","alt":[]},"12412":{"h":"כיליי","r":"K00550","html":"<div class=\"sense\">, <span class=\"citation\">Gen. R. s. 51</span>, beg. <span dir=\"rtl\">כ׳ סילוי</span>; <span class=\"citation\">Y. Shek. VI, 50ᵃ</span> top <span dir=\"rtl\">סיליי וכ׳</span>, v. <a href=\"#\" data-headword=\"כִּילּוּיָא\">כִּילּוּיָא</a></div>","alt":[]},"12413":{"h":"כיליינא","r":"K00551","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Lam. 1042</span>, v. <a href=\"#\" data-headword=\"*בִּלְיוֹנָא\">בִּלְיוֹנָא</a></div>","alt":[]},"12414":{"h":"כִּילְכּוּל","r":"K00552","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּילְבִּית\">כִּלְ׳</a></div>","alt":[]},"12415":{"h":"כילכיד","r":"K00553","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּלְכִּיד\">כַּלְכִּיד</a></div>","alt":[]},"12416":{"h":"כִּילְכִּית","r":"K00554","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (= <span dir=\"rtl\">כילכלית</span>, v. <span dir=\"rtl\">כלכל</span>; or denom. of <span dir=\"rtl\">כלב</span>, cmp. <a href=\"#\" data-headword=\"כּוּלָב\">כּוּלָב</a>) name of a <i>small fish</i>, supposed to be <i>stickleback</i>. <span class=\"citation\">Tosef. Ab. Zar. IV</span> (<span class=\"citation\">V), 11</span> <span dir=\"rtl\">כל שכילכ׳ אחת או שתי כּוּלְכִּיּוֹת וכ׳</span> ed. Zuck. (Var. <span dir=\"rtl\">כלכלת … כלכליות</span>, <span dir=\"rtl\">כלבת … כלביות</span>) when one or two <i>k</i>. swim in it (the brine); <span class=\"citation\">Ab. Zar. 39ᵇ</span> bot. <span dir=\"rtl\">כילבית … כילביות</span> ed. (Ms. M. <a href=\"#\" data-headword=\"*מִלְכָי\">מלכי</a>, read <a href=\"#\" data-headword=\"כִּנָּרָא\">כי׳</a> as <span class=\"citation\">ib. 40ᵃ</span>; Alf. ed. Cost. <span dir=\"rtl\">כלכלית</span>, v. Rabb. D. S. a. l. note). <span class=\"citation\">Sabb. 77ᵇ</span> <span dir=\"rtl\">אימת כילב׳ וכ׳</span> ed. (Ms. M. <a href=\"#\" data-headword=\"כִּלְכִּית\">כּוּלְכִּית</a>, Ms. O. <span dir=\"rtl\">כילכ׳</span>) the fear which the Leviathan has of the <i>k</i>.—<span class=\"citation\">Ḥull. 97ᵃ</span></div>","alt":["(כִּילְבִּית)","כִּלְ׳"]},"12417":{"h":"כִּילַן","r":"K00555","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , <i>curtain, cover</i>. <span class=\"citation\">Targ. Y. I Gen. XXV, 25</span> (Y. II <span dir=\"rtl\">כִּבְלַן</span> read: <a href=\"#\" data-headword=\"*כָּכְלַן\">כָּכְלַן</a>, q. v.).—Y. Meg. III, 73ᵈ bot. [read:] <span dir=\"rtl\">תחתוי דההן כ׳</span> under the curtain or wrapper (for the chest containing the Book of the Law).</div>","alt":[]},"12418":{"h":"כילרין","r":"K00556","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בּוֹלְרִין\">בּוֹלְרִין</a></div>","alt":[]},"12419":{"h":"כִּילְתָא I","r":"K00557","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"כילרין\">same</a>, <i>enclosure; bridal canopy, curtained bed</i>. <span class=\"citation\">Targ. Job XV, 32</span> כִּילְתֵיה Ms. (ed. <span dir=\"rtl\">כַּלְתֵיה</span>, h. text <a href=\"#\" data-headword=\"כִּפָּה\">כִּפָּה</a>). <span class=\"citation\">Targ. Y. Ex. II, 1</span>. <span class=\"citation\">Targ. Y. Gen. XLVI, 21</span> <span dir=\"rtl\">כֵּילַת הילולא</span> (to h. text <span dir=\"rtl\">חֻפִּים</span>, v. <a href=\"#\" data-headword=\"חוּפָּה\">חוּפָּה</a>).—<span class=\"citation\">Snh. 29ᵇ</span> <span dir=\"rtl\">בכִילְתֵיה</span> behind the curtain of his bed-room. <span class=\"citation\">Succ. 26ᵃ</span> <span dir=\"rtl\">למיגנא בכ׳ וכ׳</span> to sleep in the Succah under a canopy.</div>","alt":[]},"12420":{"h":"*כִּילְתָא II","r":"K00558","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"כַּיְילָא\">כַּיְילָא</a>) <i>measure, vessel</i>.—<span class=\"citation\">B. Mets. 40ᵃ</span> Ms. H., v. <a href=\"#\" data-headword=\"כַּיְילָא\">כַּיְילָא</a>.—Pl. constr. <a href=\"#\" data-headword=\"כִּילָוַות\">כִּילָוַות</a>. <span class=\"citation\">Targ. Job XXXVIII, 37</span> (Ms. <a href=\"#\" data-headword=\"בילוות\">בִּילָוַות</a>?; h. text <span dir=\"rtl\">נִבְלֵי</span>).</div>","alt":[]},"12421":{"h":"כִּימָא","r":"K00559","html":"<div class=\"sense\">, v. next wds.</div>","alt":[]},"12422":{"h":"כִּימָה","r":"K00560","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> or <span dir=\"rtl\">כמם</span>, cmp. Assyr. <i>Kimmut</i>, Rawl. Five Gr. Mon. ch. VII; <i>Kimtu</i> family, Schr. KAT<sup>2</sup> p. 557) <i>Kimah</i> (<i>gathering</i>), a constellation, prob. <i>Draco</i> (not Pleiades). <span class=\"citation\">Ber. 58ᵇ</span> (etymol. play) <span dir=\"rtl\">כ̇מ̇אה̇ ככבי</span> as bright as a hundred stars. <span class=\"citation\">Ib. 59ᵃ</span>; <span class=\"citation\">Yalk. Gen. 56</span> <span dir=\"rtl\">נטל … מכ׳ וכ׳</span> the Lord took two stars away from <i>K</i>. and brought the flood &amp;c.; <span class=\"citation\">R. Hash. 11ᵇ</span>, sq. <span class=\"citation\">B. Mets. 106ᵇ</span>. <span class=\"citation\">Y. Taan. I, 64ᵃ</span> bot. <span class=\"citation\">Num. R. s. 10</span> <span dir=\"rtl\">הדעת … ככ׳</span> knowledge is compared to the <i>K</i> … <span dir=\"rtl\">מה כ׳ מבשלת וכ׳</span> as the Kimah causes the ripening of the fruits and gives them taste, so does knowledge &amp;c. <span class=\"citation\">Gen. R. s. 10</span> <span dir=\"rtl\">כ׳ מעדנת וכ׳</span>, v. <a href=\"#\" data-headword=\"עָדַן\">עָדַן</a>; a. e.</div>","alt":[]},"12423":{"h":"כִּימְתָא","r":"K00561","html":"<div class=\"sense\"><span class=\"citation\">Targ. Am. V, 8</span> (ed. Lag. <a href=\"#\" data-headword=\"כִּימָה\">כימה</a>). <span class=\"citation\">Targ. Job IX, 9</span> <span dir=\"rtl\">כימא</span> (Ms. <a href=\"#\" data-headword=\"כִּימְתָא\">כימתא</a>). <span class=\"citation\">Ib. XXXVIII, 31</span>. Targ. II Esth. III, 3 <a href=\"#\" data-headword=\"כִּימָה\">כימה</a>.</div>","alt":["כִּימָא"]},"12424":{"h":"כֵּין","r":"K00562","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כֵּן\">כֵּן</a></div>","alt":[]},"12425":{"h":"כִּינָּא","r":"K00563","html":"<div class=\"sense\"> , <i>louse, vermin</i>. <span class=\"citation\">Sabb. 82ᵃ</span> (Ms. M. a. some ed. <span dir=\"rtl\">כינה</span>). <span class=\"citation\">Erub. 65ᵃ</span> <span dir=\"rtl\">כינה</span>.</div>","alt":["(כִּינָּה)"]},"12426":{"h":"כִּינַאי","r":"K00564","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"חֲכִינַאי\">חֲכִינַאי</a>. <span class=\"citation\">Tosef. Shebu. III, 6</span> ed. Zuck.</div>","alt":[]},"12427":{"h":"כִּינָּה","r":"K00565","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּנַן\">כנן</a>, cmp. <span dir=\"rtl\">קנן</span>) </div><div class=\"sense\"><b>1)</b> <i>nest, cavity, chamber</i>.—Pl. <a href=\"#\" data-headword=\"כִּינִּים\">כִּינִּים</a>, <a href=\"#\" data-headword=\"כִּינִּים\">כִּינִּין</a>, <a href=\"#\" data-headword=\"כִּינּוּיָא\">כִּנִּ׳</a>. <span class=\"citation\">Lev. R. s. 14</span> Ar. (ed. <span dir=\"rtl\">קינין</span>); <span class=\"citation\">Yalk. Job 905</span>; cmp. <a href=\"#\" data-headword=\"כּוֹנָנִית\">כּוֹנָנִית</a>.</div><div class=\"sense\"><b>—2)</b> (b. h. pl. <a href=\"#\" data-headword=\"כִּינִּים\">כִּנִּים</a>, collect. <a href=\"#\" data-headword=\"כִּנָּא\">כִּנָּם</a>) <i>vermin, louse</i> (also collect.). <span class=\"citation\">Par. IX, 2</span> <span dir=\"rtl\">הכ׳ שבתבואה</span> the vermin in grain. <span class=\"citation\">Ḥag. 5ᵃ</span>; a. e.—<i>Pl.</i> as above. <span class=\"citation\">B. Kam. 82ᵃ</span> <span dir=\"rtl\">הורג כ׳ שבבני מעיים</span> (Var. in Ms. <a href=\"#\" data-headword=\"*הֲכִינָה\">הכינה</a>) (garlic) kills the parasites in entrails. <span class=\"citation\">Pes. 112ᵇ</span>. <span class=\"citation\">Kidd. 49ᵇ</span>; <span class=\"citation\">Esth. R. to I, 3</span>; a. fr.—<span class=\"citation\">Sabb. 107ᵇ</span> ביצי כ׳ <i>nits</i>, or a species of vermin called <i>lice-nits</i>; <span class=\"citation\">Ab. Zar. 3ᵇ</span></div>","alt":["כִּנָּה"]},"12428":{"h":"כִּינּוּי","r":"K00566","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּנָה\">כָּנָה</a>) <i>by-name, surname; attribute, substituted word</i>. <span class=\"citation\">Snh. VII, 5</span> <span dir=\"rtl\">דנין … בכ׳</span> the witnesses are examined by using a substitute for the Divine Name (v. <a href=\"#\" data-headword=\"יוֹסֵי\">יוֹסֵי</a>). <span class=\"citation\">Sot. VII, 6</span> <span dir=\"rtl\">במקדש … ובמדינה בכִינּוּיוֹ</span> in the Temple the Divine Name is pronounced as it is written, in the country (outside the Temple) by its substitute (Ădonai). <span class=\"citation\">Ib. 38ᵃ</span> <span dir=\"rtl\">בכ׳</span>, opp. <span dir=\"rtl\">שם המפורש</span>; a. e.—Pl. <span dir=\"rtl\">כִּינּוּיִים</span>, <span dir=\"rtl\">כִּינּוּיִין</span>, <a href=\"#\" data-headword=\"כִּינּוּיָא\">כִּנּ׳</a>. <span class=\"citation\">Ned. I, 1</span> <span dir=\"rtl\">כִּינּוּיֵי נדרים</span> words used as substitutes for vows <a href=\"#\" data-headword=\"נְדַר I\">(נדר</a>); <span class=\"citation\">ib. 2</span> <span dir=\"rtl\">כ׳ לחרם</span> substitutes for <i>ḥerem</i> (v. <a href=\"#\" data-headword=\"חֵרֶק\">חֵרֶק</a>); a. fr.—<span dir=\"rtl\">כִּינּוּיֵי כִּינּוּיִין</span> secondary substitutes, e.g. the use of <i>g’rog’roth</i> for <i>tirosh</i> and this for <i>eshkol</i>, v. <a href=\"#\" data-headword=\"גְּרוֹגֶרֶת\">גְּרוֹגֶרֶת</a>. <span class=\"citation\">Tosef. Naz. II, 1</span>; Y. ib. II, beg. 51ᵈ</div>","alt":["כִּנּוּי"]},"12429":{"h":"כִּינּוּיָא","r":"K00567","html":"<div class=\"sense\"><span class=\"citation\">Targ. Y. Lev. XXIV, 15</span> constr. <a href=\"#\" data-headword=\"כִּינּוּי\">כִּינּוּי</a>.</div>","alt":["כִּנּ׳"]},"12430":{"h":"כִּינּוּס","r":"K00568","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּנַס\">כָּנַס</a>) </div><div class=\"sense\"><b>1)</b> <i>gathering, piling up.</i> <span class=\"citation\">Kel. XV, 5</span> <span dir=\"rtl\">העשוי לכ׳</span> a vessel used for piling up (shovel &amp;c.), opp. <span dir=\"rtl\">לקבלה</span> as a receptacle. <span class=\"citation\">Nidd. 49ᵇ</span> <span dir=\"rtl\">כ׳ ע&quot;י הדחק</span> receiving (absorbing) liquids under pressure (through pores, perforations &amp;c.) <span class=\"citation\">B. Bath. 68ᵃ</span> <span dir=\"rtl\">בית כ׳ העצים</span> (Ms. O. <a href=\"#\" data-headword=\"כּוֹנֵס\">כּוֹנֵס</a>; <span class=\"citation\">Tosef. ib. III, 3</span> <a href=\"#\" data-headword=\"כְּנִיסָא\">כְּנִיסַת</a>) store-room for wood. <span class=\"citation\">Snh. VIII, 5</span> <span dir=\"rtl\">כ׳ לרשעים כו׳</span> gathering (living together) of the wicked is bad &amp;c., opp. <a href=\"#\" data-headword=\"פִּיזּוּר\">פִּיזּוּר</a>. <span class=\"citation\">Y. Kidd. I, 59ᵈ</span> top <span dir=\"rtl\">מקום כ׳ שיער</span> a spot of the body where hair grows in quantities. <span class=\"citation\">Gen. R. s. 32</span> (ref. to <span class=\"citation\">Gen. VII, 5</span>) <span dir=\"rtl\">זה שיכון לכ׳ וכ׳</span> this is the execution of the command to gather in the animals. <span class=\"citation\">Midr. Till. to Ps. VIII</span> (ref. to <span dir=\"rtl\">ויצר</span>, <span class=\"citation\">Gen. II, 19</span>) <span dir=\"rtl\">לשון כ׳</span> it means the gathering (the animals before Adam); <span class=\"citation\">Gen. R. s. 17</span> <span dir=\"rtl\">וכאן לכבוש</span> (corr. acc.); a. fr.</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"כְּנֶסֶת\">כְּנֶסֶת</a>) <i>retirement for prayer</i>. <span class=\"citation\">Gen. R. s. 84</span>, beg. (ref. to <span dir=\"rtl\">קבוציך</span>, <span class=\"citation\">Is. LVII, 13</span>) <span dir=\"rtl\">כִּינּוּסוֹ וכ׳ בניו וכ׳</span> his (Jacob’s) and his sons’ prayers saved him &amp;c.; <span class=\"citation\">Yalk. Gen. 140</span>; <span class=\"citation\">Yalk. Is. 349</span>.</div>","alt":["כִּנּ׳"]},"12431":{"h":"כִּינּוּפְיָא","r":"K00569","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּנוּפְיָא\">כְּנוּפְיָא</a></div>","alt":[]},"12432":{"h":"כִּינּוֹר","r":"K00570","html":"<div class=\"sense\"> v. sub <a href=\"#\" data-headword=\"כִּנּוֹרָא\">כִּנּוֹ׳</a>.</div>","alt":["כִּינּוֹרָא"]},"12433":{"h":"כֵּינִי","r":"K00571","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כֵּן\">כֵּן</a></div>","alt":[]},"12434":{"h":"כִּינִּים","r":"K00572","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּינָּה\">כִּינָּה</a></div>","alt":["כִּינִּין"]},"12435":{"h":"כִּינַּר","r":"K00573","html":"<div class=\"sense\">, v. sub <span dir=\"rtl\">כנ׳</span>.</div>","alt":["כִּינְּרָא","כִּינֶּרֶת"]},"12436":{"h":"כִּינָרִיס","r":"K00574","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Kil. III, 12</span> ed. Zuck., v. <a href=\"#\" data-headword=\"קִינָרָס\">קִינָרָס</a></div>","alt":[]},"12437":{"h":"כִּינְשָׁא","r":"K00575","html":"<div class=\"sense\"> v. sub <span dir=\"rtl\">כנ׳</span>.</div>","alt":["כִּינְתָּא"]},"12438":{"h":"כִּיס","r":"K00576","html":"<div class=\"sense\"><i>receptacle, pouch, bag; purse, fund</i>. <span class=\"citation\">Bekh. 39ᵇ</span>; <span class=\"citation\">Tosef. ib. IV, 6</span>, v. <a href=\"#\" data-headword=\"זוּבָּן\">זוּבָּן</a>. <span class=\"citation\">B. Kam. X, 1</span> <span dir=\"rtl\">כ׳ של גבאין</span> the collection fund of (royal) collectors. <span class=\"citation\">Erub. 65ᵇ</span> <span dir=\"rtl\">בכִיסוֹ</span>, v. <a href=\"#\" data-headword=\"כּוֹס I\"><span dir=\"rtl\">כּוֹס</span> I</a>. <span class=\"citation\">Keth. X, 4</span> <span dir=\"rtl\">שהטילו לכ׳</span> who formed a partnership for business. <span class=\"citation\">Y. Hor. III, 48ᶜ</span> (ref. to <span class=\"citation\">Prov. XVI, 11</span>) <span dir=\"rtl\">כולהם … מכ׳ אחד</span> all of them receive their wages out of the same fund (of divine rewards).—<span dir=\"rtl\">חסרון כ׳</span>, v. <a href=\"#\" data-headword=\"חֶסְרוֹן\">חֶסְרוֹן</a>.—<span class=\"citation\">Sabb. 53ᵃ</span> <span dir=\"rtl\">הזב בכ׳ שלו</span> the gonorrhoist with his bag (for his genitals); <span dir=\"rtl\">העזים בכ׳ וכ׳</span> the goats with the bag over their teats; Tosef. ib. IV (V), 5 <span dir=\"rtl\">בכיסין</span>. <span class=\"citation\">Lev. R. s. 12</span> (ref. to <a href=\"#\" data-headword=\"כִּיס\">כיס</a>, K’ri <a href=\"#\" data-headword=\"כּוֹס III\">כוס</a>, <span class=\"citation\">Prov. XXIII, 31</span>) <span dir=\"rtl\">הוא נותן עינו בכוס וחנוני … בכ׳</span> he (the drunkard) sets his eye on the cup, the shopkeeper—on the money bag. Ib. <span dir=\"rtl\">בכיס כתיב לשון נקי הוא</span> it is written (Prov. l. c.) ‘on the bag’ which is a euphemism (for illicit intercourse) as in (<span class=\"citation\">Prov. I, 14</span>) &amp;c. Tanḥ. Sh’mini 11; a. fr.—Pl. <span dir=\"rtl\">כִּיסִים</span>, <span dir=\"rtl\">כִּיסִין</span>. <span class=\"citation\">Y. Ab. Zar. III, 42ᵈ</span> bot.—Tosef. l. c.; a. e.</div>","alt":[]},"12439":{"h":"כִּיס ²","r":"K00577","html":"<div class=\"sense\"> Targ. XLVI, 6. <span class=\"citation\">Targ. Prov. I, 14</span>; a. e.—<span class=\"citation\">Ber. 58ᵇ</span> <span dir=\"rtl\">לא שקל ידא מן כ׳</span> never took his hand out of his pocket (always prepared for charity). <span class=\"citation\">Pes. 113ᵃ</span> <span dir=\"rtl\">שרי כִּיסָיךְ וכ׳</span> untie thy purse, open thy sack, i.e. sell only for cash (Var. lect., v. Rabb. D. S. a. l. note). [<span class=\"citation\">Sabb. 67ᵃ</span> לכ׳ לימא הכי Ar. for a bag (<i>ulcer</i>), v. <a href=\"#\" data-headword=\"כֵּיבָא\">כֵּיבָא</a>.]—Pl. <a href=\"#\" data-headword=\"כִּירַיָּא\">כִּיסַיָּא</a>, <span dir=\"rtl\">כִּיסֵי</span>. <span class=\"citation\">Y. Kidd. I, 60ᵈ</span>, v. <a href=\"#\" data-headword=\"גְּרַר\">גְּרַר</a>. <span class=\"citation\">Ab. Zar. 70ᵃ</span> <span dir=\"rtl\">כמה כ׳ וכ׳</span> how many money-bags ought to be found on the street! <span class=\"citation\">Sabb. 147ᵃ</span> <span dir=\"rtl\">כִּיסֵי בבלייתא</span> pouches (a sort of <i>cape</i> or <i>hood</i>) worn by the Babylonian women; (Ar.: <span dir=\"rtl\">כישי</span>, Ms. M. <a href=\"#\" data-headword=\"כּוּשִׁי\">כושי</a>, v. <a href=\"#\" data-headword=\"כִּישָׁא\">כִּישָׁא</a> a. <a href=\"#\" data-headword=\"מַרְזֵב\">מַרְזֵב</a>).—V. <a href=\"#\" data-headword=\"כִּיסְתָא I\">כִּיסְתָא</a>.</div>","alt":["כִּיסָא"]},"12440":{"h":"כֵּיסָא","r":"K00578","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּסַס\">כְּסַס</a>) </div><div class=\"sense\"><b>1)</b> <i>thorn</i> (cmp. <a href=\"#\" data-headword=\"קֵיסָא\">קֵיסָא</a>).—Pl. <span dir=\"rtl\">כֵּיסִין</span>, <span dir=\"rtl\">כֵּיסֵי</span>, <a href=\"#\" data-headword=\"כִּיסְתָא II\">כִּיסּ׳</a>. <span class=\"citation\">Y. Sabb. VI, 8ᶜ</span> bot. <span dir=\"rtl\">מקטוע כ׳</span> to cut thorns. <span class=\"citation\">Sabb. 77ᵇ</span> <span dir=\"rtl\">אכל כ׳</span> (Ms. M. <span dir=\"rtl\">בוצי</span>, <span dir=\"rtl\">ביני</span>, Ar. <a href=\"#\" data-headword=\"ביסי\">ביסי</a>) (the camel) eats thorns. <span class=\"citation\">B. Mets. 42ᵇ</span>, sq. <span dir=\"rtl\">בכ׳ … דמי כ׳</span> (Ms. H. <a href=\"#\" data-headword=\"ב׳\">ב׳</a>, v. Rabb. D. S. a. l. note 6) when what he gave him in trust was thorns (on which the cuscuta was hanging), and he pays him the value of thorns.</div><div class=\"sense\"><b>—2)</b> <i>fodder</i>, v. <a href=\"#\" data-headword=\"כִּיסְתָא II\"><span dir=\"rtl\">כִּיסְתָא</span> II</a>.</div>","alt":["כִּיסָּא"]},"12441":{"h":"כִּיסָאנֵי","r":"K00579","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּיסָנִין\">כִּיסָנִין</a>, <a href=\"#\" data-headword=\"כִּיסְנִין\"><a href=\"#\" data-headword=\"כִּיסְנִין\">כִּיסְנִין</a>.</a></div>","alt":["כִּיסָאנִין"]},"12442":{"h":"כִּיסּוּחַ","r":"K00580","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּסַח\">כָּסַח</a>) <i>cutting down, clearing</i>. <span class=\"citation\">M. Kat. 3ᵃ</span>. <span class=\"citation\">Gen. R. s. 12</span>; <span class=\"citation\">Cant. R. to I, 1</span>; Koh. R. to II, 12 <span dir=\"rtl\">דרך הכ׳</span> in the path made by clearing the thicket; a. e.</div>","alt":["כּסּ׳"]},"12443":{"h":"כִּיסּוּי","r":"K00581","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (כָּסָה II) </div><div class=\"sense\"><b>1)</b> <i>act of covering</i>. <span class=\"citation\">Ḥull. VI, 1</span> <span dir=\"rtl\">כ׳ הדם</span> the law concerning the covering with ashes of the blood of killed animals (<span class=\"citation\">Lev. XVII, 13</span>). Ib. 4 <span dir=\"rtl\">כ׳ אחד לכולן</span> for all of them one covering up is sufficient.—<span class=\"citation\">Koh. R. to IV, 6</span> (ref. to <span dir=\"rtl\">וכסה</span>, <span class=\"citation\">Lev. XVI, 13</span>) <span dir=\"rtl\">הכ׳ הזה וכ׳</span></div><div class=\"sense\"><b>—2)</b> <i>cover, lid, roofing</i>. <span class=\"citation\">Num. R. s. 4</span> <a href=\"#\" data-headword=\"כִּנָּרָא\">כי׳</a> interch. with <span dir=\"rtl\">כסוי</span> (b. h. <a href=\"#\" data-headword=\"כְּסוּי\">כְּסוּי</a> constr.). <span class=\"citation\">Gen. R. s. 1</span> <span dir=\"rtl\">וכִיסּוּיוֹ</span>, v. <a href=\"#\" data-headword=\"אִלְפֵּס\">אִלְפֵּס</a>. <span class=\"citation\">Pes. 94ᵃ</span> <span dir=\"rtl\">ככ׳ קדירה</span> like the lid of a pot. <span class=\"citation\">Kel. XII, 3</span>, v. <a href=\"#\" data-headword=\"טְנִי\">טְנִי</a>. <span class=\"citation\">Tosef. Kel. B. Mets. IV, 11</span> <span dir=\"rtl\">כ׳ קביא</span>, v. <a href=\"#\" data-headword=\"קַבְיָא\">קַבְיָא</a>; a. fr.—[<span class=\"citation\">Pesik. R. s. 39</span> <span dir=\"rtl\">בחדש שהוא כי׳</span>, read: <a href=\"#\" data-headword=\"כְּסוּי\">כָּסוּי</a>, v. <a href=\"#\" data-headword=\"כסי\"><span dir=\"rtl\">כָּסָה</span> I</a>.]—Pl. <span dir=\"rtl\">כִּיסּוּיִין</span>, <a href=\"#\" data-headword=\"כִּיסּוּי\">כִּסּ׳</a>. Tosef. l. c.; a. e.—[<span class=\"citation\">Y. Ter. VIII, 45ᵈ</span> <span dir=\"rtl\">הכיסוין</span>, read: <span dir=\"rtl\">הכְּסוּיִין</span>, v. <a href=\"#\" data-headword=\"כסי ²\"><span dir=\"rtl\">כָּסָה</span> II</a>.]</div>","alt":["כִּסּ׳"]},"12444":{"h":"כִּיסּוּיָא","r":"K00582","html":"<div class=\"sense\"><b>1)</b> <i>covering, roofing</i>. <span class=\"citation\">Taan. 22ᵇ</span> <span dir=\"rtl\">ככ׳ דתנורא</span> (Ms. M. <span dir=\"rtl\">כי כיסתא</span>, corr. acc.) as high up as the arch of the oven.</div><div class=\"sense\"><b>—2)</b> <i>cover, cloak</i>. <span class=\"citation\">Keth. 68ᵃ</span> <span dir=\"rtl\">לבושא וכ׳</span> garment and wrap.—Pl. <span dir=\"rtl\">כִּיסּוּיִין</span>. Targ. II Esth. VI, 10 [read:] <span dir=\"rtl\">מן כִּיסּוּיַי</span>.—</div><div class=\"sense\"><b>*3)</b> <i>secret</i>.—Pl. fem. <span dir=\"rtl\">כִּיסּוּיָין</span>, <a href=\"#\" data-headword=\"כִּיסּוּי\">כִּסּ׳</a>. <span class=\"citation\">Targ. Job XI, 6</span>.</div>","alt":["כִּסּ׳"]},"12445":{"h":"כִּיסּוּפָא","r":"K00583","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּסַף I\">כְּסַף</a>) <i>putting to shame; disgrace, shame</i>. <span class=\"citation\">Targ. Y. Gen. III, 10</span> (nakedness). <span class=\"citation\">Targ. Ps. LXIX, 8</span> (<i>fem</i>.); a. fr.—<span class=\"citation\">Hor. 13ᵇ</span> <span dir=\"rtl\">אתיא מילתא לידי כ׳</span> this may lead to putting (R. S.) to shame. <span class=\"citation\">Taan. 9ᵇ</span> <span dir=\"rtl\">רחמנא … מכ׳ דשימי</span> the Lord save us from being put to shame through Shimi (by his questions). <span class=\"citation\">Snh. 11ᵃ</span> <span dir=\"rtl\">מחמת כ׳</span> in order to save the man from shame. <span class=\"citation\">Taan. 25ᵃ</span> top <span dir=\"rtl\">משום כ׳</span> to avoid exposure, v. <a href=\"#\" data-headword=\"אַקְטַרְתָּא\">אַקְטַרְתָּא</a>. <span class=\"citation\">B. Kam. 86ᵇ</span> <a href=\"#\" data-headword=\"כ׳\">כ׳</a> feeling of shame, contrad. to <a href=\"#\" data-headword=\"זִילוּתָא\">זילותא</a> disgrace though not felt. <span class=\"citation\">Num. R. s. 14</span> <span dir=\"rtl\">בלשון ירושלמי … כס׳</span> in the Jerusalem dialect (of the Chaldaic) they say for <i>ḥerpah, kissufa</i>. [כיסופין <span class=\"citation\">Targ. Prov. II, 22</span> some ed., read: <span dir=\"rtl\">נסופין</span>, v. <a href=\"#\" data-headword=\"סוּף\">סוּף</a> II ch.]</div>","alt":["כִּסּ׳"]},"12446":{"h":"כִּיסִּיּוֹת","r":"K00584","html":"<div class=\"sense\"><b>,</b> v. <a href=\"#\" data-headword=\"כֶּסֶת\">כֶּסֶת</a></div>","alt":[]},"12447":{"h":"כִּיסִיתָא","r":"K00585","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (dimin. of <a href=\"#\" data-headword=\"כִּיס\">כִּיס</a>) <i>a little bag</i>. <span class=\"citation\">Meg. 26ᵇ</span> bot. <span dir=\"rtl\">מיעבדיה … כ׳ לסיפרא</span> Ms. M. (Ms. M. 2 <span dir=\"rtl\">כִּסְוָאתָא</span> pl. of <span dir=\"rtl\">כִּסְוָא</span>; Ms. O. <a href=\"#\" data-headword=\"כִּיסְתָא I\">כִּיסְתָא</a>; ed. <a href=\"#\" data-headword=\"פְּרִיסָא\">פריסא</a>, v. Rabb. D. S. a. l. note) to alter it into a bag for a book of the Law.</div>","alt":[]},"12448":{"h":"כִּיסְכּוּס","r":"K00586","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כִּסְכֵּס\">כִּסְכֵּס</a>) <i>rubbing</i> (clothes, in washing). <span class=\"citation\">Zeb. 94ᵇ</span> <span dir=\"rtl\">כיבוס … כ׳</span> washing without rubbing.</div>","alt":[]},"12449":{"h":"כִּיסְלָא","r":"K00587","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּסִילָא\">כְּסִילָא</a></div>","alt":[]},"12450":{"h":"כִּיסְנָא","r":"K00588","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּסָן\">כְּסָן</a>.—[<span class=\"citation\">Sabb. 138ᵇ</span> <span dir=\"rtl\">בכיסנא</span>, v. <a href=\"#\" data-headword=\"כֶּסֶךְ\">כֶּסֶךְ</a>.]</div>","alt":[]},"12451":{"h":"כִּיסְנֵי","r":"K00589","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּיסְנִין\">כִּיסְנִין</a></div>","alt":[]},"12452":{"h":"כִּיסָנִין","r":"K00590","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<span dir=\"rtl\">כסס</span>, adopt. fr. Chald.; cmp. <a href=\"#\" data-headword=\"מְלִילָה\">מְלִילָה</a>) <i>nibblings, dessert</i>. <span class=\"citation\">Tosef. Ber. IV, 4</span> <span dir=\"rtl\">כסאנ׳</span> ed. Zuck. (Var. <span dir=\"rtl\">כיסאנ׳</span>, <span dir=\"rtl\">כיסנ׳</span>). <span class=\"citation\">Ber. 41ᵇ</span> <span dir=\"rtl\">פת הבאה בכ׳</span> bread offered as dessert. <span class=\"citation\">Y. Snh. X, 28ᵈ</span> top <span dir=\"rtl\">נשים … מיני כ׳</span> women selling all kinds of sweetmeats (<span class=\"citation\">Sifré Num. 131</span> <span dir=\"rtl\">בשמים</span>). <span class=\"citation\">Y. Pes. X, beg. 37ᵇ</span> <span dir=\"rtl\">מיני כִּיסָנִית</span> nibblings.</div>","alt":["כְּסָנִין","(כִּיסָאנִין","כְּסָאנִין)"]},"12453":{"h":"כִּיסְנִין","r":"K00591","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. Num. XXIV, 25</span> (v. Y. Snh. quot. in <a href=\"#\" data-headword=\"כִּיסָנִין\">preced.</a>). <span class=\"citation\">Targ. I Kings XIV, 3</span> (h. text <a href=\"#\" data-headword=\"נקדים\">נקדים</a>). <span class=\"citation\">Targ. Josh. IX, 5</span>; <span class=\"citation\">12</span> <i>crumbling</i> (h. text <a href=\"#\" data-headword=\"נקדים\">נקדים</a>).—<span class=\"citation\">Erub. 29ᵇ</span> <a href=\"#\" data-headword=\"כִּיסְנִין\">כיסא׳</a>, <a href=\"#\" data-headword=\"כִּיסְנִין\">כסא׳</a> ed. (Ar. ed. Koh. <span dir=\"rtl\">כוסאני</span>, oth. ed. <a href=\"#\" data-headword=\"כִּנָּרָא\">כי׳</a>). <span class=\"citation\">Keth. 17ᵇ</span> <span dir=\"rtl\">ארמלתא לית לה כ׳</span> at the wedding of a widow no nibblings (roasted ears) are distributed.</div>","alt":["כִּיסְנֵי","כִּסְ׳","(כִּיסָא׳","כְּסָא׳)"]},"12454":{"h":"כִּיסָנִית","r":"K00592","html":"<div class=\"sense\"><b>,</b> v. <a href=\"#\" data-headword=\"כִּיסָנִין\">כִּיסָנִין</a></div>","alt":[]},"12455":{"h":"כִּיסְתָא I","r":"K00593","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"כִּיס ²\">כִּיסָא</a>, <i>bag</i>. <span class=\"citation\">Ber. 24ᵃ</span> bot. <span dir=\"rtl\">בכ׳</span> (Ms. F. <span dir=\"rtl\">בכִיסְתֵיה</span>) in the bag (of the T’fillin). <span class=\"citation\">Sabb. 105ᵇ</span> top <span dir=\"rtl\">דעבדה כי׳</span> Ms. M. (ed. <span dir=\"rtl\">כי כסתא</span>, Rashi <span dir=\"rtl\">כי כי׳</span>, v. Rabb. D. S. a. l.) when he shapes the garment so as to form (a kind of) a pocket. <span class=\"citation\">Pes. 72ᵃ</span> <span dir=\"rtl\">ודמי ליה כמאן דמנחא בכִיסְתֵיה</span> and it was to him as if lying in his pocket (ever ready to recite it); <span class=\"citation\">Keth. 50ᵃ</span>; <span class=\"citation\">Meg. 7ᵇ</span> <span dir=\"rtl\">בכִיסֵיה</span>. [<span class=\"citation\">Keth. 98ᵃ</span>, v. <a href=\"#\" data-headword=\"כְּסִיתָא\">כְּסִיתָא</a>.]</div>","alt":[]},"12456":{"h":"כִּיסְתָא II","r":"K00594","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּסַס\">כְּסַס</a>) <i>fodder</i>. <span class=\"citation\">Targ. O. Gen. XXIV, 25</span>; <span class=\"citation\">32</span> (v. Berl. Targ. O. II, p. 9; Targ. Y. <a href=\"#\" data-headword=\"*אַסְפַּסְתָּא\">אספסתא</a>, Ar. <a href=\"#\" data-headword=\"כַּסָּא I\">כַּסָּא</a>). <span class=\"citation\">Targ. Jud. XIX, 19</span>; <span class=\"citation\">21</span> (some ed. <span dir=\"rtl\">כִּסְתָא</span>); a. e.—<span class=\"citation\">B. Mets. 85ᵃ</span> <span dir=\"rtl\">כדהוה רמי כ׳ וכ׳</span> when casting fodder for the animal.</div>","alt":["כִּיסְּ׳"]},"12457":{"h":"כִּיעוּר","r":"K00595","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּעַר\">כָּעַר</a>) <i>hideousness</i>. <span class=\"citation\">Ḥull. 44ᵇ</span> (prov.) <span dir=\"rtl\">הרחק מן הכ׳ וכ׳</span> keep aloof from everything hideous and from whatever seems hideous; <span class=\"citation\">Ab. d’R. N. ch. II</span>; <span class=\"citation\">Tosef. Yeb. IV, 7</span>; a. e.</div>","alt":[]},"12458":{"h":"כִּיף","r":"K00596","html":"<div class=\"sense\"><i>to bend</i>, v. <a href=\"#\" data-headword=\"כּוּף\">כּוּף</a>.</div>","alt":[]},"12459":{"h":"כִּיף ²","r":"K00597","html":"<div class=\"sense\"><i>, </i> pl. <span dir=\"rtl\">כִּיפִין</span>, v. <a href=\"#\" data-headword=\"כִּיפָּה\">כִּיפָּה</a>.</div>","alt":[]},"12460":{"h":"כֵּיף","r":"K00598","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b>  [<i>ball</i>,] <i>rock</i>.—Pl. <span dir=\"rtl\">כֵּיפִים</span>, constr. <a href=\"#\" data-headword=\"כֵּיפֵי\">כֵּיפֵי</a>, <a href=\"#\" data-headword=\"כֵּיפֵי\">כֵּפֵי</a>. <span class=\"citation\">Y. Shek. VI, 50ᵃ</span>; <span class=\"citation\">Gen. R. s. 23</span>, v. <a href=\"#\" data-headword=\"בַּרְבַּרְיָא\">בַּרְבַּרְיָא</a>.</div><div class=\"sense\"><b>—2)</b>  (v. <a href=\"#\" data-headword=\"כִּיפָּה\">כִּיפָּה</a>) <i>arch, tuft, umbel</i>. <span class=\"citation\">Tosef. Kel. B. Bath. V, 5</span> <span dir=\"rtl\">כ׳ של נייר</span> a tuft of papyrus; <span dir=\"rtl\">כ׳ של סיב</span> of hemp.—Pl. <span dir=\"rtl\">כֵּיפִין</span>, <a href=\"#\" data-headword=\"כֵּיפְלָא\">כֵּפִ׳</a>. Ib., sq.; v. <a href=\"#\" data-headword=\"כִּיפָּה\">כִּיפָּה</a>.</div>","alt":["כֵּף"]},"12461":{"h":"כֵּיף ²","r":"K00599","html":"<div class=\"sense\">, <i>rock, stone, ball</i>. <span class=\"citation\">Targ. Is. XXXII, 2</span>. <span class=\"citation\">Targ. Prov. XVII, 8</span>; a. fr.—<span class=\"citation\">Y. Shek. V, 48ᵈ</span> <span dir=\"rtl\">היי דין כ׳ מקורר וכ׳</span> which rock (when bored) will give forth water, and which &amp;c., v. <a href=\"#\" data-headword=\"שְׁרַבְרוּבִי\">שְׁרַבְרוּבֵי</a>.—Pl. <span dir=\"rtl\">כֵּיפִין</span>, <span dir=\"rtl\">כֵּיפַיָּא</span>, <a href=\"#\" data-headword=\"כֵּיפֵי\">כֵּיפֵי</a>. <span class=\"citation\">Targ. Y. I Deut. XXXII, 13</span>. <span class=\"citation\">Targ. I Kings XIX, 11</span>. <span class=\"citation\">Targ. Ps. CIV, 18</span>; a. fr.—כיפי טבתא <i>pearls, jewels</i>. <span class=\"citation\">Targ. Prov. III, 15</span>; a. e.—<span class=\"citation\">M. Kat. 25ᵇ</span> <span dir=\"rtl\">כ׳ דנורא</span> (Ms. M. <span dir=\"rtl\">טיפי</span>) fire-balls; <span dir=\"rtl\">כ׳ דברדא</span> hail-stones. <span class=\"citation\">Y. Ab. Zar. IV, 43ᵈ</span> <span dir=\"rtl\">דאת אילין כ׳ …</span> thou must remove these stones. <span class=\"citation\">Keth. 112ᵃ</span> bot. <span dir=\"rtl\">מנשק כ׳ דעכו</span> kissed the rocks (Rashi: <i>corals</i>) of the shore of Ptolemais (as sacred ground); <span class=\"citation\">Y. Shebi. IV, end, 35ᶜ</span> <span dir=\"rtl\">לכֵיפָתָא</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מתקל כֵּיפֵי</span> weighed the stones (to demonstrate his appreciation of the sacred ground); a. fr.—Esp. <a href=\"#\" data-headword=\"כֵּיפֵי\">כֵּיפֵי</a> (v. supra) <i>precious stones, jewelry</i> (prob. <i>amber</i>, v. <a href=\"#\" data-headword=\"כֵּיפָה\">כֵּיפָה</a>). <span class=\"citation\">Erub. 96ᵇ</span>; <span class=\"citation\">Keth. 81ᵇ</span> <span dir=\"rtl\">כ׳ תלא לה</span> has he jewelry suspended on it (his opinion)?, i.e. must his opinion absolutely be accepted?—<span class=\"citation\">B. Bath. 52ᵃ</span>. <span class=\"citation\">B. Mets. 35ᵃ</span> <span dir=\"rtl\">אפקיד כ׳ וכ׳</span> gave jewelry in trust &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">הב לי כֵּיפַי</span> (Ms. M. <a href=\"#\" data-headword=\"כִּיפְתָא\">כֵּיפַאי</a>) give me my jewelry back; a. e.—3) also <a href=\"#\" data-headword=\"כַּף ²\">כַּפָּא</a> (cmp. <a href=\"#\" data-headword=\"גֵּיף\">גֵּיף</a>, <a href=\"#\" data-headword=\"כַּף\">כַּף</a> &amp;c.) <i>shore, border</i>. <span class=\"citation\">Targ. Jud. VII, 12</span>. <span class=\"citation\">Targ. Is. XIX, 7</span> <span dir=\"rtl\">ככֵיפֵיה</span> (ed. Lag. <span dir=\"rtl\">ככפיה</span>; ed. Wil. <span dir=\"rtl\">בכיפי</span>, corr. acc.) like its shore.—<span class=\"citation\">Pes. 4ᵃ</span>, v. <a href=\"#\" data-headword=\"*אֲסִיסְנָא\">אֲסִיסְנָא</a>. <span class=\"citation\">Ned. 40ᵃ</span> bot. <span dir=\"rtl\">נהרא מכֵּיפֵיה וכ׳</span> the Euphrates grows from (the waters coming down) its shores (not from rain); <span class=\"citation\">Sabb. 65ᵇ</span>; <span class=\"citation\">Bekh. 55ᵇ</span>. <span class=\"citation\">Koh. R. to XI, 1</span> <span dir=\"rtl\">הוה מיטמר בכיף ימא</span> (some ed. <span dir=\"rtl\">בכֵף</span>) was hiding himself at the sea-shore; a. e.—Pl. as ab. <span class=\"citation\">Targ. Is. VIII, 7</span> <span dir=\"rtl\">כֵּיפוֹהִי</span>; <span class=\"citation\">Targ. Josh. III, 15</span> (some ed. <span dir=\"rtl\">כַּפּוֹהִי</span>).—<span class=\"citation\">Sabb. 65ᵇ</span> <span dir=\"rtl\">מכֵּיפֵי</span> some ed. (v. supra).—M. Kat. l. c. <span dir=\"rtl\">נשוק כ׳ … אהדדי</span> the shores of … touched each other (the waters rising to the level of the shores; Rashi: <i>the arches</i> of the ruined bridges, v. infra).—4) <i>arch, vault</i>, v. <a href=\"#\" data-headword=\"כִּיפְתָא\">כִּיפְתָא</a>.—5) <i>cap</i>, v. <a href=\"#\" data-headword=\"כִּיפָּה\">כִּיפָּה</a>.—6) <i>bundle, sheaf</i>, v. <a href=\"#\" data-headword=\"כַּף ²\">כַּפָּא</a>. [<a href=\"#\" data-headword=\"כִּיפְתָא\">כיפא</a>, <span class=\"citation\">Tosef. Mikv. IV, 5</span>, v. <a href=\"#\" data-headword=\"כִּיפָּה\">כִּיפָּה</a>, end.]</div>","alt":["כֵּיפָא I"]},"12462":{"h":"כֵּיפָא II","r":"K00600","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>pressure, necessity</i>, v. <a href=\"#\" data-headword=\"כַּיְיפָא\">כַּיְיפָא</a>.</div>","alt":[]},"12463":{"h":"כֵּיפָה","r":"K00601","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"כֵּיף\">כֵּיף</a>) </div><div class=\"sense\"><b>1)</b> <i>ball, stone.</i> Ohol. VIII, 5 <span dir=\"rtl\">כֵּיפַת הברד</span> hail-stone.</div><div class=\"sense\"><b>—2)</b> <i>resin</i> (or something similar) <i>found in balls</i>. <span class=\"citation\">Tosef. Dem. I, 29</span> <span dir=\"rtl\">כֵּפַת המרחץ</span> ed. Zuck. (Var. <span dir=\"rtl\">בפת</span>, emend. by El. Wil. <span dir=\"rtl\">קופת</span>) resin used (with oil) in the bath-room.—כֵּיפַת הירדן <i>Jordan-resin, amber</i> (an adapt. of Eridanus, v. Sm. Ant. s. v. Electrum, Lübker’s Reallex. s. v. Electron). <span class=\"citation\">Kerith. 6ᵃ</span> (one of the ingredients of frankincense).</div><div class=\"sense\"><b>—3)</b> <i>ball, lump</i>. <span class=\"citation\">Y. Sabb. V, 7ᵇ</span> bot. (in Chald. dict.), v. <a href=\"#\" data-headword=\"*גְּבִינְתָּא\">גְּבִינְתָּא</a>.</div>","alt":["כֵּפָה"]},"12464":{"h":"כִּיפָה","r":"K00602","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"כְּפִיפָה\">כְּפִיפָה</a>, <i>bending</i>. <span class=\"citation\">Y. Succ. III, 54ᵃ</span> top (in mixed dict.) <span dir=\"rtl\">כ׳ קומוי</span> (not <a href=\"#\" data-headword=\"קוֹמֵי\">קומי</a>) bending is due before Him; Y. Meg. I, 72ᵃ top <span dir=\"rtl\">בפה קומך</span> (corr. acc.).</div>","alt":[]},"12465":{"h":"כִּיפָּה","r":"K00603","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>arch, doorway, bow</i>. <span class=\"citation\">Yeb. 80ᵇ</span> <span dir=\"rtl\">עושה כ׳</span> forms a bow (when urinating). <span class=\"citation\">Yoma 11ᵇ</span>; <span class=\"citation\">Erub. 11ᵇ</span> <span dir=\"rtl\">כ׳ ר&quot;מ וכ׳</span> as to an arched doorway R. M. says, it requires a M’zuzah. <span class=\"citation\">Tosef. ib. VII</span> (<span class=\"citation\">V), 2</span> <span dir=\"rtl\">עד מקום הכי׳</span> (ed. Zuck. <span dir=\"rtl\">הקופא</span>) to the site of the (now ruined) arch (of Tiberias); Y. ib. V, 22ᵈ bot. <span dir=\"rtl\">עד הכ׳</span>. <span class=\"citation\">Y. Naz. VII, 56ᵃ</span> top <span dir=\"rtl\">הגיעו לכ׳</span> when they arrived at the arch (or arcade). <span class=\"citation\">Ab. Zar. I, 7</span> (<span class=\"citation\">16ᵃ</span>) <span dir=\"rtl\">כ׳ שמעמידין וכ׳</span> the arched chamber in the bath where they put up idolatrous statues. <span class=\"citation\">Pesik. R. s. 41</span> <span dir=\"rtl\">כ׳ של חשבונות … אותה כ׳</span> an arcade named Arch of Accounts (a sort of Exchange) existed outside of Jerusalem, and they used to go out and settle their accounts under this arcade &amp;c. Tanḥ. <span class=\"citation\">B’shall. 17</span> (ref. to <span dir=\"rtl\">קפאו</span>, <span class=\"citation\">Ex. XV, 8</span>) <span dir=\"rtl\">כמין כפה</span> (Mekh. ib., Shir. s. 6 <span dir=\"rtl\">קופה</span>) like a vault; a. e.—Esp. <span dir=\"rtl\">כִּיפַּת הרקיע</span>, or <a href=\"#\" data-headword=\"כּוּפָּה\">כִּופָּה</a> <i>the heavenly arch, sky</i> (believed to be a solid mass). <span class=\"citation\">Gen. R. s. 48</span>, beg. <span class=\"citation\">Gen. R. s. 4</span> <span dir=\"rtl\">הרקיע … ולמעלה … כ׳ וכ׳</span> the firmament is like a lake, and above the lake is the arch, and owing to the heat of the lake the arch exudes drops &amp;c. <span class=\"citation\">B. Bath. 25ᵇ</span> <span dir=\"rtl\">אחורי כ׳</span> back of (above) the sky. <span class=\"citation\">Meg. 11ᵃ</span> ג׳ מלכו תחת הכ׳ Ms. M. 2 (ed. <span dir=\"rtl\">בכ׳</span>, Ms. M. 1 <span dir=\"rtl\">בקופה</span>) three persons ruled over the whole world; a. e.</div><div class=\"sense\"><b>—2)</b> <i>a vaulted chamber, prison</i>. <span class=\"citation\">Snh. IX, 3</span> <span dir=\"rtl\">כונסין אותן לכ׳</span> they put them in prison (for life). <span class=\"citation\">Ib. 5</span>.</div><div class=\"sense\"><b>—3)</b> <i>skull-cap, cap</i>. <span class=\"citation\">Y. Gitt. IV, 45ᵈ</span> bot.; Bab. <span class=\"citation\">Gitt. 20ᵃ</span>; v. <a href=\"#\" data-headword=\"*אנדכתרי\">אנדכתרי</a>; Treat. ʿĂbadim ch. III (ed. Kirchh.) <span dir=\"rtl\">קיפה</span>. <span class=\"citation\">Sabb. 57ᵇ</span> <span dir=\"rtl\">כ׳ של צמר</span> a woolen cap, v. <a href=\"#\" data-headword=\"כָּבוּל II\"><span dir=\"rtl\">כָּבוּל</span> II</a>. Y. ib. V, end, 7ᶜ <span dir=\"rtl\">כ׳ של צמר</span> a woolen cap on the head of a lamb, v. <a href=\"#\" data-headword=\"חָנוּן I\"><span dir=\"rtl\">חָנוּן</span> I</a>; a. e.—<span class=\"citation\">Tosef. Mikv. IV, 5</span>, v. infra.</div><div class=\"sense\"><b>—4)</b>  (cmp. <a href=\"#\" data-headword=\"קוּפָּה\">קוּפָּה</a>) <i>heap, pile</i>. <span class=\"citation\">Y. Snh. X, 27ᵈ</span> bot.; <span class=\"citation\">Y. M. Kat. III, 83ᶜ</span> top <span dir=\"rtl\">כ׳ של אבנים</span> a heap of stones; <span class=\"citation\">Gen. R. s. 100</span> <span dir=\"rtl\">כִּיפַּת אבנים</span>. <span class=\"citation\">Ḥull. 129ᵃ</span> <span dir=\"rtl\">כִּיפַּת שאור וכ׳</span> a heap (lump) of leavened dough which one intended to use as a block to sit on; <span class=\"citation\">Pes. 45ᵇ</span> <a href=\"#\" data-headword=\"כּוֹפֶת\">כופת</a> some ed. (corr. acc.; Ms. M. 2 <a href=\"#\" data-headword=\"כִּנָּרָא\">כי׳</a>; v. Rabb. D. S. a. l. note 90); v. <a href=\"#\" data-headword=\"כּוֹפֶת\">כּוֹפֶת</a>.—Pl. <a href=\"#\" data-headword=\"כִּינִּים\">כִּיפִּין</a>, <span dir=\"rtl\">כִּפִּים</span> (or <span dir=\"rtl\">כֵּיפִ׳</span> fr. <a href=\"#\" data-headword=\"כֵּיף\">כֵּיף</a>) a) <i>top-branches</i> (<i>arches</i>) <i>of palm-trees</i>. <span class=\"citation\">Tosef. Shebi., VII, 16</span> <span dir=\"rtl\"><span dir=\"rtl\">על</span> (<span dir=\"rtl\">של</span>) <span dir=\"rtl\">בין הכֵּיפִ׳</span></span> ed. Zuck. (Var. <span dir=\"rtl\">על מה שבכי׳</span>, <span dir=\"rtl\">שבכופין</span>); <span class=\"citation\">Pes. 53ᵃ</span> <span dir=\"rtl\">על של בין הכ׳</span> as long as there are fruits in the tops. <span class=\"citation\">Tosef. Kel. B. Bath. II, 1</span> <span dir=\"rtl\">שכיפת שתי כ׳ של תמרה וכ׳</span> (R. S. to <span class=\"citation\">Kel. XXII, 9</span> <span dir=\"rtl\">כופות</span>) who tied together two palm branches and sat upon them. <span class=\"citation\">Sabb. XXIV, 2</span> <span dir=\"rtl\">מפספסין את הכ׳</span> you may spread the bunches of branches (for fodder), contrad. to <a href=\"#\" data-headword=\"זִימִין\">זִירִין</a> a. <a href=\"#\" data-headword=\"פְּקִיעִין\">פְּקִיעִין</a>. <span class=\"citation\">Ib. 155ᵃ</span> <span dir=\"rtl\">כ׳ תלתא</span> bunches are called <i>kippin</i> when tied with three bands.—b) <i>billow-crests, surf</i>. <span class=\"citation\">Sot. 34ᵃ</span>. <span class=\"citation\">Ḥag. 19ᵃ</span>; <span class=\"citation\">Ḥull. 31ᵇ</span> <span dir=\"rtl\">אין מטבילין בכ׳</span> you must not immerse vessels in the surf (caps of waves), contrad. to <span dir=\"rtl\">ראשין</span>; <span class=\"citation\">Tosef. Mikv. IV, 5</span> <span dir=\"rtl\">בכיפא</span> ed. Zuck. (oth. ed. <span dir=\"rtl\">בכיפה</span>).</div>","alt":["כִּפָּה"]},"12466":{"h":"כִּיפּוּר","r":"K00604","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּפּוּר\">כִּפּוּר</a></div>","alt":[]},"12467":{"h":"כִּיפֵּחַ","r":"K00605","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּפַח\">כָּפַח</a>, <a href=\"#\" data-headword=\"קָפַח\">קָפַח</a>, v. <a href=\"#\" data-headword=\"כּוּפָּח\">כּוּפָּח</a>) </div><div class=\"sense\"><b>1)</b>  (sub. <span dir=\"rtl\">שוקים</span>) <i>one having high and arched shoulders, hump-backed</i>. <span class=\"citation\">Y. Keth. VII, end, 31ᵈ</span> <span dir=\"rtl\">עובדא … בכ׳</span> (not <span dir=\"rtl\">בכופיח</span>) a case (petition for divorce) came before R. J. against a husband who had become hump-backed (after marriage), and he forced him (to a divorce).</div><div class=\"sense\"><b>—2)</b>  (v. <a href=\"#\" data-headword=\"גִּבֵּחַ\">גִּבֵּחַ</a>, <a href=\"#\" data-headword=\"גְּבִיחַ\"><a href=\"#\" data-headword=\"גְּבִיחַ\">גְּבִיחַ</a>)</a><i>an extremely tall and unshapely person</i>. <span class=\"citation\">Bekh. VII, 6</span> (<span class=\"citation\">45ᵇ</span>) <a href=\"#\" data-headword=\"כ׳\">כ׳</a> Ar. (ed. <span dir=\"rtl\">קפ׳</span>), v. <a href=\"#\" data-headword=\"גִּבֵּחַ\">גִּבֵּחַ</a>. <span class=\"citation\">Y. Ber. IX, 13ᵇ</span> bot. <a href=\"#\" data-headword=\"כ׳\">כ׳</a>; Bab. <span class=\"citation\">Ber. 58ᵇ</span> <span dir=\"rtl\">קפח</span> ed. (Ms. M. <a href=\"#\" data-headword=\"קִרְיָיא\">קי׳</a>; Ms. F. <a href=\"#\" data-headword=\"כּוּפָּה\">כופה</a>, corr. acc.); Tosef. ib. VII (VI), 3 <a href=\"#\" data-headword=\"כ׳\">כ׳</a> (Var. <a href=\"#\" data-headword=\"כִּיפֵּחַ\">כִּיפֵּיחַ</a>, <span dir=\"rtl\">קפח</span>); Tanḥ. Pinḥ. 10; ed. Bub. 1 <a href=\"#\" data-headword=\"ק׳\">ק׳</a>. V. <a href=\"#\" data-headword=\"*הִדְרָנִיקוֹס\">הִדְרָנִיקוֹס</a>.</div>","alt":["(כִּיפֵּיחַ)","קִיפֵּ׳","קִפֵּ׳"]},"12468":{"h":"כֵּיפֵי","r":"K00606","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Be-Khefé</i> in Babylonia. <span class=\"citation\">Ber. 31ᵃ</span> (Ms. M. <a href=\"#\" data-headword=\"קוּפָּאֵי\">קופאי</a>, v. Rabb. D. S. a. l. note).</div>","alt":["בֵּי כ׳"]},"12469":{"h":"כֵּיפְלָא","r":"K00607","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּפַל\">כְּפַל</a>) <i>duplication</i>; <span dir=\"rtl\">בכ׳</span> <i>double</i>. <span class=\"citation\">Targ. Y. II, Gen. XLIII, 12</span>. <span class=\"citation\">Targ. Job XLII, 10</span>; a. fr.—Y. Pes. 30ᵈ bot. [read:] <span dir=\"rtl\">וקנסיה בכֵיפְלָה</span> and he fined him double the amount. <span class=\"citation\">Y. Peah VII, 20ᵇ</span> top <span dir=\"rtl\">בכפ׳ הוות מעביד׳</span> it would have yielded twice the quantity. <span class=\"citation\">Gen. R. s. 91</span> <span dir=\"rtl\">יהבון לי בכ׳</span> give me double the amount. <span class=\"citation\">Lam. R. to I, 5</span> <span dir=\"rtl\">אוכלוסין בכ׳</span> twice as many troops; a. e.—V. <a href=\"#\" data-headword=\"כְּפֵילָא\">כְּפֵילָא</a>.</div>","alt":["כּוּפְלָא","כֵּפְ׳"]},"12470":{"h":"כֵּיפְלָה","r":"K00608","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כֵּיפְלָא\">preced.</a></div>","alt":[]},"12471":{"h":"כיפליסין","r":"K00609","html":"<div class=\"sense\">, <span class=\"citation\">Y. Peah VII, 20ᵃ</span> top <span dir=\"rtl\">דיעבי׳ ד׳ כ׳</span>, read: <span dir=\"rtl\">דיעביד כְּלוּפְסִין</span>.</div>","alt":[]},"12472":{"h":"כִּיפַּר","r":"K00610","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Kippar</i>. <span class=\"citation\">Gitt. 14ᵇ</span>; Y. ib. I, end, 43ᵈ; <span class=\"citation\">Y. Kidd. III, 64ᵃ</span> <span dir=\"rtl\"><span dir=\"rtl\">ר׳ יוסי</span> (<span dir=\"rtl\">בר</span>) <span dir=\"rtl\">בן כ׳</span></span>; <span class=\"citation\">Tosef. Shebi. II, 5</span>; a. fr.</div>","alt":[]},"12473":{"h":"כִּיפְרָא","r":"K00611","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כּוּפְרָה\">כּוּפְרָה</a></div>","alt":[]},"12474":{"h":"כִּיפֵּשׁ","r":"K00612","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*כּוֹפֶשׁ\">כּוֹפֶשׁ</a></div>","alt":[]},"12475":{"h":"כִּיפַּת","r":"K00613","html":"<div class=\"sense\">, constr. of <a href=\"#\" data-headword=\"כִּיפָּה\">כִּיפָּה</a>; <a href=\"#\" data-headword=\"כֵּפַת\">כֵּיפַת</a>, constr. of <a href=\"#\" data-headword=\"כֵּיפָה\">כֵּיפָה</a>.—[<span class=\"citation\">Tosef. Ohol. XII, 2</span>, a. e. <span dir=\"rtl\">כיפת</span> ed. Zuck., v. <a href=\"#\" data-headword=\"כּוֹפֶת\">כּוֹפֶת</a>].</div>","alt":[]},"12476":{"h":"כִּיפְתָא","r":"K00614","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>vault, vaulted chamber; arcade</i>. <span class=\"citation\">Y. Snh. VII, 25ᵈ</span> top <span dir=\"rtl\">תפשיתון כיפ׳</span> the vaulted chamber (in the bath) seized them (kept them spell-bound). <span class=\"citation\">Y. Naz. VII, 56ᵃ</span> top <span dir=\"rtl\">כ׳ דקסרין</span> the arcade of the gate of Caesarea (considered unclean); Y. Ber. III, 6ᵃ <span dir=\"rtl\">כִּפְתָה דק׳</span>.—Pl. <a href=\"#\" data-headword=\"כִּינִּים\">כִּיפִּין</a>. Targ. II Esth. I, 5, v. <a href=\"#\" data-headword=\"כְּפַף\">כְּפַף</a>.</div><div class=\"sense\"><b>—2)</b> <i>bow, curve</i>. <span class=\"citation\">Targ. Job XLI, 12</span> <span dir=\"rtl\">דעביד כיפא</span> which forms a bow (in boiling over; h. text <span dir=\"rtl\">ואגמן</span>); cmp. <a href=\"#\" data-headword=\"כִּיפָּה\">כִּיפָּה</a> beg.</div>","alt":["כֵּיפָא","כִּיפָּא"]},"12477":{"h":"כֵּיפְתָא","r":"K00615","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּפַף\">כְּפַף</a>) </div><div class=\"sense\"><b>1)</b> <i>stocks</i>, an instrument of torture in the shape of a wooden <i>collar</i>. <span class=\"citation\">Targ. Jer. XX, 2</span>, sq.; <span class=\"citation\">ib. XXIX, 26</span> (h. text <span dir=\"rtl\">מהפכת</span>, which Rashi explains by <span dir=\"rtl\">כיפה</span>).</div><div class=\"sense\"><b>—2)</b>  (v. <a href=\"#\" data-headword=\"כְּפִיפָה\">כְּפִיפָה</a>) <i>muzzle</i> with fodder basket. <span class=\"citation\">Snh. 98ᵇ</span> בטולא דכי׳ דחמריה Ms. M. (ed. <span dir=\"rtl\">דכופיתא</span>, v. <a href=\"#\" data-headword=\"כַּפּוּתָא\">כַּפּוּתָא</a>) in the shadow of the basket of the Messiah’s ass.—Pl. <a href=\"#\" data-headword=\"כֵּיפְתָא\">כֵּיפָתָא</a>, <a href=\"#\" data-headword=\"כֵּיפְלָא\">כֵּפָ׳</a>. Midr. Sam. ch. XXI (expl. <span dir=\"rtl\">ירומו</span>, <span class=\"citation\">Ps. CXL, 9</span>, v. <a href=\"#\" data-headword=\"זְמָם I\">זְמָם</a>) <span dir=\"rtl\">רומם כֵּפָתוֹי</span> (some ed. <span dir=\"rtl\">כְּפֵפָתוֹי</span>) lift high his muzzle (strengthen his enemies); <span class=\"citation\">Lev. R. s. 21</span>; <span class=\"citation\">Yalk. Sam. 126</span> <span dir=\"rtl\">חזק כתפוי</span> (corr. acc.) tighten his muzzle.—[<span class=\"citation\">Y. Shebi. IV, end, 35ᶜ</span> <a href=\"#\" data-headword=\"כֵּיפְתָא\">כֵּיפָתָא</a>, v. <a href=\"#\" data-headword=\"כֵּיף ²\"><span dir=\"rtl\">כֵּיפָא</span> I</a>.]</div>","alt":["כֵּפְתָא"]},"12478":{"h":"כֵּיצַד","r":"K00616","html":"<div class=\"sense\"> (contr. of <span dir=\"rtl\">כְּאֵי זֶה צַד</span>, v. <a href=\"#\" data-headword=\"כֵּי\">כֵּי</a>) <i>how?, in what manner?, in what respect?</i> <span class=\"citation\">B. Kam. II, 1</span> <span dir=\"rtl\">כ׳ הרגל וכ׳</span> in what respect is the foot of an animal a constant danger (no forewarning being required to make the owner responsible)? <span class=\"citation\">Ib. V, 4</span> <span dir=\"rtl\">כ׳ משלם וכ׳</span> how is the value of the embryo assessed? <span class=\"citation\">Zeb. V, 3</span> <a href=\"#\" data-headword=\"כ׳\">כ׳</a> in what manner (is the sprinkling performed)?—<span class=\"citation\">B. Mets. III, 12</span>; a. v. fr.—<span class=\"citation\">Tosef. B. Kam. IX, 2</span>, a. fr. ed. Zuck. <a href=\"#\" data-headword=\"כֵּיזֶה\">כֵּיזְצַד</a>.—<span class=\"citation\">Num. R. s. 4</span> <span dir=\"rtl\">הא כְּאֵי צַד וכ׳</span> (some ed. <a href=\"#\" data-headword=\"כֵּיצַד\">כיצד</a></div>","alt":[]},"12479":{"h":"כִּיר","r":"K00617","html":"<div class=\"sense\">, <i>Pi.</i> <span dir=\"rtl\">(<a href=\"#\" data-headword=\"כִּיֵּיד\">כִּיֵּיד</a>) <a href=\"#\" data-headword=\"כִּיֵּיר\">כִּיֵּיר</a></span> (denom. of <a href=\"#\" data-headword=\"כִּירָה I\">כִּירָה</a> II or of <a href=\"#\" data-headword=\"כַּד II\"><span dir=\"rtl\">כַּד</span> II</a>) [<i>to do the work of the stove-setter</i> or <i>of the potter</i> (<a href=\"#\" data-headword=\"כַּיָּיל\">כַּיָּיר</a> or <a href=\"#\" data-headword=\"כִּיֵּיד\">כַּיָּיד</a>, v. <a href=\"#\" data-headword=\"בִּרְכַּיָּיר\">בִּרְכַּיָּיר</a>),] <i>to cement; to lay out with tiles, panels</i> &amp;c. [Ar. reads <a href=\"#\" data-headword=\"ר\">ר</a>, editions mostly <a href=\"#\" data-headword=\"ד\">ד</a>.] <span class=\"citation\">B. Kam. 51ᵃ</span> bot. <span dir=\"rtl\">אחד … וסייד וכ׳</span> (Ms. F. <span dir=\"rtl\">וסייר וכייר</span>) if one dug a pit ten handbreadths deep, and another came and lined it with plaster and cemented it; Mekh. Mishp., N’zik., s. 11. <span class=\"citation\">Ab. Zar. III, 7</span> (<span class=\"citation\">47ᵇ</span>) <span dir=\"rtl\">סיידו וכִיְּירוֹ לאליל</span> Mish. (Bab. ed. <span dir=\"rtl\">וכיידו לע&quot;ז</span>) he plastered the room and put tiles on (v. Sm. Ant. s. v. Abacus) designing it for idolatrous purposes. Ib. <span dir=\"rtl\">סיידה וכִיְּירָהּ וכ׳</span> (Ms. M. <span dir=\"rtl\">וציירה</span>) if one plastered and stuccoed a stone (slab) for an idolatrous purpose. <span class=\"citation\">Gen. R. s. 28</span> <span dir=\"rtl\">סיידה וכיירה וציירה</span> he plastered and panelled and painted the wedding chamber; <span class=\"citation\">Lam. R. to IV, 11</span> <span dir=\"rtl\">וכיידה</span>. <span class=\"citation\">Tosef. Sot. VIII, 7</span> <span dir=\"rtl\">כִּיְּירוּהוּ וסיידוהו וכ׳</span> (Var. <span dir=\"rtl\">כִּיְּדוּהָ</span>, <span dir=\"rtl\">כִּיְּרוּהָ</span>) they panelled the stone and stuccoed it and wrote upon it. <span class=\"citation\">B. Bath. 60ᵇ</span> <span dir=\"rtl\">אין מסיידין ואין מְכַיְּירִין וכ׳</span> we must not decorate our rooms with plaster, panels and paintings in these days (after the destruction of the Temple); <span class=\"citation\">Tosef. ib. II, 17</span>.—Part. pass. <span dir=\"rtl\">מְכוּיָּיר</span>, f. <span dir=\"rtl\">מְכוּיֶּירֶת</span>. Ib.</div>","alt":["(כִּיד)"]},"12480":{"h":"כירבי","r":"K00618","html":"<div class=\"sense\">, <span class=\"citation\">Y. Kil. I, 27ᵃ</span> bot. <span dir=\"rtl\">כ׳ לבנון</span>, read: <a href=\"#\" data-headword=\"כְּרִיסוֹלָכַנוֹן\">כְּרִיסוֹלָכַנוֹן</a>.</div>","alt":[]},"12481":{"h":"כֵּירָה","r":"K00619","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>a circle</i>, esp. <i>banquet</i>. <span class=\"citation\">B. Bath. 75ᵃ</span> (expl. <span dir=\"rtl\">יכרו</span> <span class=\"citation\">Job XL, 30</span>, with ref. to <span class=\"citation\">II Kings VI, 23</span>) <span dir=\"rtl\">אין כ׳ אלא סעודה</span> <i>kerah</i> means banquet.</div>","alt":["כֵּרָה"]},"12482":{"h":"כִּירָה I","r":"K00620","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּרָה\">כָּרָה</a>) </div><div class=\"sense\"><b>1)</b> <i>digging, making a pit</i>. Mekh. Mishp., N’zik., s. 11 (prob. to be read: <a href=\"#\" data-headword=\"כְּרִיָה\">כְּרִיָּה</a>).</div><div class=\"sense\"><b>—2)</b>  [<i>selecting</i>,] <i>buying, sale</i>. <span class=\"citation\">R. Hash. 26ᵃ</span> <span dir=\"rtl\">היו קורין למכירה כ׳</span> (in the sea-towns) I heard them call a sale <i>kirah</i> (which accounts for <span dir=\"rtl\">כריתי</span>, <span class=\"citation\">Gen. L, 5</span>); <span class=\"citation\">Sot. 13ᵃ</span></div>","alt":[]},"12483":{"h":"כִּירָה II","r":"K00621","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>a portable stove on feet</i>, with caves for two pots, v. <a href=\"#\" data-headword=\"כּוּפָּח\">כּוּפָּח</a>. <span class=\"citation\">Sabb. 38ᵇ</span>. <span class=\"citation\">Ib. III, 1</span>. <span class=\"citation\">Ib. 138ᵇ</span>, v. <a href=\"#\" data-headword=\"יָרֵךְ\">יָרֵךְ</a>. <span class=\"citation\">Kel. VI, 1</span> <span dir=\"rtl\">העושה שתי … כ׳</span> if one improvises a stove by means of two stones; <span class=\"citation\">Tosef. Kel. B. Kam. V, 3</span> <span dir=\"rtl\">כרה</span> ed. Zuck. (R. S. to <span class=\"citation\">Kel. VI, 4</span> <a href=\"#\" data-headword=\"כֵּירָה\">כירה</a>). <span class=\"citation\">Kel. VI, 2</span> <span dir=\"rtl\">כִּירַת הטבחים</span> the butchers’ stove (improvised with several stones). <span class=\"citation\">Y. Bets. II, 61ᶜ</span> top <span dir=\"rtl\">בשאה שכִּירָתְךָ סתומה</span> at a time when thine own (private) stove is closed (when you are not permitted to cook), opp. <span dir=\"rtl\">כירת רבך</span> thy Master’s stove (the altar); Bab. <span class=\"citation\">Bets. 20ᵇ</span>; <span class=\"citation\">Tosef. Ḥag. II, 10</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"*כִּירִים\">כִּירִים</a>. <span class=\"citation\">Kel. VI, 3</span> <span dir=\"rtl\">שתי כ׳</span> two fire-places.—Dual form: <a href=\"#\" data-headword=\"כִּירַיִם\">כִּירַיִים</a>, <a href=\"#\" data-headword=\"כִּירַיִם\">כִּירַיִם</a>. <span class=\"citation\">Sabb. III, 2</span>. <span class=\"citation\">B. Mets. VIII, 7</span>. Sifra Sh’mini Mill. <span dir=\"rtl\">לא … אלא מן הכ׳</span> they brought the fire in from the (private) stove; <span class=\"citation\">Lev. R. s. 20</span>; Tanḥ. Aḥaré 6; ed. Bub. 7 <span dir=\"rtl\">מבית</span> (<a href=\"#\" data-headword=\"ה\">ה</a>)<a href=\"#\" data-headword=\"כ׳\">כ׳</a> from the kitchen. <span class=\"citation\">Ab. d’R. N. ch. XII</span> <span dir=\"rtl\">כ׳ זה טמא</span> (Var. <span dir=\"rtl\">כ׳ זו טמאה</span>; v. II Vers., ed. Schechter, ch. XXVIII) this stove is unclean.</div>","alt":[]},"12484":{"h":"כִּירָוַון","r":"K00622","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּרְיָא I\">כַּרְיָא</a></div>","alt":["כֵּירָוָותָא"]},"12485":{"h":"כִּירוֹמָנִיקְיָא","r":"K00623","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (χειρομάνικα = μανίκια, S.) [<i>tight sleeves</i>,] <i>handcuffs, manacles</i> (cmp. Lat. manicae). <span class=\"citation\">Targ. II Chr. XXXVI, 6</span> (a gloss to <span dir=\"rtl\">שושלון דנחשא</span>). <span class=\"citation\">Ib. XXXIII, 11</span> <span dir=\"rtl\">כירומנק׳</span> ed. Lag. (h. text <span dir=\"rtl\">חחים</span>);—Y. Snh. X, 28ᶜ bot.; Ruth. R. to II, 14 <span dir=\"rtl\">כירומניקאה</span>; Pesik. Shub. p. 162ᵃ <span dir=\"rtl\">כידי ומנקייה</span> (corr. acc.). <span class=\"citation\">Cant. R. to IV, 8</span> (ref. to <span dir=\"rtl\">זקים</span>, <span class=\"citation\">Is. XLV, 14</span>) <a href=\"#\" data-headword=\"קרקומניקיא\">קרקומניקיא</a>, Bxt. <span dir=\"rtl\">כרקומ׳</span> (corr. acc.).</div>","alt":[]},"12486":{"h":"כִּירְחָא","r":"K00624","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כֻּרְהָנָא\">כֻּרְהָנָא</a></div>","alt":[]},"12487":{"h":"כֵּירִי","r":"K00625","html":"<div class=\"sense\"> (χαῖρε, imper. of χαίρω) <i>hail!</i> <span class=\"citation\">Gen. R. s. 89</span> (play on <a href=\"#\" data-headword=\"כַּר\">כר</a>, <span class=\"citation\">Is. XXX, 23</span>) (when thy cattle has pasture) <span dir=\"rtl\">כ׳ כ׳ מרובה בעולם</span> Ar. ‘hail! hail!’ is largely heard in the world (good-will prevails); [ed. <span dir=\"rtl\">כ׳ עבד קירי אדון</span>; ‘Rashi’: <span dir=\"rtl\">כ׳ קירי מרובה בעולם</span> (χαῖρε κύριε, hail, O Lord &amp;c.), misinterpreting: <span dir=\"rtl\">כ׳ עבד קירי אדון</span> (v. <a href=\"#\" data-headword=\"כִּירִי I\">next w.</a>), which gloss came into the text of the ed. in place of the original passage]. Tanḥ. Mikk. 9 א&quot;ל קירי כ׳ Mus. (ed. <a href=\"#\" data-headword=\"בָּרָא I\">ברא</a>; ed. Bub. 11 <a href=\"#\" data-headword=\"בַּדָּא I\">בדא</a>; corr. acc.), he said to him, hail mylord!</div>","alt":[]},"12488":{"h":"כִּירִי I","r":"K00626","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (χείριε, vocat. of χείριος = ὑποχείριος) <i>in the control of, captive</i>. <span class=\"citation\">Erub. 53ᵇ</span> (of a Galilean woman who wished to say <span dir=\"rtl\">קירי</span>, κύριε, O Lord) <span dir=\"rtl\">מרי כ׳</span>.—<span class=\"citation\">Ḥull. 139ᵇ</span> (of doves which uttered a sound like <span dir=\"rtl\">קירי קירי</span>) <span dir=\"rtl\">אמרה … קירי בירי</span> (corr. acc.) said she, blind one, say rather κύριε χείριε lord slave (an allusion to Herod the Great, v. <a href=\"#\" data-headword=\"הַרְדְּסִיאוֹת\">הַרְדְסִיאוֹת</a>).—[<span class=\"citation\">Gen. R. s. 89</span> <span dir=\"rtl\">כ׳ עבד קירי אדון</span>, v. <a href=\"#\" data-headword=\"כֵּירִי\">preced. w.</a></div>","alt":[]},"12489":{"h":"*כִּירִי II","r":"K00627","html":"<div class=\"sense\">, <span dir=\"rtl\">כ׳ רָם</span> <i>Kiri Ram</i>, an imitation of a musical sound for beating time for dancers. <span class=\"citation\">Num. R. s. 4</span> (expl. <span dir=\"rtl\">מכרכר</span>, <span class=\"citation\">II Sam. VI, 14</span>) <span dir=\"rtl\">שהיה מקיש … ואומר כ׳ רם</span> he clapped his hands and kalled <i>kiri ram</i>.</div>","alt":[]},"12490":{"h":"כירי","r":"K00628","html":"<div class=\"sense\">, <span class=\"citation\">Ḥull. 62ᵇ</span> Ar., v. <a href=\"#\" data-headword=\"כּוֹרָא\">כּוֹרָא</a></div>","alt":[]},"12491":{"h":"כִּירַיָּא","r":"K00629","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Kiraya near Beth Sekhel</i>. <span class=\"citation\">Targ. Y. I Num. XXXIV, 9</span> (v. Hildesh. Beitr., p. 46, sq.).</div>","alt":["כ׳ דבית סכל"]},"12492":{"h":"כִּירְיוֹ","r":"K00630","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּרִי\">כְּרִי</a></div>","alt":["כִּירְייוֹ"]},"12493":{"h":"כִּירַיִם","r":"K00631","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּירָה II\"><span dir=\"rtl\">כִּירָה</span> II</a></div>","alt":[]},"12494":{"h":"*כִּירִים","r":"K00632","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"><i>iron tools for crowding olives into the vat</i> (Maim.; cmp. <a href=\"#\" data-headword=\"כְּרִי\">כְּרִי</a>). <span class=\"citation\">Kel. XII, 8</span> (some ed. <a href=\"#\" data-headword=\"כורים\">כורים</a>, ed. Dehr. <a href=\"#\" data-headword=\"כידים\">כידים</a>; Ar. <a href=\"#\" data-headword=\"כידים\">כידין</a>, Var. <a href=\"#\" data-headword=\"כִּרְכּוּר\">כיר׳</a>, expl. = <a href=\"#\" data-headword=\"*עֲכִירִים\">עֲכִירִים</a> q. v.—R. Hai Gaon quotes a Var. <a href=\"#\" data-headword=\"כִּידוֹן I\">כידון</a>); [<span class=\"citation\">Tosef. Kel. B. Bath. VII, 12</span> <span dir=\"rtl\">עתידין</span>, some ed. <span dir=\"rtl\">עמידין</span>, <a href=\"#\" data-headword=\"*עֲכִירִים\">עכירים</a>].</div>","alt":["כִּירִין"]},"12495":{"h":"כִּירְכּוּר","r":"K00633","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּרְכּוּר\">כִּרְכּוּר</a></div>","alt":[]},"12496":{"h":"כִּירְכֵּם","r":"K00634","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"כִּרְכֵּב\">כִּרְכֵּ׳</a>.</div>","alt":["כִּירְכֵּר"]},"12497":{"h":"כִּירְצָא","r":"K00635","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּרְצָא\">כִּרְצָא</a></div>","alt":[]},"12498":{"h":"כִּישׁ","r":"K00636","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"כִּשְׁכֵּשׁ\">כִּשְׁכֵּשׁ</a>) <i>kish</i>, an imitation of a clapping sound. <span class=\"citation\">B. Mets. 85ᵇ</span> (prov.) <span dir=\"rtl\">אסתירא … כ׳ כ׳ קריא</span> Ms. H. a. Ar. (ed. <a href=\"#\" data-headword=\"קִישׁ I\">קִישׁ</a>) a coin in a bottle cries <i>kish kish</i> (clappers, i.e. an ignorant man boasts of what little knowledge he has).</div>","alt":[]},"12499":{"h":"כִּישָׁא","r":"K00637","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כּוּשׁ I\">כוש</a> or <span dir=\"rtl\">כנש</span>, cmp. <a href=\"#\" data-headword=\"כִּיס\">כיס</a>) </div><div class=\"sense\"><b>1)</b> <i>bunch</i>. <span class=\"citation\">B. Bath. 146ᵇ</span> <span dir=\"rtl\">כ׳ דירקא</span> a bunch of vegetables. <span class=\"citation\">Kidd. 45ᵇ</span>. <span class=\"citation\">Ḥull. 105ᵇ</span> <span dir=\"rtl\">מכ׳ דאסר וכ׳</span> out of a bunch which the gardener has tied. <span class=\"citation\">Sabb. 140ᵇ</span> <span dir=\"rtl\">כ׳ כי כ׳</span> (Ms. M. <a href=\"#\" data-headword=\"ב׳\">ב׳</a>, incorr.) a bunch is a bunch, v. <a href=\"#\" data-headword=\"אוּרְכָּא\">אוּרְכָּא</a>. <span class=\"citation\">Ib.</span> <a href=\"#\" data-headword=\"כִּישְׁתָּא\">כִּישְׁתָּא</a> fem. (Ms. M. <a href=\"#\" data-headword=\"בִּישׁ I\">בישא</a>, corr. acc.; Ar. <a href=\"#\" data-headword=\"הוּצָא I\">הוּצָא</a>).—</div><div class=\"sense\"><b>*2)</b> <i>a pouch</i> (of a garment).—Pl. <span dir=\"rtl\">כִּישֵׁי</span>. Ib. 147ᵃ Ar. (Ms. M. <a href=\"#\" data-headword=\"כּוּשִׁי\">כּוּשֵׁי</a>), v. <a href=\"#\" data-headword=\"כִּיס ²\">כִּיסָא</a> a. <a href=\"#\" data-headword=\"מַרְזֵב\">מַרְזֵב</a>.—[Ib. 108ᵇ, v. <a href=\"#\" data-headword=\"כָּשׁוֹרָא\">כָּשׁוֹרָא</a>.]</div>","alt":[]},"12500":{"h":"כִּישּׁוּף","r":"K00638","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּשַׁף\">כָּשַׁף</a>) <i>sorcery, witchcraft</i>. <span class=\"citation\">Snh. 56ᵇ</span> <span dir=\"rtl\">אף על הכ׳</span> the prohibition of sorcery is also included in the Noachidic laws (v. <a href=\"#\" data-headword=\"נֹחַ\">נֹחַ</a>). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">פרשת כ׳</span> (Ms. M. a. Rashi <a href=\"#\" data-headword=\"מְכַשֵּׁף\">מכשף</a>) the passage referring to sorcery (<span class=\"citation\">Deut. XVIII, 10</span>, sq.). <span class=\"citation\">Pesik. R. s. 14</span> לא כ׳ ולא כשפים וכ׳ I applied neither sorcery nor witchcraft; a. e.</div>","alt":["כִּשּׁ׳"]},"12501":{"h":"כִּישׁוּת","r":"K00639","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"כָּשׁוּת\">כָּשׁוּת</a></div>","alt":[]},"12502":{"h":"כִּישְׁרָא","r":"K00640","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כָּשׁוֹרָא\">כָּשׁוֹרָא</a></div>","alt":[]},"12503":{"h":"כִּישָּׁרוֹן","r":"K00641","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>virtue, fitness</i>. <span class=\"citation\">Num. R. s. 3</span> (ref. to <span dir=\"rtl\">בכושרות</span>, <span class=\"citation\">Ps. LXVIII, 7</span>) <span dir=\"rtl\">בכ׳ אין כתיב כאן וכ׳</span> it is not written here ‘in fitness’ but <i>bakkosharoth</i>, that means through the merits of noble and worthy women.</div>","alt":["כִּשָּׁ׳"]},"12504":{"h":"כִּישְׁתָּא","r":"K00642","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּישָׁא\">כִּישָׁא</a></div>","alt":[]},"12505":{"h":"כִּיתָּא I","r":"K00643","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּתַת\">כְּתַת</a>) <i>beating</i> (<i>of flax</i>). <span class=\"citation\">Sabb. 140ᵇ</span>, v. <a href=\"#\" data-headword=\"כִּיתּוּנִיתָא\">כִּיתּוּנִיתָא</a>.</div>","alt":[]},"12506":{"h":"כִּיתָּא II","r":"K00644","html":"<div class=\"sense\"><i>band</i>, v. <a href=\"#\" data-headword=\"כִּתָּא\">כִּתָּא</a>.</div>","alt":[]},"12507":{"h":"כִּיתָּה","r":"K00645","html":"<div class=\"sense\"> f. <a href=\"#\" data-headword=\"כִּיתָּא II\">same</a>, v. <a href=\"#\" data-headword=\"כַּתְּ\">כַּתְּ</a></div>","alt":[]},"12508":{"h":"כִּיתּוּנָא","r":"K00646","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(v. <a href=\"#\" data-headword=\"כִּיתַּן\">כִּיתַּן</a>) = h. <a href=\"#\" data-headword=\"כְּתוֹנֶת\">כֻּתּוֹנֶת</a>, <i>linen coat</i>, in gen. <i>undergarment, shirt</i>. <span class=\"citation\">Targ. O. Gen. XXXVII, 3</span>; a. fr.—<span class=\"citation\">R. Hash. 27ᵇ</span> <span dir=\"rtl\">דהפכיה ככ׳</span> that he turned it like a shirt (the inside outside). <span class=\"citation\">Ned. 55ᵇ</span> <span dir=\"rtl\">כ׳ דצלא</span> a leather coat (v. <a href=\"#\" data-headword=\"אִיסְקוֹרטְיָא\">אִיסְקוֹרְטְיָא</a>). <span class=\"citation\">Ḥull. 46ᵃ</span>, v. <a href=\"#\" data-headword=\"וְרַד\">וְרַד</a>; a. e.—Pl. <span dir=\"rtl\">כִּיתּוּנִין</span>, <a href=\"#\" data-headword=\"כִּיתּוּנְתָּא\">כִּיתּוּנַיָּא</a>, <a href=\"#\" data-headword=\"כִּיתּוּנָא\">כִּתּ׳</a>. <span class=\"citation\">Targ. Ex. XXVIII, 40</span>. <span class=\"citation\">Targ. Is. III, 22</span>; a. fr.</div>","alt":["כִּתּ׳"]},"12509":{"h":"כִּיתּוּנִיתָא","r":"K00647","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (diminut. of <a href=\"#\" data-headword=\"כִּיתּוּנָא\">preced.</a>) <i>fine linen shirt</i>. <span class=\"citation\">Sabb. 140ᵇ</span> <span dir=\"rtl\">דזבן כ׳ וכ׳</span> he who wishes to buy &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מאי כ׳ כיתנא נאה</span> Ms. O. (not <a href=\"#\" data-headword=\"כִּיתָּנִיתָא\">כיתניתא</a>) what is a <i>k</i>.?—Fine flax; ed. <span dir=\"rtl\">כיתא נאה</span> ‘fine beating’, v. <a href=\"#\" data-headword=\"כִּיתָּא I\"><span dir=\"rtl\">כִּיתָּא</span> I</a>.—Pl. <span dir=\"rtl\">כִּיתְוַונְיָיתָא</span>. <span class=\"citation\">Ib.ᵃ</span> bot. Ms. M. (ed. <a href=\"#\" data-headword=\"כִּיתָּנִיתָא\">כִּיתָּנִיתָא</a> q. v.).</div>","alt":[]},"12510":{"h":"כִּיתּוּנְתָּא","r":"K00648","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּיתָּנִיתָא\">כִּיתָּנִיתָא</a></div>","alt":[]},"12511":{"h":"כִּיתּוֹת","r":"K00649","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּתְּ\">כַּתְּ</a></div>","alt":["כִּיתִּים"]},"12512":{"h":"כִּיתְמָא","r":"K00650","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּתְמָא\">כִּתְמָא</a></div>","alt":[]},"12513":{"h":"כִּיתַּן","r":"K00651","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">כתן</span>, cmp. <span dir=\"rtl\">כתת</span>, a. <a href=\"#\" data-headword=\"כּוּנְתָּא\">כּוּנְתָּא</a>) [<i>beaten</i>,] <i>flax</i>. <span class=\"citation\">Targ. Deut. XXII, 11</span>. <span class=\"citation\">Targ. Ex. IX, 31</span>; a. fr.—<span class=\"citation\">Y. Snh. X, 29ᵃ</span> bot. (in Hebr. dict.) <span dir=\"rtl\">זרעו חטים וכ׳</span> sow wheat and flax. <span class=\"citation\">Yoma 71ᵇ</span> <span dir=\"rtl\">מאי … כ׳ הוא</span> what proof is there that <i>shesh</i> means flax?; <span class=\"citation\">ib.</span> <span dir=\"rtl\">כ׳ אגב לקותיה וכ׳</span> flax splits into branches only when beaten (while it grows in plain stalks); <span class=\"citation\">Zeb. 18ᵇ</span>. <span class=\"citation\">B. Mets. 29ᵇ</span> bot. <span dir=\"rtl\">כ׳ רומיתא</span> (fem.; Ar. a. M. R. <a href=\"#\" data-headword=\"רוֹמָאָה\">רומאה</a>) Roman (fine and expensive) linen; <span class=\"citation\">Ḥull. 84ᵇ</span>. <span class=\"citation\">Ib. 51ᵇ</span> <span dir=\"rtl\">כ׳ דעביד בטוני</span> flax-stalks in bundles. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כ׳ דדייק וכ׳</span> flax which has been pounded &amp;c., v. <a href=\"#\" data-headword=\"נְפַץ\">נְפַץ</a>. <span class=\"citation\">Y. Sabb. II, beg. 4ᶜ</span> (expl. <a href=\"#\" data-headword=\"ירָוֹקָה\">יָרוֹקָה</a>) <span dir=\"rtl\">כ׳ דמיי</span> ‘water-flax’ (a sort of lichen); a. fr.—Pl. <span dir=\"rtl\">כִּיתָּנַיָּיא</span>. Ib. VII, 10ᵃ bot. <span dir=\"rtl\">ההן כ׳</span> (insert <span dir=\"rtl\">דעבד</span>) he who works in flax-stalks &amp;c., v. <a href=\"#\" data-headword=\"*אֲפַסְטִיתָה\">אֲפַסְטִיתָה</a>.</div>","alt":["(כִּיתָן","כִּיתְנָא)","כִּיתָּנָא","כִּת׳"]},"12514":{"h":"כיתנאי","r":"K00652","html":"<div class=\"sense\">, <span class=\"citation\">Y. Peah I, 16ᵃ</span>, v. <a href=\"#\" data-headword=\"כותנאי\">כותנאי</a></div>","alt":[]},"12515":{"h":"כִּיתָּנִיתָא","r":"K00653","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> collect. noun (<a href=\"#\" data-headword=\"כיתנאי\">preced.</a> wds.) <i>washed linen clothes, underwear</i>. <span class=\"citation\">Sabb. 140ᵃ</span> <span dir=\"rtl\">כסכוסי כ׳</span> ed. (Or Zar. Sabb., end <a href=\"#\" data-headword=\"כִּיתּוּנָא\">כיתונא</a>, R. H. quot. ib. <span dir=\"rtl\">כִּתַּנְיָאתָא</span> pl., Ms. M. <span dir=\"rtl\">כִּיתְוַונְיָיתָא</span>, pl. of <a href=\"#\" data-headword=\"כִּיתּוּנִיתָא\">כִּיתּוּנִיתָא</a>; Alf. a. Ash. <a href=\"#\" data-headword=\"כִּיתּוּנְתָּא\">כִּיתּוּנְתָּא</a>, <a href=\"#\" data-headword=\"כְּתִישָׁא\">כִּתּוּ׳</a>) to rub the starch out of linen underwear; <span dir=\"rtl\">לרכוכי כ׳ וכ׳</span> he intends only to soften the linen &amp;c. Ib. bot. <span dir=\"rtl\">האי כ׳ וכ׳</span> (Or Zer. l. c. a. Ash. <a href=\"#\" data-headword=\"כִּיתּוּנָא\">כיתונא</a>, v. Rabb. D. S. a. l. for Var. lect.). <span class=\"citation\">Y. Snh. II, 20ᶜ</span> bot. <a href=\"#\" data-headword=\"אותניתיה\">אותניתיה</a> read: <span dir=\"rtl\">כִּיתָּנִיתֵיה</span> (= <span dir=\"rtl\">חלוקא דכיתנא</span> ib.) his linen garments.</div>","alt":["כִּיתְ׳"]},"12516":{"h":"כִּיתְרָא","r":"K00654","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּתַב II\"><span dir=\"rtl\">כְּתַר</span> II</a></div>","alt":[]},"12517":{"h":"כָּךְ","r":"K00655","html":"<div class=\"sense\"><i>thus, so.</i> <span class=\"citation\">Ab. IV, 5</span> <span dir=\"rtl\">וכך הי׳ הלל וכ׳</span> and even so (in the same sense) did Hillel say. <span class=\"citation\">B. Kam. 61ᵃ</span> <span dir=\"rtl\">כך מקובלני וכ׳</span> such is my tradition from &amp;c. <span class=\"citation\">Tosef. Keth. V, 9</span> <span dir=\"rtl\">כך תתנו וכ׳</span> even so much (and no more) may you have wherewith to endow your daughters; Bab. <span class=\"citation\">Snh. 66ᵇ</span>; <span class=\"citation\">ib. 65ᵃ</span> <span dir=\"rtl\">כך תפסקו</span>; Y. ib. V, end, 30ᶜ <a href=\"#\" data-headword=\"כָּכָה\">כָּכָה</a>; a. fr.—כך וכך <i>so and so many, a certain number, date</i> &amp;c. <span class=\"citation\">R. Hash. 18ᵇ</span> <span dir=\"rtl\">בשנת כך וכך ליוחנן וכ׳</span> in the year—of John &amp;c.; a. fr.—<span dir=\"rtl\">אחר כך</span>, v. <a href=\"#\" data-headword=\"אַחַר\">אַחַר</a>.—<a href=\"#\" data-headword=\"לְכָךְ\">לְכָךְ</a> (cmp. b. h. <a href=\"#\" data-headword=\"לָכֵן\">לָכֵן</a>) <i>for such a purpose, therefore.</i> <span class=\"citation\">Ab. II, 8</span>, v. <a href=\"#\" data-headword=\"יָצַר\">יָצַר</a>. <span class=\"citation\">Num. R. s. 4</span>, beg. <span dir=\"rtl\">ל׳ דַּקְדֵּק וכ׳</span> therefore be exact in recording the numbers &amp;c.; a. fr.—V. <a href=\"#\" data-headword=\"הִילְכָךְ\">הִילְכָךְ</a>, <a href=\"#\" data-headword=\"לְפִיכָךְ\">לְפִיכָךְ</a>.</div>","alt":[]},"12518":{"h":"כַּכָּא","r":"K00656","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (collect. noun), pl. <a href=\"#\" data-headword=\"כְּכָי\">כַּכֵּי</a> (<span dir=\"rtl\">אכך</span> or <a href=\"#\" data-headword=\"חָכַךְ I\">חכך</a>, dropped guttural; cmp. <a href=\"#\" data-headword=\"*אַכָּכָא\">אַכָּכָא</a>) <i>molars</i>, in gen. <i>teeth</i>. <span class=\"citation\">Targ. Jud. XV, 19</span> ed. Lag., a. Kimḥi Var. (ed. <a href=\"#\" data-headword=\"כִּיפְתָא\">כֵּיפָא</a>, h. text <span dir=\"rtl\">מכתש</span>). <span class=\"citation\">Targ. Y. Num. XXI, 35</span> <span dir=\"rtl\">כַּכֵּיה ושיניה</span> his molars and his (front) teeth. <span class=\"citation\">Ib. XI, 33</span>; a. fr.—<span class=\"citation\">Pes. 113ᵃ</span> <span dir=\"rtl\">לא תעקר כ׳</span> never have a molar tooth extracted. <span class=\"citation\">Gitt. 69ᵃ</span> <span dir=\"rtl\">לכ׳</span> for pain of the molars. <span class=\"citation\">B. Kam. 92ᵇ</span> (prov.) <span dir=\"rtl\">שיתין … לכ׳ דקל וכ׳</span> sixty pains befall the teeth of him who hears his neighbor’s sounds (at meals) and is himself not permitted to eat (not being invited). <span class=\"citation\">Ab. Zar. 28ᵃ</span>; a. e.—<span dir=\"rtl\">כ׳ דאקלידא</span>, v. <a href=\"#\" data-headword=\"אַקְלִידָא\">אַקְלִידָא</a>.—<span class=\"citation\">B. Bath. 167ᵃ</span> כַּכֵּיה דבי&quot;ת Ar., Ms. H. (Ms. M. <span dir=\"rtl\">בבי</span>, v. Rabb. D. S. a. l. note; ed. <span dir=\"rtl\">גַּגֵּיה דבי&quot;ת וכרעיה</span>) the teeth, the upper and the lower horizontal lines of the letter Beth.—[כַּכֵּי <i>cakes</i>, v. <a href=\"#\" data-headword=\"כַּעֲכָא\">כַּעֲכָא</a>.]</div>","alt":[]},"12519":{"h":"כֹּכָב","r":"K00657","html":"<div class=\"sense\">, v. sub <span dir=\"rtl\">כּוֹכ׳</span>.</div>","alt":["כֹּכְבָא"]},"12520":{"h":"ככדיתא","r":"K00658","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*כַּכָּרִיתָא\">כַּכָּרִיתָא</a></div>","alt":[]},"12521":{"h":"כָּכָה","r":"K00659","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כָּךְ\">כָּךְ</a></div>","alt":[]},"12522":{"h":"כְּכָי","r":"K00660","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (= <span dir=\"rtl\">כיכי</span>, √<a href=\"#\" data-headword=\"כַּו\">כו</a>, cmp. <a href=\"#\" data-headword=\"כַּוָּוא\">כַּוָּא</a>) [<i>small apertures, meshes</i>,] <i>spiderweb;</i> trnsf. <i>the web-like marrow of reeds.</i> Ohol. XIII, 5 <span dir=\"rtl\">כ׳ שיש בה ממש</span> substantial spiderweb; [oth. opin.:] substantial reed marrow. <span class=\"citation\">Kel. XVII, 17</span> <span dir=\"rtl\">עד שיוציא את כל הכ׳</span> (Var. <a href=\"#\" data-headword=\"כבאי\">כבאי</a>, read <a href=\"#\" data-headword=\"כְּכָי\">כְּכַאי</a>) until he has taken out the entire marrow; <span class=\"citation\">Tosef. Kel. B. Mets. VII, 12</span> <a href=\"#\" data-headword=\"כ׳\">כ׳</a> quoted by R. s. to Kel. l. c. (ed. <a href=\"#\" data-headword=\"זָכָר\">זָכָר</a>).</div>","alt":["כְּכָיי"]},"12523":{"h":"*כֹּכְלָא","r":"K00661","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (κόχλος) <i>purple-fish</i> (murex); trnsf. <i>purple</i>, esp. <i>the purple stripe on the tunica, a badge of nobility</i>. Y’lamd. to Gen. XXV, 23; 25, quot. in Ar., corresp. to <a href=\"#\" data-headword=\"צִיצִית\">צִיצִית</a> on the Jewish garment.</div>","alt":[]},"12524":{"h":"*כָּכְלַן","r":"K00662","html":"<div class=\"sense\">, m. (<a href=\"#\" data-headword=\"*כֹּכְלָא\">preced.</a>) <i>purple cloak</i>. <span class=\"citation\">Targ. O. Gen. XXV, 25</span> ed. Berl. (oth. ed. <span dir=\"rtl\">כִּגְלִים</span>, codices <span dir=\"rtl\">כִּגְלָם</span>, v. Berl. Targ. O. II, p. 9); Targ. Y. II ib. <span dir=\"rtl\">כִּבְלַן</span> (corr. acc., or <span dir=\"rtl\">כְּכִילַן</span>).</div>","alt":[]},"12525":{"h":"ככר","r":"K00663","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Prov. XVII, 25</span> מככיר Ms., v. <a href=\"#\" data-headword=\"כְּבַד\">כְּבַד</a> <i>Af</i>.</div>","alt":[]},"12526":{"h":"כִּכָּר","r":"K00664","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּרְכֵּר\">כִּרְכֵּר</a>) [<i>circle</i>,] </div><div class=\"sense\"><b>1)</b> <i>district</i>. <span class=\"citation\">Gen. R. s. 41</span> <span dir=\"rtl\">כל ערי הכ׳</span> all the towns of the (Jordan) district.</div><div class=\"sense\"><b>—2)</b> <i>loaf</i>. <span class=\"citation\">Erub. VIII, 2</span>; <span class=\"citation\">Kel. XVII, 11</span> <span dir=\"rtl\">מכ׳ בפונדיון וכ׳</span> bread for two meals consists of a loaf bought for a <i>dupondium</i> when four S’ah of wheat are worth one Sela; ib. <span dir=\"rtl\">משתי ידות לכ׳ וכ׳</span> of two thirds of a loaf three of which represent a Kab of grain. <span class=\"citation\">Sifré Deut. 40</span> <span dir=\"rtl\">כ׳ ומקל ירדו וכ׳</span> bread and stick (reward and punishment) came down from heaven tied together; a. v. fr.—Pl. <span dir=\"rtl\">כִּכָּרִים</span>, <span dir=\"rtl\">כִּכָּרוֹת</span>. <span class=\"citation\">Toh. V, 6</span> <span dir=\"rtl\">שני כ׳</span>. <span class=\"citation\">Ber. 39ᵇ</span> <span dir=\"rtl\">שתי כ׳</span>; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>Kikkar</i>, a weight of silver or gold, <i>talent</i> (= 3000 Shekel, v. Zuckerm. Talm. Münz. p. 7). <span class=\"citation\">Ab. Zar. 44ᵃ</span> <span dir=\"rtl\">שוה כִּכַּר זהב</span> worth a gold talent; a. fr.—Pl. <span dir=\"rtl\">כִּכָּרִים</span>, constr. <span dir=\"rtl\">כִּכְּרֵי</span>. <span class=\"citation\">Y. Shek. VI, 50ᵇ</span> top.</div>","alt":[]},"12527":{"h":"כִּכְּרָא","r":"K00665","html":"<div class=\"sense\"><b>1)</b> <i>talent</i>. <span class=\"citation\">Targ. O. Ex. XXV, 39</span>; a. e.—Pl. <span dir=\"rtl\">כִּכְּרִין</span>, <span dir=\"rtl\">כִּכְּרֵי</span>, <a href=\"#\" data-headword=\"כִּכְּרָא\">כַּ׳</a>. <span class=\"citation\">Ib. XXXVIII, 27</span>; a. e.—<span class=\"citation\">Bekh. 5ᵃ</span> <span dir=\"rtl\">כללי קחשיב בכ׳ וכ׳</span> large round sums the Bible counts by Kikkars, units of Kikkars it does not (but counts by Shekels).</div><div class=\"sense\"><b>—2)</b> <i>ball</i>.—<i>Pl.</i> as ab. <span class=\"citation\">B. Mets. 86ᵃ</span>, v. <a href=\"#\" data-headword=\"כּוֹכָב ²\">כּוֹכְבָא</a>.</div>","alt":["כַּ׳"]},"12528":{"h":"*כַּכָּרִיתָא","r":"K00666","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כִּכְּרָא\">preced.</a>) [<i>loaf</i>,] <i>honey-comb</i>. <span class=\"citation\">Targ. Prov. V, 3</span> ed. Lag. (Ar. a. Lev. <a href=\"#\" data-headword=\"ככדיתא\">ככדיתא</a>, v. Koh. Ar. Compl. II, p. 221); a. e., v. <a href=\"#\" data-headword=\"כַּבְרִיתָא I\"><span dir=\"rtl\">כַּבְרִיתָא</span> I</a></div>","alt":[]},"12529":{"h":"ככרתו","r":"K00667","html":"<div class=\"sense\">, <span class=\"citation\">Y. Succ. II, 52ᵈ</span> bot., v. <a href=\"#\" data-headword=\"כְּוֶורֶת\">כְּוֶורֶת</a></div>","alt":[]},"12530":{"h":"כֹּל","r":"K00668","html":"<div class=\"sense\">, constr. <a href=\"#\" data-headword=\"כָּל\">כָּל</a> (b. h.; <a href=\"#\" data-headword=\"כָּלַל\">כָּלַל</a>) <i>all, every one</i>. <span class=\"citation\">Sot. 5ᵃ</span> <span dir=\"rtl\">הקב&quot;ה הניח כל הרים וכ׳</span> the Lord passed over all mountains and hills and caused his Presence to rest on Sinai. <span class=\"citation\">Ib.</span> (ref. to <span dir=\"rtl\">ככל</span> <span class=\"citation\">Job XXIV, 24</span>) <span dir=\"rtl\">כאברהם … בַּכֹּל מִכֹּל כֹּל</span> like Abraham, Isaac and Jacob of whom is written ‘with everything’ &amp;c. (<span class=\"citation\">Gen. XXIV, 1</span>; <span class=\"citation\">XXVII, 33</span>; <span class=\"citation\">XXXIII, 11</span>).—<span class=\"citation\">Ḥull. I, 1</span> <span dir=\"rtl\">הַכֹּל שוחטין וכ׳</span> all persons are competent to slaughter &amp;c.; <span dir=\"rtl\">וכוּלָּן וכ׳</span> but all those (mentioned as unfit), if they &amp;c. Ib. 2 <span dir=\"rtl\">ובַכֹּל שוחטין וכ׳</span> and you may slaughter with any cutting tool except &amp;c. <span class=\"citation\">Tem. I, 1</span>; a. v. fr.—<span dir=\"rtl\">דברי הכל</span> the words of all, (<i>it is</i>) <i>the unanimous opinion, all agree</i>. <span class=\"citation\">Bets. 9ᵃ</span> <span dir=\"rtl\">ד׳ ה׳ מותר</span> all agree that it is permitted; a. fr.—אין … כל עיקר <i>not at all</i>. <span class=\"citation\">Y. Dem. I, 21ᵈ</span> <span dir=\"rtl\">אינו מפריש כל עיקר</span> he does not set aside at all; a. fr.—Y. Shebi. VIII, beg. 37ᵈ, a. e. <span dir=\"rtl\">לא הכל ממנו</span> it is not in his power to do so, v. <a href=\"#\" data-headword=\"הֵימ־\">הֵימ־</a>.—<span dir=\"rtl\">כָּל העולם כּוּלּוֹ</span> the whole world. <span class=\"citation\">Ber. 17ᵇ</span>; a. fr.—<span dir=\"rtl\">כל ה־</span>, <span dir=\"rtl\">כל ש־</span> <i>whosoever, whatsoever</i>. <span class=\"citation\">Gitt. 11ᵇ</span> <span dir=\"rtl\">כל האומר תנו וכ׳</span> whoever says, ‘Give you’ (a letter of emancipation &amp;c.), is considered as having said, Take possession (in behalf of the person concerned). <span class=\"citation\">Kidd. 43ᵇ</span> <span dir=\"rtl\">כל שאין יכולה וכ׳</span> whatever woman is incapable of guarding her letter of divorce, is incapable of being divorced. <span class=\"citation\">Ḥag. 4ᵇ</span>, v. <a href=\"#\" data-headword=\"יֵשׁ\">יֵשׁ</a>; a. v. fr.—<span dir=\"rtl\">כָּל שֶׁהוּא</span> whatever it be, i.e. <i>the smallest quantity</i>. <span class=\"citation\">Macc. 17ᵃ</span>, a. e. <span dir=\"rtl\">כ׳ ש׳ למכות</span> for punishment with lashes, the partaking of any quantity is sufficient, opp. <a href=\"#\" data-headword=\"כַּזַּיִת\">כזית</a>, v. <a href=\"#\" data-headword=\"זַיִת\">זַיִת</a>. <span class=\"citation\">Shebu. III, 1</span> <span dir=\"rtl\">ואכל כ׳ ש׳</span> and ate the least thing; a. v. fr.—<span dir=\"rtl\">כָּל שֶׁכֵּן</span> (abbr. <span dir=\"rtl\">כ&quot;ש</span>) there is every reason that it is even so, i.e. <i>so much the more, a matter of course</i>. <span class=\"citation\">Sabb. 63ᵃ</span> … <span dir=\"rtl\">אורך וכ&quot;ש וכ׳</span> there is length of life promised and, as a matter of course, wealth and honor; a. fr.—<span dir=\"rtl\">לא כ&quot;ש</span>, v. <a href=\"#\" data-headword=\"הַשְׁתָּא\">הַשְׁתָּא</a>.</div>","alt":[]},"12531":{"h":"כָּל","r":"K00669","html":"<div class=\"sense\"> ch., v. <a href=\"#\" data-headword=\"כּוֹל\">כּוֹל</a></div>","alt":["כֹּלָּא"]},"12532":{"h":"כָּלָא","r":"K00670","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כלי\">כלי</a></div>","alt":["כְּלָא"]},"12533":{"h":"כִּלְאָב","r":"K00671","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Chileab</i>, son of David. Tanḥ. Tol’doth 6 כ̇ל̇א̇ב̇ שהיה כ̇ול̇ו א̇ב̇ Kilab, he was entirely (like) his father; Y’lamd. to Gen. XXV, 19 <span dir=\"rtl\">כ̇איל̇ו א̇ב̇יו</span>.</div>","alt":[]},"12534":{"h":"כְּלָאָה","r":"K00672","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> , <i>extinction</i>. Lam. R., introd. (R. Joh. 1) <span dir=\"rtl\">לא תשוון כ׳ גמירא</span> do not exterminate (them) entirely.</div>","alt":[]},"12535":{"h":"כְּלָאֵי","r":"K00673","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּלֵי\"><span dir=\"rtl\">כְּלָא</span> I</a>), <span dir=\"rtl\">כ׳ בבא</span> <i>guard-house at the gate</i> (cmp. <a href=\"#\" data-headword=\"הַרְזִיקֵי\">הַרְזִיקֵי</a>). <span class=\"citation\">Ned. 91ᵇ</span> <span dir=\"rtl\">אִיתִּיב בכ׳ ב׳</span> he was placed in the guard-house &amp;c. [Ar. s. v. <a href=\"#\" data-headword=\"בָּב\">בב</a>: <a href=\"#\" data-headword=\"בלאי\">בלאי</a>, ed. Koh. <a href=\"#\" data-headword=\"כְּלָאֵי\">כלאי</a>.]</div>","alt":[]},"12536":{"h":"כִּלְאַיִם","r":"K00674","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> du. (b. h.; <a href=\"#\" data-headword=\"כְּלֵי\">כלא</a>, v. Ges. H. Dict. s. v.) <i>junction of two</i>, esp. <i>Kilayim, the forbidden junction of heterogeneous plants in the same field, of heterogeneous animals by hybridization or by harnessing together, of wool and linen in the same web</i> (<span class=\"citation\">Lev. XIX, 19</span>; <span class=\"citation\">Deut. XXII, 9</span> to 11). <span class=\"citation\">Gen. R. s. 82</span>; <span class=\"citation\">Y. Ber. VIII, 12ᵇ</span> top <span dir=\"rtl\">האש והכ׳ וכ׳</span> fire and hybrids (mules) although not having been created in the six days &amp;c. <span class=\"citation\">Kil. VIII, 1</span> <span dir=\"rtl\">כְּלָאֵי הכרם</span> mixed seeds in the vineyard. <span class=\"citation\">Ib. I, 1</span> <span dir=\"rtl\">אינם כ׳ זה בזה</span> are no forbidden junction. <span class=\"citation\">Ib. 9</span> <span dir=\"rtl\">משום כ׳</span> as coming under the law of K.—<span class=\"citation\">Tosef. ib. III, 16</span> כשית אינו כ׳ <i>cuscuta</i> is not forbidden (in the vineyard); <span class=\"citation\">Sabb. 139ᵃ</span>; a. v. fr.—<i>Kilayim</i>, name of a treatise of the Mishnah and Tosefta, of the Order of Z’raïm.</div>","alt":[]},"12537":{"h":"כְּלָאמִין","r":"K00675","html":"<div class=\"sense\"><i>chlamys</i>, v. <a href=\"#\" data-headword=\"כְּלָמוּס\">כְּלָמוּס</a>.</div>","alt":[]},"12538":{"h":"כָּלַב","r":"K00676","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"כָּלַל\">כָּלַל</a>) <i>to seize</i>.—Denom. <a href=\"#\" data-headword=\"כֶּלֶב\">כֶּלֶב</a>.</div><div class=\"sense\"><b>Pi. כִּלֵּב</b> </div><div class=\"sense\"><b>Hif. הִכְלִיב</b> <div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"כֶּלֶב\">כֶּלֶב</a>) [<i>to make stitches resembling dog-bites</i> (cmp. our ‘cat-stitching’),] <i>to stitch</i>, opp. to <a href=\"#\" data-headword=\"תָּפַר\">תָּפַר</a> to sew in a workmanlike manner. <span class=\"citation\">M. Kat. I, 8</span> (<span class=\"citation\">8ᵇ</span>) <span dir=\"rtl\">האומן מְכַלֵּב</span> Ms. M. a. Y. ed. (Mish. a. Babli <span dir=\"rtl\">מַכְלִיב</span>) the professional tailor is permitted (during the festive week) to stitch (but not to sew); expl. ib. 10ᵃ <span dir=\"rtl\">מפסיע</span> he makes wide steps (cross-stitches); (another opin.) <span dir=\"rtl\">שיני כלבתא</span> (Ms. M. only <a href=\"#\" data-headword=\"כַּלְבְּתָא\">כַּלְבְּתָא</a> q. v.) dog’s teeth, i.e. irregular stitches; Y. ib. 80ᵈ bot. <span dir=\"rtl\">מפסיע</span>; (oth. opin.) <span dir=\"rtl\">אחת אחת</span> each stitch singly. Ib. <span dir=\"rtl\">הרוצענין מְכַלְּבִין</span> the saddlers are permitted to do dog-stitching.</div></div>","alt":[]},"12539":{"h":"כֶּלֶב","r":"K00677","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"כָּלַב\">preced.</a>) <i>dog</i>. <span class=\"citation\">Snh. 63ᵇ</span> (expl. <a href=\"#\" data-headword=\"נִבְחָן\">נבחן</a>, <span class=\"citation\">II Kings XVII, 31</span>) <a href=\"#\" data-headword=\"כ׳\">כ׳</a> they worshipped a dog. <span class=\"citation\">Yoma VIII, 6</span>, a. e. <span dir=\"rtl\">כ׳ שוטה</span> a mad dog. <span class=\"citation\">Kil. I, 6</span>, v. <a href=\"#\" data-headword=\"כּוּפְרִי I\">כּוּפְרִי</a>. <span class=\"citation\">Kel. XVII, 13</span> <span dir=\"rtl\">כ׳ המים</span> sea-dog. <span class=\"citation\">Gen. R. s. 77</span>, v. <a href=\"#\" data-headword=\"אַגְרִיאוֹן\">אַגְרִיאוֹן</a>. <span class=\"citation\">Y. Snh. VII, 23ᶜ</span> top (ref. to <span class=\"citation\">Ps. XXII, 21</span>) <span dir=\"rtl\">מכַּלְבּוֹ של וכ׳</span> from the dog (the vicious accuser) of that pious man, v. ib. 23ᵇ bot., sq.); a. fr. Pl. <span dir=\"rtl\">כְּלָבִים</span>. <span class=\"citation\">Ber. 3ᵃ</span>. <span class=\"citation\">Tosef. B. Kam. VIII, 17</span>. <span class=\"citation\">Ex. R. s. 20</span> <span dir=\"rtl\">עשו … כ׳ של וכ׳</span> the Egyptians made golden dogs by sorcery that they should bark &amp;c.; a. fr.</div>","alt":[]},"12540":{"h":"כְּלֵב","r":"K00678","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Ps. LIX, 7</span>. <span class=\"citation\">Targ. Prov. VII, 22</span> (Ms. <a href=\"#\" data-headword=\"כְּלִיבָא\">כְּלֵיבָא</a>; h. text <a href=\"#\" data-headword=\"עֶכֶס\">עכס</a>); a. fr.—<span class=\"citation\">Y. Ab. Zar. III, 42ᵈ</span> top, expl. <a href=\"#\" data-headword=\"נִבְחָן\">נבחן</a>, v. preced.—<span class=\"citation\">Erub. 61ᵃ</span> (prov.) <span dir=\"rtl\">כ׳ בלא מתיה וכ׳</span> a dog away from home barks not for seven years, i.e. however quarrelsome a man may be, he will not fight in a strange place; a. fr.—Trnsf. <i>a mean person</i>. <span class=\"citation\">Lev. R. s. 9</span>.—Pl. <span dir=\"rtl\">כַּלְבִּין</span>, <a href=\"#\" data-headword=\"*כִּלְבִּיָּא\">כַּלְבַּיָּא</a>, <span dir=\"rtl\">כַּלְבֵּי</span>. <span class=\"citation\">Targ. Ps. XXII, 17</span>. <span class=\"citation\">Targ. Is. LVI, 10</span>; a. e.—<span class=\"citation\">Y. Peah I, 15ᶜ</span> bot.; <span class=\"citation\">Y. Kidd. I, 61ᵇ</span>, v. <a href=\"#\" data-headword=\"דּוּשׁ\">דּוּשׁ</a> ch.—<span class=\"citation\">Sabb. 152ᵃ</span> <span dir=\"rtl\">כַּלְבּוֹהִי לא וכ׳</span> his (euphem. for <i>my</i>) dogs no longer bark, i.e. my voice is weak from old age. <span class=\"citation\">B. Mets. 94ᵃ</span> top <span dir=\"rtl\">כך וכך כ׳ איכא וכ׳</span> so and so many dogs have we with us. Pesik. B’shall., p. 86ᵃ <span dir=\"rtl\">תרין כלבי דחרשין</span> (not <a href=\"#\" data-headword=\"כַּלְבָּא III\">כלבא</a>) two dogs (of gold) made by the sorcerers (v. <a href=\"#\" data-headword=\"כֶּלֶב\">preced.</a>). Ib., sq. <span dir=\"rtl\">כ׳ דקושטא</span> the real (natural) dogs do not bark at us (ref. to <span class=\"citation\">Ex. XI, 7</span>); a. e.—[<span class=\"citation\">Targ. Koh. IV, 6</span> <span dir=\"rtl\">כלב גזילא</span>, some ed., read <span dir=\"rtl\">בלא ג׳</span>.—<span class=\"citation\">Lam. R. to I, 4</span> <a href=\"#\" data-headword=\"כַּלְבָּא III\">כלבא</a>, read: <a href=\"#\" data-headword=\"כַּלבָּה\">כַּלְבָּה</a>.]</div>","alt":["כְּלַב","כַּלְבָּא I"]},"12541":{"h":"כַּלְבָּא II","r":"K00679","html":"<div class=\"sense\">, pr. n. m. <span dir=\"rtl\">בֶּן כ׳ שְׂבוּעַ</span> <i>Ben Kalba S’buʿa</i>, name of a wealthy citizen of Jerusalem. <span class=\"citation\">Gitt. 56ᵃ</span></div>","alt":[]},"12542":{"h":"כַּלְבָּא III","r":"K00680","html":"<div class=\"sense\">, Var. of <a href=\"#\" data-headword=\"אַכְלְבָא\">אַכְלְבָא</a>. V. Ar. Compl. ed. <span class=\"citation\">Koh. IV, 235</span>.</div>","alt":["כְּלֵבָא"]},"12543":{"h":"כַּלבָּה","r":"K00681","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"כֶּלֶב\">כֶּלֶב</a>) </div><div class=\"sense\"><b>1)</b> <i>she-dog</i>. <span class=\"citation\">Lam. R. to I, 4</span> (not <a href=\"#\" data-headword=\"כַּלְבָּא III\">כלבא</a>). <span class=\"citation\">Y. Snh. VI, 23ᵇ</span> bot. <span dir=\"rtl\">נזקקין לכ׳</span> having connection with a dog. <span class=\"citation\">Koh. R. to VII, 26</span>.</div><div class=\"sense\"><b>—2)</b> <i>tongs, pinchers</i>. <span class=\"citation\">Tosef. Kel. B. Mets. III, 11</span> <span dir=\"rtl\">כ׳ של ספרין וכ׳</span> the barbers’ tongs, the physicians’ &amp;c.; v. <a href=\"#\" data-headword=\"כַּלְבּוּס\">כַּלְבּוּס</a>.</div>","alt":[]},"12544":{"h":"כלבודא","r":"K00682","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּלְכִּיד\">כַּלְכִּיד</a></div>","alt":[]},"12545":{"h":"כַּלְבּוּס","r":"K00683","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (enlarg. of <span dir=\"rtl\">כלב</span>, v. <a href=\"#\" data-headword=\"כַּלבָּה\">כַּלְבָּה</a> 2) </div><div class=\"sense\"><b>1)</b> <i>tongs, pinchers</i>, <span class=\"citation\">Sot. 19ᵇ</span> <span dir=\"rtl\">כ׳ של ברזל</span> (Alf. <a href=\"#\" data-headword=\"ק׳\">ק׳</a>) iron tongs (to force her mouth open; Tosef. ib. II, 3 <span dir=\"rtl\">צבת</span>). <span class=\"citation\">Tosef. Kel. B. Mets. III, 11</span> some ed., v. <a href=\"#\" data-headword=\"כַּלבָּה\">כַּלְבָּה</a>. <span class=\"citation\">Men. 63ᵃ</span> <span dir=\"rtl\">כמין כ׳ עמוק</span> (Ar. <a href=\"#\" data-headword=\"כִּלְכּוּל\">כיל׳</a></div><div class=\"sense\"><b>—2)</b>  (v. <a href=\"#\" data-headword=\"כָּלַב\">כָּלַב</a>) <i>shape of cross-stitches, zigzag</i> of nails in the sole. <span class=\"citation\">Sabb. 60ᵇ</span> <span dir=\"rtl\">עשאו כמין כ׳</span> (Ms. M. <a href=\"#\" data-headword=\"*כַּלְכּוּס\">כלכוס</a>, Alf. <a href=\"#\" data-headword=\"ק׳\">ק׳</a>) if he drove the nails in in the shape of &amp;c. <span class=\"citation\">Koh. R. to XII, 11</span> <span dir=\"rtl\">הכ׳ אינו וכ׳</span>, v. <a href=\"#\" data-headword=\"כַּלֶּבֶת\">כַּלֶּבֶת</a>.—[<span class=\"citation\">B. Kam. 100ᵇ</span> <a href=\"#\" data-headword=\"כ׳\">כ׳</a>, v. <a href=\"#\" data-headword=\"*כַּלְכּוּס\">כַּלְכּוּס</a>.—Tanḥ. Balak 13, read: <a href=\"#\" data-headword=\"כָּלִינוֹס\">כָּלִינוֹס</a>.]</div>","alt":[]},"12546":{"h":"*כִּלְבִּיָּא","r":"K00684","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (an assumed word for <a href=\"#\" data-headword=\"כַּלבָּה\">כַּלְבָּה</a>, after the form of <a href=\"#\" data-headword=\"לְבִיאָה\">לְבִיָּא</a>) <i>she-dog, bitch</i>. <span class=\"citation\">Midr. Till. to Ps. XXXIX</span> (in an allegorical contest of the limbs) <span dir=\"rtl\">הא לך חלב כ׳</span> here is dog-milk for thee, ed. Bub. <a href=\"#\" data-headword=\"כַּלְבָּא III\">כלבא</a>; <span class=\"citation\">Yalk. Ps. 721</span> <a href=\"#\" data-headword=\"כַּלְבְּתָא\">כלבתא</a> (corr. acc.). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">הבאת חלב כ׳</span> (read with Yalk. l. c. <a href=\"#\" data-headword=\"כְּלֵב\">כַּלְבָּא</a>; ed. Bub. <a href=\"#\" data-headword=\"כַּלְבְּתָא\">כלבתא</a>) thou hast brought dog-(instead of lion-) milk. Ib. <span dir=\"rtl\">ועוד ג&quot;כ כי לבייא קורין אותה כ׳</span> (differ. in Yalk.; ed. Bub. <span dir=\"rtl\">ועוד ללבייא … כלבתא</span>) and furthermore a lioness may likewise be called a bitch.</div>","alt":[]},"12547":{"h":"כִּלְבִּית","r":"K00685","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּילְכִּית\">כִּילְכִּית</a></div>","alt":[]},"12548":{"h":"כַּלֶּבֶת","r":"K00686","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּלַב\">כָּלַב</a>, v. <a href=\"#\" data-headword=\"כַּלְבּוּס\">כַּלְבּוּס</a>) <i>dog-stitch, the shoemaker’s pegging</i> of the sandal. <span class=\"citation\">Y. Snh. X, 28ᵃ</span> <span dir=\"rtl\">כ׳ אינה עולה וכ׳</span> the <i>kallebeth</i> does not count among the number of nails to be driven into shoes; Y. Sabb. VI, 8ᵃ <span dir=\"rtl\">כלי בית</span> (corr. acc., or <span dir=\"rtl\">כְּלִיבִית</span>); <span class=\"citation\">Koh. R. to XII, 11</span> <span dir=\"rtl\">הכלבוס אינו וכ׳</span>.</div>","alt":[]},"12549":{"h":"כַּלְבְּתָא","r":"K00687","html":"<div class=\"sense\"> (tradit. pronunc. <a href=\"#\" data-headword=\"כַּלְבְּתָא\">כְּלַבְתָּא</a>) f. ch. = h., <i>bitch</i>. <span class=\"citation\">R. Hash. 4ᵃ</span>. <span class=\"citation\">Yalk. Ps. 721</span>, v. <a href=\"#\" data-headword=\"*כִּלְבִּיָּא\">כִּלְבִּיָּא</a>; a. e.—<span dir=\"rtl\">שיני כ׳</span> (cmp. <a href=\"#\" data-headword=\"כַּלֶּבֶת\">preced. w.</a>) <i>dog-stitch</i>. <span class=\"citation\">M. Kat. 10ᵃ</span>, v. <a href=\"#\" data-headword=\"כָּלַב\">כָּלַב</a>.</div>","alt":[]},"12550":{"h":"כַּלְדָּאָה","r":"K00688","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>Chaldeans, soothsayers</i>. <span class=\"citation\">Sabb. 119ᵃ</span>. <span class=\"citation\">Yeb. 21ᵇ</span>; a. e.</div>","alt":[]},"12551":{"h":"כַּלְדִּי","r":"K00689","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> . <span class=\"citation\">Pes. 113ᵇ</span> <span dir=\"rtl\">אין שואלין בכ׳</span> (Ar. <span dir=\"rtl\">כַּלְדָּאִין</span>) we must not consult soothsayers.</div>","alt":[]},"12552":{"h":"*כְּלָה","r":"K00690","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אוּבְלָא II\">אוּכְלָא</a>, <a href=\"#\" data-headword=\"עוּכְלָא\"><a href=\"#\" data-headword=\"עוּכְלָא\">עוּכְלָא</a>)</a><i>K’lah</i>, a measure for spices. <span class=\"citation\">Y. Bets. III, end, 62ᵇ</span> <span dir=\"rtl\">תן לי כ׳ וכ׳</span> give me a <i>k’lah</i> of spices, for housekeepers are in the habit of putting a <i>k</i>. of spices &amp;c. Y. Peah VIII, 20ᵈ bot. <span dir=\"rtl\">כולה תבלין</span> a K. is the ordinary quantity for spices; (<span class=\"citation\">Erub. 29ᵃ</span>; R. S. to <span class=\"citation\">Peah VIII, 5</span> <a href=\"#\" data-headword=\"עוּכְלָא\">עוכלא</a>).</div>","alt":[]},"12553":{"h":"כַּלָּה","r":"K00691","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b>  [<i>crown, ornament</i>, v. <span class=\"citation\">Is. XLIX, 18</span>,] (sub. <span dir=\"rtl\">בעלת</span> or <a href=\"#\" data-headword=\"בַּת I\">בת</a>, cmp. <a href=\"#\" data-headword=\"אִיתּוּ\">אִיתּוּ</a>, <span dir=\"rtl\">חוֹרִים</span> a. <span dir=\"rtl\">בֶּן חוֹרִים</span>) <i>bride; daughter-in-law</i>. <span class=\"citation\">Yeb. I, 1</span> <span dir=\"rtl\">וכַלָּתוֹ</span> and his (deceased) son’s wife. <span class=\"citation\">Sot. IX, 14</span> <span dir=\"rtl\">שתצא הב׳ וכ׳</span> that the bride on her wedding day may be taken around in procession, v. <a href=\"#\" data-headword=\"אַפִּרְיוֹן\">אַפִּרְיוֹן</a>. <span class=\"citation\">Keth. 71ᵇ</span>; <span class=\"citation\">Pes. 87ᵃ</span> <span dir=\"rtl\">ככ׳ שנמצאת וכ׳</span> like a bride (daughter-in-law) found perfect in the house of her father-in-law. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כ׳ בבית אביה</span> a bride in her father’s house (not yet taken to her husband’s paternal house). <span class=\"citation\">Ex. R. s. 41</span> (play on <span dir=\"rtl\">ככלתו</span>, <span class=\"citation\">Ex. XXXI, 18</span>, cmp. <a href=\"#\" data-headword=\"כְּלַל\">כְּלַל</a> <i>Pa</i>.) <span dir=\"rtl\">מה כ׳ זו מקושטת וכ׳</span> as the bride is adorned &amp;c.; a. fr. [Tanḥ. Ki Thissa 18 <span dir=\"rtl\">כ׳ נופי</span>, read with ed. Bub. ib. 9 <span dir=\"rtl\">קלי נינפי</span>.]—Pl. <span dir=\"rtl\">כַּלּוֹת</span>. Sot. l. c. <span dir=\"rtl\">עטרות כ׳</span> (Talm. ed. <i>sing</i>.) the bridal wreaths. Ib. 49ᵇ; a. fr </div><div class=\"sense\"><b>—2)</b> <i>general assembly</i>, esp. <i>Kallah, the assembly of Babylonian students in the months of Elul and Adar</i>. <span class=\"citation\">Ber. 8ᵇ</span> פרשייתא דכ׳ Ar. (Ms. Paris <span dir=\"rtl\">דכַלָּא</span>, v. Rabb. D. S., Vol. I, p. 384; ed. <span dir=\"rtl\">דכולא שתא</span>) the weekly Scripture lessons of the Kallah weeks (during which R. Bibi could not find time to peruse the section of each week). Ib. 6ᵃ, v. <a href=\"#\" data-headword=\"דּוּחֲקָא\">דּוּחֲקָא</a>. Ib. 57ᵃ <span dir=\"rtl\">ראש לבני כ׳</span>; <span class=\"citation\">B. Bath. 22ᵃ</span> <span dir=\"rtl\">ריש כ׳</span> the president of the Kallah.—Pl. (of <a href=\"#\" data-headword=\"כְּלֵי\">כַּלָּא</a>) <a href=\"#\" data-headword=\"כְּלֵי\">כַּלֵּי</a>. <span class=\"citation\">Ḥull. 49ᵃ</span> <span dir=\"rtl\">רישי כ׳</span>.—<span dir=\"rtl\">מסכת כלה</span>, <span dir=\"rtl\">מסכתא דכ׳</span> a (small) treatise of the Talmud named <i>Kallah</i> (from its first word). <span class=\"citation\">Sabb. 114ᵃ</span>; <span class=\"citation\">Kidd. 49ᵇ</span>; <span class=\"citation\">Taan. 10ᵇ</span>; [oth. opin.: a subject which has been discussed in the general assembly].</div>","alt":[]},"12554":{"h":"כָּלָה","r":"K00692","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כלי\">כלי</a></div>","alt":[]},"12555":{"h":"כָּלוּ","r":"K00693","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (כְּלֵי I, sub. <a href=\"#\" data-headword=\"חֵימְתָא\">חֵימְתָא</a>) <i>finishing, venting full wrath</i>. <span class=\"citation\">Targ. Y. Deut. XXIX, 27</span>. <span class=\"citation\">Targ. Ps. LIX, 14</span> <span dir=\"rtl\">בכָ׳</span> (Ms. <span dir=\"rtl\">בכַיְלוּ</span>). <span class=\"citation\">Targ. Y. II, Gen. XXVII, 44</span> <span dir=\"rtl\">כולתיה</span> (read: <span dir=\"rtl\">כְּלוּתֵיה</span>). <span class=\"citation\">Targ. Y. Deut. XXIX, 22</span> <span dir=\"rtl\">כְּלֵיתֵיה</span>.</div>","alt":["כְּלוּ"]},"12556":{"h":"כְּלוּב","r":"K00694","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> [<i>twisted together, united by tenons</i>,] <i>shed, coop</i>. <span class=\"citation\">Bets. 24ᵃ</span> <span dir=\"rtl\">באין לכְלוּבָן בערב</span> enter their coop in the evening.</div>","alt":[]},"12557":{"h":"*כָּלוּב","r":"K00695","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּלַב\">כָּלַב</a>, cmp. <a href=\"#\" data-headword=\"כּוּלָב\">כּוּלָב</a>) <i>axe</i>.—Pl. <span dir=\"rtl\">כְּלוּבִין</span>. Pesik. Zakh., p. 22ᵇ</div>","alt":[]},"12558":{"h":"כְּלוּבָא","r":"K00696","html":"<div class=\"sense\">v. <a href=\"#\" data-headword=\"כּוּלָב\">כּוּלְבָא</a></div>","alt":[]},"12559":{"h":"כלודי","r":"K00697","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Gen. 147</span>, v. <a href=\"#\" data-headword=\"כְּלִי\">כֶּלִי</a></div>","alt":[]},"12560":{"h":"כְּלוֹזָא","r":"K00698","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"אוֹכְלוֹזא\">אוֹכְלוֹזָא</a>. <span class=\"citation\">B. Bath. 8ᵃ</span> Ms. H. (Ar. s. v. <a href=\"#\" data-headword=\"כַּר\">כר</a> 11 quotes <a href=\"#\" data-headword=\"כִּילוֹזָא\">כִּילוֹזָא</a>).</div>","alt":[]},"12561":{"h":"כְּלוּחִית","r":"K00699","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Be-K’luḥith</i>. <span class=\"citation\">Bets. 5ᵇ</span> <span dir=\"rtl\">מבי כ׳</span> (Ms. M. <span dir=\"rtl\">מכ׳</span>). <span class=\"citation\">Keth. 40ᵇ</span></div>","alt":["בֵּי כ׳"]},"12562":{"h":"כלוט","r":"K00700","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בָּלוּט\">בָּלוּט</a></div>","alt":[]},"12563":{"h":"כלוכסין","r":"K00701","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּלוּפְסִין\">כְּלוּפְסִין</a></div>","alt":[]},"12564":{"h":"כָּלוּל","r":"K00702","html":"<div class=\"sense\"> m. </div><div class=\"sense\"><b>1)</b>  = <a href=\"#\" data-headword=\"כָּלִיל\">כָּלִיל</a>; </div><div class=\"sense\"><b>2)</b>  part. pass. of <a href=\"#\" data-headword=\"כָּלַל\">כָּלַל</a>. [Tanḥ. Bo 5 <span dir=\"rtl\">כ׳ לדברות</span>; Mekh. Bo, beg. <span dir=\"rtl\">כלל לדברות</span>, read: <a href=\"#\" data-headword=\"כְּלִי\">כֶּלִי</a> (v. Levy, Catal. of Rabb. Semin. of Breslau 1889, p. 38, note).]</div>","alt":[]},"12565":{"h":"כְּלוּם","r":"K00703","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <span dir=\"rtl\">כל מ</span>, cmp. <a href=\"#\" data-headword=\"מאום\">מְאוּם</a>) </div><div class=\"sense\"><b>1)</b> <i>anything, something, somebody</i> (Lat. ullus). <span class=\"citation\">Targ. Koh. I, 9</span> <span dir=\"rtl\">לית כ׳</span> (h. text <span dir=\"rtl\">אין כל</span>).—<span class=\"citation\">Yalk. Num. 730</span> (ref. to <span class=\"citation\">Num. X, 35</span>) <span dir=\"rtl\">מפניך … ואין אנו כ׳ לפניהם</span> before thee they flee, and are we nothing before them? <span dir=\"rtl\">אלא כשפניך אתנו אנו כ׳ לפניהם וכשאין פניך אתנו אין אנו כ׳ לפניהם</span> but (it means) when thy countenance is with us we are <i>something</i> before them &amp;c.; <span class=\"citation\">Sifré Num. 84</span> (corr. acc.).—<span class=\"citation\">Kel. XXIV, 1</span> <span dir=\"rtl\">טהורה מכ׳</span> is clean from any (of the aforementioned impurities). <span class=\"citation\">Ber. 22ᵇ</span>, a. fr. <span dir=\"rtl\">פטור מכ׳</span> is entirely exempt. <span class=\"citation\">Ned. I, 1</span>, a. fr. <span dir=\"rtl\">לא אמר כ׳</span> he has said nothing, i.e. what he said is void.—לא כ׳ <i>not the least, nothing at all</i>. <span class=\"citation\">Erub. 11ᵃ</span> <span dir=\"rtl\">לא עשה ולא כ׳</span> (Rashi <span dir=\"rtl\">לא עשה כ׳</span>) he has done nothing at all, i.e. what he has done has no legal consequences. <span class=\"citation\">Ib.ᵇ</span> הכל מודין … לא כ׳ היא Ms. M. all agree that if …, there is nothing at all (to consider; ed. <span dir=\"rtl\">ולא כ׳</span> = <span dir=\"rtl\">פטורה ולא כ׳</span> it is exempt, and there is nothing &amp;c.); <span class=\"citation\">Yoma 11ᵇ</span> <span dir=\"rtl\"><span dir=\"rtl\">ולא כ׳</span> (<span dir=\"rtl\">ולאו</span>) <span dir=\"rtl\">היא</span></span> (v. Rabb. D. S. a. l. Ms. M. and note).—<span class=\"citation\">Koh. R. to IX, 10</span> <span dir=\"rtl\">מאן הוא דכ׳ ודבר בגרמיה כ׳ וכ׳</span> if a person is somebody and comports himself as somebody (is proud of his value), it were better he had not been born; a. fr.</div><div class=\"sense\"><b>—2)</b>  (interrog.) introducing a question to which a negative answer is expected, <i>is there any? has any?</i> &amp;c. <span class=\"citation\">Snh. 105ᵃ</span> <span dir=\"rtl\">כ׳ יש לזה על זה כ׳</span> has the one still any claim on the other? <span class=\"citation\">Sabb. 31ᵃ</span> <span dir=\"rtl\">כ׳ מעמידין וכ׳</span> is there ever a king appointed except &amp;c.? <span class=\"citation\">Ned. VIII, 7</span> <span dir=\"rtl\">כ׳ אמרת וכ׳</span> wouldst thou have said it, but for thy wish to honor me?; a. fr.—[<span class=\"citation\">Tosef. Men. XIII, 19</span>; <span class=\"citation\">Tosef. B. Kam. VII, 8</span>, v. <a href=\"#\" data-headword=\"דֶּלֶם\">דֶּלֶם</a>.]</div>","alt":[]},"12566":{"h":"כְּלוֹמַר","r":"K00704","html":"<div class=\"sense\"> (= <span dir=\"rtl\">כְּאִילּוּ אָמַר</span>) <i>as though one said, that is to say, this means</i>. <span class=\"citation\">Naz. II, 3</span> (<span class=\"citation\">11ᵃ</span>) <span dir=\"rtl\">לא נתכוונה זו אלא כ׳ וכ׳</span> (Mish. ed. <span dir=\"rtl\">לומר</span>) she had no intention except that of one who says, ‘This be unto me a sacrifice’, i.e. she meant only to forbid herself this cup (cmp. ib. <span dir=\"rtl\">כמאן דאמר</span>). <span class=\"citation\">Snh. VI, 4</span> (interpret. <span dir=\"rtl\">כי קללת וכ׳</span>, <span class=\"citation\">Deut. XXI, 23</span>) <span dir=\"rtl\">כ׳ מפני מה וכ׳</span> which means as much as, (people will say,) Why has this man been hanged? &amp;c.—Ib. 6 <span dir=\"rtl\">כ׳ שאין וכ׳</span> as if saying (intimating), we bear no grudge &amp;c. <span class=\"citation\">Ex. R. s. 41</span> <span dir=\"rtl\">היא מגלה פניה כ׳ וכ׳</span> she uncovers her face, as if saying &amp;c.; a. v. fr.</div>","alt":[]},"12567":{"h":"כלונוס","r":"K00705","html":"<div class=\"sense\">, Ab. d’R. N. ch. XLIV, ed. Schechter, v. <a href=\"#\" data-headword=\"כָּלִינוֹס\">כָּלִינוֹס</a></div>","alt":[]},"12568":{"h":"כלוניא","r":"K00706","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"לִינְיָא\">לִינְיָא</a></div>","alt":["כלונייס"]},"12569":{"h":"כלוניס","r":"K00707","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Kel. B. Mets. IV, 7</span>, v. <a href=\"#\" data-headword=\"כָּלִינוֹס\">כָּלִינוֹס</a></div>","alt":[]},"12570":{"h":"כְּלוֹנָס","r":"K00708","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (a sing. of κελεόντες, as if κελέονς) <i>beam of the loom</i>, in gen. <i>beam, pole.</i> <span class=\"citation\">Kel. XX, 3</span> <span dir=\"rtl\">קבעו בכ׳</span> if he inserted the transverse staff of the loom in the beam; <span dir=\"rtl\">כסא שקבעו בכ׳</span> if one fixes a chair on the top of a beam; <span class=\"citation\">Tosef. Kel. B. Mets. XI, 5</span>. <span class=\"citation\">Zab. III, 3</span> על הכ׳ Ar. (ed. <span dir=\"rtl\">האכ׳</span>) was seated on a beam. <span class=\"citation\">Tosef. Kel. B. Bath. II, 2</span> <span dir=\"rtl\">כליניס</span> ed. Zuck. (corr. acc.). <span class=\"citation\">Ib. VII, 2</span> <a href=\"#\" data-headword=\"כליונים\">כליונים</a> ed. Zuck. (ed. <a href=\"#\" data-headword=\"כָּלִינוֹס\">כלינוס</a>, corr. acc.). [<span class=\"citation\">Ab. d’R. N. ch. XXIV</span>, v. <a href=\"#\" data-headword=\"כָּלִינוֹס\">כָּלִינוֹס</a>.]—Pl. <span dir=\"rtl\">כְּלוֹנְסוֹת</span>, <span dir=\"rtl\">כְּלוֹנְסִיּוֹת</span>, <span dir=\"rtl\">כְּלוֹנְסָאוֹת</span>. <span class=\"citation\">B. Bath. 67ᵇ</span> (expl. <span dir=\"rtl\">בתולות</span>) <span dir=\"rtl\">כ׳ של ארז וכ׳</span> cedar beams supporting the transverse press beam. <span class=\"citation\">R. Hash. II, 3</span> (<span class=\"citation\">22ᵇ</span>) <span dir=\"rtl\">כלונסא׳</span> (Ms. M. 2 <span dir=\"rtl\">קְלוֹנְסוֹת</span>). <span class=\"citation\">Sifré Num. 160</span>. <span class=\"citation\">Tosef. Kel. B. Bath. II, 2</span>; a. e.</div>","alt":[]},"12571":{"h":"כְּלוֹנְסָא","r":"K00709","html":"<div class=\"sense\"> <span class=\"citation\">Targ. I Kings VI, 4</span>; <span class=\"citation\">VII, 5</span> Ar., Rashi a. Kimḥi (ed. <a href=\"#\" data-headword=\"כְּלִינְסָא\">כּלִינְסָא</a>, <span dir=\"rtl\">כְּלֵנ׳</span>, Levita Var. <span dir=\"rtl\">קלונסא</span>; h. text <a href=\"#\" data-headword=\"שָׁקַף I\">שקף</a>) beam used for arches (v. Sm. Ant. s. v. Camara). Ib. 4.—Pl. <a href=\"#\" data-headword=\"כְּלוֹנְסָא\">כְּלוֹנְסָן</a>. <span class=\"citation\">Targ. Y. II, Num. XXXV, 20</span> (v. <span class=\"citation\">Sifré Num. 160</span>).</div>","alt":[]},"12572":{"h":"כלוסין","r":"K00710","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּלוּפְסִין\">next w.</a> a. <a href=\"#\" data-headword=\"כָּלִיס\">כָּלִיס</a>.</div>","alt":[]},"12573":{"h":"כְּלוּפְסִין","r":"K00711","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (Lesbii; v. <a href=\"#\" data-headword=\"גְּלוּסְקָא\">גְּלוּסְקָא</a> a. <a href=\"#\" data-headword=\"גְּלוּגְדְּקָא\"><a href=\"#\" data-headword=\"גְּלוּגְדְּקָא\">גְּלוּגְדְּקָא</a>)</a><i>Lesbians</i>, </div><div class=\"sense\"><b>1)</b>  a species of <i>figs</i>. <span class=\"citation\">Ned. 50ᵇ</span> (quoting <span class=\"citation\">Maasr. II, 8</span>) <span dir=\"rtl\">היה עושה בכ׳</span> if one is doing hired labor among Lesbian figs; Maasr. l. c. <a href=\"#\" data-headword=\"כְּלוּפְסִין\">לבסים</a>; Mish. Y. ed. <span dir=\"rtl\">לכסים</span>; Y. ib. II, 50ᵃ <a href=\"#\" data-headword=\"כלוסין\">כלוסין</a>. Ned. l. c. <span dir=\"rtl\">מאי כ׳</span> what is K.? Answ. <span dir=\"rtl\">מינא דתאיני וכ׳</span> a species of figs used for cooking purposes. Ib. 49ᵇ (in Chald. dict.) <span dir=\"rtl\">בלוספיין</span>, read <span dir=\"rtl\">כְּלוּסְפִּיִּין</span> (or … <span dir=\"rtl\">פָּיִין</span>); [Ar. reads <a href=\"#\" data-headword=\"בלופסין\">בלופסין</a>; Mus. refers to φιβαλέως, a species of <i>early figs</i>.]</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"גְּלוּסְקָא\">גְּלוּסְקָא</a>) a species of <i>table-olives</i>, opp. <span dir=\"rtl\">זיתי שמן</span>. <span class=\"citation\">Tosef. Ter. IV, 3</span> <a href=\"#\" data-headword=\"קְלוּפְסִין\">קלופסין</a> ed. Zuck. (Var. <a href=\"#\" data-headword=\"כְּלוּפְסִין\">גלופ׳</a>; <span class=\"citation\">Ter. II, 6</span> <span dir=\"rtl\">זיתי כבש</span>). Ib. III, 15 <a href=\"#\" data-headword=\"ק׳\">ק׳</a> (Var. <span dir=\"rtl\">קולפ׳</span>, <span dir=\"rtl\">קלפין</span>); Y. ib. I, end, 41ᵃ <a href=\"#\" data-headword=\"כלוכסין\">כלוכסין</a> (read: <span dir=\"rtl\">כלוב׳</span> or <span dir=\"rtl\">כלופ׳</span>).</div>","alt":["גְּלוּפְ׳","קְלוּפְ׳","לִבְסִים","לִבְסִין"]},"12574":{"h":"כלורכין","r":"K00712","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כלירכין\">כלירכין</a></div>","alt":[]},"12575":{"h":"כְּלוּתָא","r":"K00713","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כָּלוּ\">כָּלוּ</a></div>","alt":[]},"12576":{"h":"כְּלִי","r":"K00714","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"כלי\">next w.</a>) </div><div class=\"sense\"><b>1)</b> <i>vessel, receptacle; bag</i> &amp;c. <span class=\"citation\">B. Bath. 85ᵃ</span> <span dir=\"rtl\">כֶּלְיוֹ של אדם וכ׳</span> a man’s vessel takes possession for him (of its contents). <span class=\"citation\">Ber. 23ᵃ</span> <span dir=\"rtl\">כ׳ שהוא כֶלְיָין</span> a receptacle which is intended for them (the T’fillin). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כ׳ בתוך כ׳</span> one wrapper within the other. <span class=\"citation\">Y. Sabb. VII, 10ᵈ</span> top <span dir=\"rtl\">הגודל כְּלִי צורה</span> he who shapes an earthen vessel; <span dir=\"rtl\">הנופח כ׳ זכוכית</span> who shapes a glass vessel by blowing; <span dir=\"rtl\">העושה כ׳ בדפוס</span> who makes a vessel in a mould. <span class=\"citation\">Y. Ḥag. III, 79ᵃ</span> top, a. fr. <span dir=\"rtl\">נזקקו לכֶילְיָין</span> they are tied to their vessel, i.e. the vessel in which they are offered makes them to be considered one mass, though they are otherwise disconnected; <span class=\"citation\">Ḥag. III, 2</span> <span dir=\"rtl\">הכ׳ מצרף וכ׳</span>. Mekh. Yithro, Amalek, 2 (ref. to <span class=\"citation\">Ex. XVIII, 19</span>) <span dir=\"rtl\">היה להם ככ׳ מלא דברות</span> be unto them like a vessel filled with divine revelations. <span class=\"citation\">Ab. d’R. N., II</span> vers., ch. II, v. <a href=\"#\" data-headword=\"יָחַד\">יָחַד</a>. Mekh. Bo., beg. <span dir=\"rtl\">כלל לדברות</span>; Tanḥ. Bo. 5 <span dir=\"rtl\">כלול לד׳</span> (read <a href=\"#\" data-headword=\"כלי\">כלי</a>) a vessel of revelation; a. fr.—Pl. <span dir=\"rtl\">כֵּלִים</span>, constr. <a href=\"#\" data-headword=\"כְּלֵי\">כְּלֵי</a>. <span class=\"citation\">Ḥag. III, 1</span> <span dir=\"rtl\">כ׳ בתוך כ׳</span> vessels put into larger vessels. <span class=\"citation\">Kel. I, 1</span>. <span class=\"citation\">Ib. II, 1</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>outfit, apparel, garment, tool, weapon.</i> <i> Pl.</i> as ab. <span class=\"citation\">Keth. 59ᵇ</span> <span dir=\"rtl\">כ׳ פשתן</span> linen garments. <span class=\"citation\">Sabb. 114ᵃ</span> <span dir=\"rtl\">כ׳ לבנים</span> white garments; a. v. fr.—<span class=\"citation\">Gen. R. s. 90</span> (expl. <span class=\"citation\">Gen. XLI, 44</span>) <span dir=\"rtl\">כ׳ ידים</span> official badge of the hands (bracelets, rings &amp;c.), <span dir=\"rtl\">כ׳ רגלים</span> greaves &amp;c.; (Ar. a. Rashi <a href=\"#\" data-headword=\"כלידו\">כלידרים</a>, <a href=\"#\" data-headword=\"כלידו\">כלידרין</a>, corrupt. of <span dir=\"rtl\">כלי ידים</span>). <span class=\"citation\">Gen. R. s. 89</span> <span dir=\"rtl\">שאין עבד … כ׳ ידים</span> (some ed. <a href=\"#\" data-headword=\"כלידו\">כלידים</a>, Ar. <a href=\"#\" data-headword=\"כלידו\">כלידרין</a>; Yalk. ib. 147 <a href=\"#\" data-headword=\"כלודי\">כלודי</a>, corr. acc.) that no servant was to hold office or wear rings &amp;c. (v. Sm. Ant. s. v. Annulus).—<span dir=\"rtl\">כלי זיין</span>, v. <a href=\"#\" data-headword=\"זַיִין\">זַיִין</a>.—<span class=\"citation\">B. Mets. IX, 13</span> <span dir=\"rtl\">חייב משום שני כ׳</span> he is guilty of having seized two implements (the upper and the lower millstone). Ib. <span dir=\"rtl\">שני כ׳</span> two objects of use (a mattress and a plough). <span class=\"citation\">B. Bath. V, 2</span> <span dir=\"rtl\">כֵּלָיו</span> the outfit of the ass (saddle &amp;c.); a. fr.</div>","alt":["כֶּלִי"]},"12577":{"h":"כלי","r":"K00715","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"כָּלַל\">כָּלַל</a>) </div><div class=\"sense\"><b>1)</b> <i>to enclose; to restrain, keep back</i>. <span class=\"citation\">Midr. Till. to Ps. CXIII</span> <span dir=\"rtl\">לִכְלוֹת את המכה וכ׳</span> to ward this plague off from thee. <span class=\"citation\">Midd. IV, 6</span> כֹּלֵה עֹרֵב ‘keeping off the raven’, an arrangement of <i>iron points</i> on the roof of the Temple; <span class=\"citation\">Sabb. 90ᵃ</span> <span dir=\"rtl\">כּוֹלֵי עורב</span> (pl.) Ms. M. (ed. <a href=\"#\" data-headword=\"כַּלְיָא\">כַּלְיָיא</a> ch.; v. Rabb. D. S. a. l. note); <span class=\"citation\">Men. 107ᵃ</span> כולי Ms. M. (ed. <a href=\"#\" data-headword=\"כִּלְיָה\">כַּלְיָה</a>); <span class=\"citation\">M. Kat. 9ᵃ</span> כולי Ms. M. (ed. <span dir=\"rtl\">כליא</span>); <span class=\"citation\">Arakh. 6ᵃ</span> <span dir=\"rtl\">כליה</span>.—Part. pass. <a href=\"#\" data-headword=\"כָּלוּ\">כָּלוּי</a>. <span class=\"citation\">Y. Naz. II, beg. 51ᵈ</span> כ׳ אני ממנו I will be restrained from it (for ‘I will abstain’).</div><div class=\"sense\"><b>—2)</b>  (cmp. <span dir=\"rtl\">שלם</span>) <i>to be full, to be finished, to cease</i>. <span class=\"citation\">Ber. 39ᵃ</span> <span dir=\"rtl\">צריך שתִּכְלֶה ברכה וכ׳</span> the benediction must be finished simultaneously with breaking the bread. Tanḥ. Ki Thissa 5 כבר כָּלוּ ישראל וכ׳ Israel would have ceased to exist; (Pesik. Shek., p. 13ᵇ <span dir=\"rtl\">חיו … מְכוּלִּין</span>, v. infra). <span class=\"citation\">Snh. 97ᵇ</span> <span dir=\"rtl\">כלו כל הקצין</span> all the predicted terms of redemption are ended (have passed by); a. fr.—[<span class=\"citation\">Pesik. R. s. 12</span> <span dir=\"rtl\">מת וכלה בקבר</span>, read: <span dir=\"rtl\">ובלה</span>.]—Part. (fr. <a href=\"#\" data-headword=\"כּוּל\">כּוּל</a>, cmp. <a href=\"#\" data-headword=\"חוּל\">חוּל</a>, part. <a href=\"#\" data-headword=\"חוֹלוֹת\">חולות</a> a. <span dir=\"rtl\">חלות</span>) <a href=\"#\" data-headword=\"כָּל\">כָּל</a>. <span class=\"citation\">Snh. 17ᵃ</span> (ref. to <span dir=\"rtl\">כלאם</span>, <span class=\"citation\">Num. XI, 28</span>) <span dir=\"rtl\">הטל … והן כָּלִין מאליהם</span> throw upon them the care for the public, and they will cease (to prophesy) of themselves; a. fr.</div><div class=\"sense\"><b>Pi. כִּלָּה</b> <div class=\"sense\"><b>1)</b> <i>to finish, cease</i>. <span class=\"citation\">Yoma 60ᵇ</span> (ref to <span class=\"citation\">Lev. XVI, 20</span>) <span dir=\"rtl\">אם כפר כ׳</span> when he has atoned (for the sanctuary &amp;c.), he has finished (his task). Ib. <span dir=\"rtl\">אם כ׳ כפר</span> when he has done all (the prescribed ritual), he has achieved atonement; Sifra Aḥăré ch. IV, Par. 4; a. e.—Tanḥ. Vayetse 2 <span dir=\"rtl\">מְכַלִּין את שדותיהן</span> they reap their fields entirely (leaving no corners for the poor). <span class=\"citation\">Snh. 67ᵇ</span> <span dir=\"rtl\">כַּלֵּה מִדַּבְּרוֹתֶיךָ ולך וכ׳</span> (some ed. <span dir=\"rtl\">כלך</span>, v. Rab. D. S. a. l. note) cease from thy homiletical interpretations, and turn to &amp;c.; <span class=\"citation\">Midr. Till. to Ps. CIV, 6</span>; <span class=\"citation\">Ex. R. s. 10</span>, v. <a href=\"#\" data-headword=\"כַּלֵּךְ\">כַּלֵּךְ</a>.</div><div class=\"sense\"><b>—2)</b> <i>to finish, destroy</i>. Y. Shek. VI, 50ᵇ top (ref. to <span dir=\"rtl\">מכלות</span>, <span class=\"citation\">II Chr. IV, 21</span>) <span dir=\"rtl\">הן כִּילּוּ וכ׳</span> they (these vessels) consumed all the gold (of the country); <span class=\"citation\">Men. 29ᵃ</span> <span dir=\"rtl\">שכִּילַּתּוֹ וכ׳</span> it consumed &amp;c. <span class=\"citation\">Pesik. R. s. 2</span> <span dir=\"rtl\">שכי׳ אותה וכ׳</span> whom the Lord destroyed. <span class=\"citation\">Num. R. s. 3</span> <span dir=\"rtl\">היה הארון מְכַלֶּה בבני וכ׳</span> the Ark made havoc among the sons of Kehath (who had charge of it; cmp. <span class=\"citation\">II Sam. VI, 7</span>). Mekh. B’shall., Amalek, s. 2 <span dir=\"rtl\">לכַלָּן</span> to destroy them. Y. Ḥag. II, 78ᵃ bot. (cited in Tosaf. to <span class=\"citation\">Ḥag. 17ᵇ</span> a. v. <a href=\"#\" data-headword=\"אֲלָא I\">אלא</a>) <span dir=\"rtl\">ובלבד שיְכַלֶּה עיסתו</span> (ed. <span dir=\"rtl\">שיבלים</span>) provided he has used up all his dough for the day; a. fr.—Part. pass. <span dir=\"rtl\">מְכוּלֶּה</span>, pl. <a href=\"#\" data-headword=\"מְכוֹלִין\">מְכוּלִּין</a>. Pesik. Shek., p. 13ᵇ כבר היו ישראל מ׳ וכ׳ Israel would then have been destroyed; a. e.</div></div><div class=\"sense\"><b>Hithpa. הִתְכַּלֶּה</b> </div><div class=\"sense\"><b>Nithpa. נִתְכַּלֶּה</b> <div class=\"sense\"><i>to be destroyed, visited by death</i>. <span class=\"citation\">Num. R. s. 5</span> <span dir=\"rtl\">היו מִתְכַּלִּין</span> they were diminished. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שלא יִתְכַּלּוּ מן וכ׳</span> that they may not be destroyed from the world. <span class=\"citation\">Num. R. s. 3</span> <span dir=\"rtl\">לא נ׳ וכ׳</span> not one of them was missing on being counted &amp;c.; a. e.</div></div>","alt":["כָּלָא","כָּלָה"]},"12578":{"h":"כְּלֵי","r":"K00716","html":"<div class=\"sense\"><b>1)</b> <i>to keep enclosed, to withhold, restrain</i>. <span class=\"citation\">Targ. I Sam. VI, 10</span>. <span class=\"citation\">Targ. Ps. XXI, 3</span>. <span class=\"citation\">Targ. Is. XXXIII, 15</span> <a href=\"#\" data-headword=\"כָּאלָא\">כָּלֵי</a> (ed. Wil. <a href=\"#\" data-headword=\"כָּל\">כָּל</a>) restrains his eyes. <span class=\"citation\">Targ. Prov. XI, 26</span> <a href=\"#\" data-headword=\"כָּאלָא\">כָּאלֵא</a> ed. Lag.; <span class=\"citation\">ib. XVII, 28</span> <a href=\"#\" data-headword=\"כָּאלָא\">כָּאלֵי</a> ed. Lag.—Part. pass. <a href=\"#\" data-headword=\"כְּלֵי\">כְּלֵי</a>. <span class=\"citation\">Targ. Jer. XXXII, 2</span>; (<span class=\"citation\">Targ. Ps. LXXXVIII, 9</span> <a href=\"#\" data-headword=\"כָּלוּ\">כָּלוּא</a>, h. form).—<span class=\"citation\">Sabb. 57ᵇ</span> <span dir=\"rtl\">כַּלְיָא פרוחי</span>, v. <a href=\"#\" data-headword=\"בִּזְיוּנָא I\"><span dir=\"rtl\">בִּזְיוּנָא</span> I</a>; [Var. Ar. <span dir=\"rtl\">דידבי</span>, reminiscence fr. <span class=\"citation\">Nidd. 17ᵃ</span>, v. <a href=\"#\" data-headword=\"בָּאלֵי\">בָּאלֵי</a>.]—<span dir=\"rtl\">כַּלְיָא עורב</span>, v. <a href=\"#\" data-headword=\"כלי\">preced.</a></div><div class=\"sense\"><b>—2)</b> <i>to be finished, gone</i>. <span class=\"citation\">Ber. 39ᵃ</span> <span dir=\"rtl\">כַּלְיָא ברכה</span> the benediction is finished &amp;c., v. <a href=\"#\" data-headword=\"כלי\">preced.</a> <span class=\"citation\">B. Mets. 79ᵃ</span> <span dir=\"rtl\">וקא כליא קרנא</span> and the capital itself is used up (v. infra). <span class=\"citation\">Yoma 69ᵇ</span> <span dir=\"rtl\">כ׳ עלמא</span> the world would come to an end; a. fr.</div><div class=\"sense\"><b>—3)</b>  (cmp. <span dir=\"rtl\">שלם</span>) [<i>to be entirely with</i>,] <i>to trust</i>. <span class=\"citation\">Targ. Ps. XXXI, 7</span>. <span class=\"citation\">Ib. 25</span> <span dir=\"rtl\">כַּלְיָין</span> (ed. Lag. a. oth. <span dir=\"rtl\">כיילין</span>, corr. acc.). <span class=\"citation\">Ib. XXXII, 10</span>; a. e.; v. <a href=\"#\" data-headword=\"תְּכַל\">תְּכַל</a>. [Differ. fr. b. h. <a href=\"#\" data-headword=\"כָּלָה\">כָּלָה</a> <i>to be consumed</i> by anxiety, <i>to long, die for</i>.]</div><div class=\"sense\"><b>Af. אַכְלֵי</b> <div class=\"sense\"><i>to lock up, restrain</i>. <span class=\"citation\">Targ. II Chr. VII, 13</span>.—<span class=\"citation\">Kidd. 81ᵇ</span> מַכְלֵי להו מִכּוּלָּהּ וכ׳ Ar. a. Tosaf. (ed. <span dir=\"rtl\">מכלליה</span>, read: <span dir=\"rtl\">מכלי ליה</span>) kept the cattle off from the entire field (in which he walked); (ed.: kept himself aloof from the entire pasture ground). <span class=\"citation\">B. Bath. 5ᵃ</span>, v. <a href=\"#\" data-headword=\"כְּלֵי ²\">next w.</a></div></div><div class=\"sense\"><b>Pa. כַּלֵּי</b> <div class=\"sense\"><i>to destroy, use up, diminish</i>. B. Mets. l. c. <span dir=\"rtl\">מְכַלִּינָן קרנא</span> (when hiring the usufruct of an object,) we are permitted to use up the stock itself, e.g. if you hired an ass for travelling, and it died on the road, you may sell its carcass, and hire another ass for the money; ib. <span dir=\"rtl\">לא מכ׳ קרנא</span> we must not use up the stock, i.e. you may <i>buy</i> another ass for the carcass, but not hire one. Ib. Ms. M. <span dir=\"rtl\">לכַלּוּיֵי קרנא לא חיישינן</span> (v. Rabb. D. S. a. l. note 8) and as for using up the stock, we need not take that into consideration. <span class=\"citation\">B. Kam. 3ᵃ</span> <span dir=\"rtl\">דמְכַלְּיָא קרנא</span> when the obnoxious subject destroys the object itself (not only the fruits).</div></div><div class=\"sense\"><b>Ithpe. אִתְכְּלִי</b> <div class=\"sense\"><i>to be closed up, withheld; to refrain</i>. <span class=\"citation\">Targ. O. Gen. VIII, 2</span>. <span class=\"citation\">Targ. Prov. III, 27</span>; a. fr.</div></div>","alt":["כְּלָא I"]},"12579":{"h":"כְּלֵי ²","r":"K00717","html":"<div class=\"sense\">, <i>Af</i>. <a href=\"#\" data-headword=\"כְּלֵי\">אַכְלֵי</a> (v. <a href=\"#\" data-headword=\"כְּלֵי\">preced.</a>) [<i>to assemble, call together</i> (cmp. <span dir=\"rtl\">אוֹכְלוֹסָא</span>),] </div><div class=\"sense\"><b>1)</b> <i>to call, give a signal</i>. <span class=\"citation\">Targ. Jer. I, 15</span>. <span class=\"citation\">Targ. Zeph. II, 15</span>; a. e.</div><div class=\"sense\"><b>—2)</b>  (of the lion) <i>to roar; to shout, thunder</i> &amp;c. <span class=\"citation\">Targ. Ps. CIV, 21</span>, v. <a href=\"#\" data-headword=\"אַכְלִי\">אַכְלִי</a>. <span class=\"citation\">Ib. XXIX, 3</span>. <span class=\"citation\">Ib. LXXIV, 4</span>; a. e.—<span class=\"citation\">B. Bath. 5ᵃ</span> <span dir=\"rtl\">עיזא בעלמא אַכְלוּיֵי מַכְלִינָן בה</span> v. Ar. s. v. <span dir=\"rtl\">כל</span>; (incorr. in eds. <span dir=\"rtl\">לאו לאכלויי בעיא</span>) as to a goat, we need only shout at her (to drive her off). Ib. <span dir=\"rtl\">ולאו גברא בעי לאכלויי</span> Rashi (ed. <span dir=\"rtl\">דמיכלי</span>, read <span dir=\"rtl\">דמַכְלֵי</span>) and need you not a man to shout at her?; [oth. opin. we need only <i>keep</i> her <i>off</i>, v. preced.]</div>","alt":["כְּלָא II"]},"12580":{"h":"כִּלְיָא","r":"K00718","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּלְיָה\">כִּלְיָה</a></div>","alt":[]},"12581":{"h":"כַּלַּיָּא","r":"K00719","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּלַּיָּיה\">כַּלַּיָּיה</a></div>","alt":[]},"12582":{"h":"כַּלְיָא","r":"K00720","html":"<div class=\"sense\">, v. <span dir=\"rtl\">כְּלִי I</span></div>","alt":[]},"12583":{"h":"כְּלִיבָא","r":"K00721","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּלִיבָה\">next w.</a></div>","alt":[]},"12584":{"h":"כְּלִיבָה","r":"K00722","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"כְּלוּב\">כְּלוּב</a>) <i>box</i>, consisting of movable tenoned links. <span class=\"citation\">Tosef. Kel. B. Mets. IX, 1</span> <span dir=\"rtl\">כ׳ של חייטין</span> the tailors’ box.—Pesik. Ănokhi, p. 138ᵃ <span dir=\"rtl\">ונתנום בכ׳</span> and put them (the Cherubs of the Temple) in a box; a. e.—Esp. <i>coffin</i> with <i>bier</i>. <span class=\"citation\">M. Kat. 27ᵃ</span>, sq. <span dir=\"rtl\">ועניים בכ׳</span> (not <span dir=\"rtl\">בכליכה</span>) and the poor were carried out on a common bier; opp. <a href=\"#\" data-headword=\"דַּרְגֵּשׁ\">דרגש</a>; <span class=\"citation\">Tosef. Nidd. IX, 16</span> <span dir=\"rtl\">בכְלִיבָא</span>. <span class=\"citation\">Par. XII, 9</span> <span dir=\"rtl\">קרן של כ׳</span> the movable support of the bier, Maim.; (oth. opin.: the ring for keeping the corpse in position). <span class=\"citation\">Lam. R. to III, 16</span> <a href=\"#\" data-headword=\"כְּלִיבָא\">כליבא</a>.</div>","alt":[]},"12585":{"h":"כַּלִּיד","r":"K00723","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (χάλις, -ιδος, only in χαλιδοφόρος; κύλιξ, κάλιξ, calix) </div><div class=\"sense\"><b>1)</b> <i>cup</i>. <span class=\"citation\">Targ. II Chr. IV, 5</span>. <span class=\"citation\">Targ. O. Gen. XLIV, 12</span>, a. e. (Var. <a href=\"#\" data-headword=\"ק׳\">ק׳</a>, v. Berl. Targ. O. II, p. 16). <span class=\"citation\">Targ. Ps. XI, 6</span>; a. e.—Pl. <span dir=\"rtl\">כַּלִּידִין</span>. <span class=\"citation\">Targ. Jer. XXXV, 5</span>.</div><div class=\"sense\"><b>—2)</b> <i>calyx</i> of flowers. Pl. as ab. <span class=\"citation\">Targ. Ex. XXV, 33</span>, sq. (Ms. I <a href=\"#\" data-headword=\"ק׳\">ק׳</a>).</div>","alt":["כַּלִּידָא"]},"12586":{"h":"כלידו","r":"K00724","html":"<div class=\"sense\">, corrupt. of <span dir=\"rtl\">כלי ידים</span>, v. <a href=\"#\" data-headword=\"כְּלִי\">כֶּלִי</a></div>","alt":["כלידים","כלידרים","כלידרין"]},"12587":{"h":"כִּלְיָה","r":"K00725","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> , v. <a href=\"#\" data-headword=\"כּוֹלְיָא\">כּוֹלְיָא</a>) </div><div class=\"sense\"><b>1)</b> <i>kidney</i>. <span class=\"citation\">Y. B. Mets. II, beg. 8ᵇ</span>. <span class=\"citation\">Ḥull. 55ᵃ</span> <a href=\"#\" data-headword=\"כּוֹלְיָא\">כוליא</a>; a. fr.—Pl. <span dir=\"rtl\">כְּלָיוֹת</span>, constr. <span dir=\"rtl\">כִּלְיוֹת</span>. <span class=\"citation\">Ib. III, 2</span>. <span class=\"citation\">Ber. 61ᵃ</span>, a. e., v. <a href=\"#\" data-headword=\"יָעַץ\">יָעַץ</a>. Tanḥ. Vayigg. 11, a. e. <span dir=\"rtl\">כִּלְיוֹתָיו</span>, v. <a href=\"#\" data-headword=\"כַּד II\"><span dir=\"rtl\">כַּד</span> II</a>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>the belly</i> of a stove. <span class=\"citation\">B. Bath. II, 11</span> <span dir=\"rtl\">כליא</span> (Ms. F. a. H. <a href=\"#\" data-headword=\"כִּילְיָא\">כיליא</a>). <span class=\"citation\">Ib. 20ᵇ</span> <span dir=\"rtl\">כ׳ דתנור טפח</span> the protuberance of the belly of the stove is one hand-breadth beyond the rim; <span class=\"citation\">Tosef. ib. I, 3</span> <a href=\"#\" data-headword=\"כִּילְיָא\">כיליא</a> ed. Zuck. (Var. <a href=\"#\" data-headword=\"כִּלְיָיה\">כִּלְיָיה</a>, <a href=\"#\" data-headword=\"כּוּלְיָה\">כּוּלְיָיה</a>). [R. Ḥănanel: <a href=\"#\" data-headword=\"כִּילְיָא\">כיליא</a> = κοιλία.]</div>","alt":["כּוּלְיָה","יָא"]},"12588":{"h":"כְּלָיָה","r":"K00726","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּלָיָיה\">כְּלָיָיה</a></div>","alt":[]},"12589":{"h":"כליונים","r":"K00727","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Kel. B. Bath. VII, 2</span>, v. <a href=\"#\" data-headword=\"כְּלוֹנָס\">כְּלוֹנָס</a></div>","alt":[]},"12590":{"h":"כַּלְיוּתָא","r":"K00728","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (כְּלֵי I 3) <i>cheer, trust.</i> <span class=\"citation\">Targ. Ps. CXIX, 116</span> Ms. (ed. <a href=\"#\" data-headword=\"כִּילְבִּית\">כִּלְ׳</a>; h. text <span dir=\"rtl\">שׂבר</span>).</div>","alt":[]},"12591":{"h":"כַּלַּיָּיה","r":"K00729","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"כַּלָּה\">כַּלָּה</a>) [<i>crowns, ornaments</i>,] <i>brides</i>. <span class=\"citation\">Y. Ab. Zar. III, 42ᶜ</span> top; <span class=\"citation\">Y. Peah I, 15ᵈ</span>.—<span class=\"citation\">Targ. Y. Deut. XXIV, 6</span> <span dir=\"rtl\">חתנין וכַלִּין</span> (h. text <span dir=\"rtl\">רחים ורכב</span>).—[<span class=\"citation\">Targ. Y. II, Gen. XVIII, 21</span> <a href=\"#\" data-headword=\"כַּלַּיָּיה\">כַּלַּיָּיה</a>, v. <a href=\"#\" data-headword=\"כְּלָיָיה\">כְּלָיָיה</a>.]</div>","alt":["כַּלַּיָּא"]},"12592":{"h":"כִּלְיָיה","r":"K00730","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּלְיָה\">כִּלְיָה</a></div>","alt":[]},"12593":{"h":"כְּלָיָיה","r":"K00731","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּלָה\">כָּלָה</a>) <i>destruction, diminution, extinction.</i> <span class=\"citation\">Ab. V, 8</span> <span dir=\"rtl\">רעב של כ׳</span> a destructive famine (general miscrop). <span class=\"citation\">Y. Ber. II, 5ᶜ</span> bot. <span class=\"citation\">Snh. 63ᵃ</span> <span dir=\"rtl\">נתחייבו שונאיהם … כ׳</span> the enemies of Israel (censorial change <span dir=\"rtl\">רשעיהם</span>, euphem. for <i>Israel</i>) would have been condemned to destruction. <span class=\"citation\">Gen. R. s. 10</span> אין ויכלו … לשון כ׳ <i>vaykhullu</i> (<span class=\"citation\">Gen. II, 1</span>) has the meaning of affliction, of diminution (ref. to the reduction of the planetary courses after Adam’s sin). <span class=\"citation\">Gen. R. s. 49</span> (expl. <span dir=\"rtl\">כלה</span>, <span class=\"citation\">Gen. XVIII, 21</span>) <span dir=\"rtl\">כ׳ הן חייבין</span> they deserve extinction; [Targ. Y. II, Gen. l. c. <span dir=\"rtl\">כַּלַּיָּיה עבדו גמירא</span>, read: <span dir=\"rtl\">עבדו כְּלָיָיה גמירא</span>]. Mekh. B’shall., Shirah, s. 5 <span dir=\"rtl\">גמרת … כ׳</span> thou hast passed the verdict of destruction &amp;c.; a. fr.</div>","alt":[]},"12594":{"h":"כליכה","r":"K00732","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּלִיבָה\">כְּלִיבָה</a></div>","alt":[]},"12595":{"h":"כָּלִיל","r":"K00733","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>entire</i>, esp. <i>Kalil, a sacrifice burnt entirely</i>. Sifra Tsav, Par. 3, ch. V; <span class=\"citation\">Men. 51ᵇ</span> <span dir=\"rtl\">בכ׳ תקטר</span> shall be burned as a <i>Kalil</i>. <span class=\"citation\">Y. Sot. III, 19ᵇ</span> top <span dir=\"rtl\">קריבה בכלול</span> is offered as a <i>K</i>.—<span class=\"citation\">Men. 74ᵃ</span>; a. e.—<span class=\"citation\">Tosef. Par. I, 2</span>; <span class=\"citation\">Zeb. V, 4</span> <span dir=\"rtl\">כ׳ לאישים</span>, v. <a href=\"#\" data-headword=\"אִישֶּׁה\">אִישֶּׁה</a>.</div>","alt":["(כָּלוּל)"]},"12596":{"h":"כְּלִיל","r":"K00734","html":"<div class=\"sense\"> c. (<a href=\"#\" data-headword=\"כְּלַל\">כְּלַל</a>) </div><div class=\"sense\"><b>1)</b> <i>circle, wreath, crown</i>. <span class=\"citation\">Targ. Y. II, Ex. XXV, 11</span>. <span class=\"citation\">Targ. Num. VI, 7</span> (h. text <a href=\"#\" data-headword=\"נֵזֶר\">נֵזֶר</a>). <span class=\"citation\">Targ. Y. I Deut. XIV, 1</span> <span dir=\"rtl\">כ׳ דיסער</span> (cmp. <a href=\"#\" data-headword=\"כִּלְכּוּל\">כִּלְכּוּל</a>). <span class=\"citation\">Ib. XXXIV, 5</span> fem. (also <a href=\"#\" data-headword=\"כְּלִיל\">כְּלִילַת</a> constr.). <span class=\"citation\">Targ. Is. XXVIII, 5</span>; a. fr.—<span class=\"citation\">Sabb. 152ᵃ</span>, v. <a href=\"#\" data-headword=\"חִילְפָא II\"><span dir=\"rtl\">חִילְפָא</span> II</a>. <span class=\"citation\">Gen. R. s. 98</span>, end (ref. to <span dir=\"rtl\">נזיר</span>, <span class=\"citation\">Gen. XLIX, 26</span>) <span dir=\"rtl\">כְּלִילֵיהוֹן דאחוך</span> the crown of thy brothers. <span class=\"citation\">Gitt. 7ᵃ</span> <span dir=\"rtl\">כ׳ לברתיה</span> a bridal wreath for his daughter. <span class=\"citation\">B. Bath. 4ᵃ</span>, v. <a href=\"#\" data-headword=\"יָילָא\">יָילָא</a>; a. e.—Pl. <span dir=\"rtl\">כְּלִילַיָּא</span>, <a href=\"#\" data-headword=\"כְּלִיל\">כְּלִילָן</a>, <a href=\"#\" data-headword=\"כְּלִילָאֵי\">כְּלִילֵי</a>. Targ. Y. Deut. l. c. <span class=\"citation\">Targ. Job XXXI, 36</span>. <span class=\"citation\">Targ. Jud. VIII, 26</span> ed. Lag. (oth. ed. <i>sing</i>.); a. e.—<span class=\"citation\">B. Bath. 16ᵇ</span> כלילי הוו להו Ms. M. (ed. <i>sing</i>.) they had wreaths (each dedicated to a friend).</div><div class=\"sense\"><b>—2)</b>  <span dir=\"rtl\">דמי כ׳</span> or <a href=\"#\" data-headword=\"כ׳\">כ׳</a> <i>coronation tax</i> (aurum coronarium, v. Sm. Ant. s. v.). Ib. 8ᵃ <span dir=\"rtl\">כההוא דמי כ׳ וכ׳</span> as in the case of a coronation tax which they put on the city of Tiberias. Ib. <span dir=\"rtl\">פקע כ׳</span> (Ms. M. <a href=\"#\" data-headword=\"בָּטֵל I\">בטל</a>) the tax was repealed.</div><div class=\"sense\"><b>—3)</b>  <span dir=\"rtl\">כ׳ מלכא</span> or <a href=\"#\" data-headword=\"כ׳\">כ׳</a> <i>melilot</i>. <span class=\"citation\">Keth. 77ᵇ</span>. <span class=\"citation\">Sabb. 109ᵇ</span> <span dir=\"rtl\">חד כ׳</span> one dose of melilot.—Pl. <a href=\"#\" data-headword=\"כְּלִילָאֵי\">כְּלִילֵי</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">חמשא כ׳</span> five parts of melilot (Rashi: roses). [Y. M. Kat. II, 81ᵈ bot. <span dir=\"rtl\">וגנבון מנהין כליליא</span>, read: <span dir=\"rtl\">כל ליליא</span>.]</div>","alt":["כְּלִילָא"]},"12597":{"h":"כְּלִילָאֵי","r":"K00735","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"כְּלִיל\">preced.</a>) <i>coronation tax</i>. Meg. Taan. II <span dir=\"rtl\">אתנטילו כ׳</span> the coronation tax was remitted (v. <span class=\"citation\">I Macc. XIII, 39</span>); [Scholion to Meg. Taan.: <i>wreaths</i>, an idolatrous rite forced upon the Jews by the Syrians.]</div>","alt":[]},"12598":{"h":"כְּלִילְתָּא","r":"K00736","html":"<div class=\"sense\">, constr. <a href=\"#\" data-headword=\"כְּלִיל\">כְּלִילַת</a>, v. <a href=\"#\" data-headword=\"כְּלִיל\">כְּלִיל</a></div>","alt":[]},"12599":{"h":"כְּלִימָּה","r":"K00737","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>disgrace</i>, usu. with <a href=\"#\" data-headword=\"בּוּשָׁה\">בּוּשָׁה</a>. <span class=\"citation\">B. Bath. 75ᵃ</span>; a. fr.</div>","alt":[]},"12600":{"h":"כלימך","r":"K00738","html":"<div class=\"sense\">, <span class=\"citation\">Ex. R. s. 15</span> Mus., read: <span dir=\"rtl\">כל הימך</span>, v. <a href=\"#\" data-headword=\"הֵימ־\">הֵימ־</a></div>","alt":[]},"12601":{"h":"כַּלִּין","r":"K00739","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּלַּיָּיה\">כַּלַּיָּיה</a></div>","alt":[]},"12602":{"h":"כָּלִינוֹס","r":"K00740","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (χαλινός) <i>bridle</i>. Tanḥ. Balak 13 <a href=\"#\" data-headword=\"כַּלְבּוּס\">כלבוס</a> (corr. acc.); <span class=\"citation\">Num. R. s. 20</span> <a href=\"#\" data-headword=\"בלינוס\">בלינוס</a>; Y’lamd. to Num. XXIII, 5 quot. in Ar., v. <a href=\"#\" data-headword=\"פָּקַם\">פָּקַם</a>.—<span class=\"citation\">Ab. d’R. N. ch. XXIV</span> לסוס שיש לו כלינס Ar. (ed. <span dir=\"rtl\">כלים נאים</span>, Var. <a href=\"#\" data-headword=\"כְּלוֹנָס\">כלונס</a>, corr. acc.) like a horse which is bridled. <span class=\"citation\">Tosef. Kel. B. Mets. IV, 7</span> <a href=\"#\" data-headword=\"כלינס\">כלינס</a>, <a href=\"#\" data-headword=\"כלוניס\">כלוניס</a>, <a href=\"#\" data-headword=\"כולוניס\">כולוניס</a> (corr. acc.). <span class=\"citation\">Pesik. R. s. 42</span> <span dir=\"rtl\">בל׳</span> (corr. acc.)</div>","alt":[]},"12603":{"h":"כְּלִינִידִין","r":"K00741","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (χλανίδιον meant for χλαμύδιον, cmp. Cast. Lex. Syr. s. v.) <i>a fine mantle</i>, an officer’s distinction. <span class=\"citation\">Y. Snh. X, 29ᵃ</span> top, v. <a href=\"#\" data-headword=\"זוֹנָרָא\">זוֹנָרָא</a>.</div>","alt":[]},"12604":{"h":"כלינס","r":"K00742","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כָּלִינוֹס\">כָּלִינוֹס</a></div>","alt":[]},"12605":{"h":"כְּלִינְסָא","r":"K00743","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּלוֹנְסָא\">כְּלוּנְסָא</a></div>","alt":[]},"12606":{"h":"כָּלִיס","r":"K00744","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, pl. <span dir=\"rtl\">כְּלִיסִים</span>, <span dir=\"rtl\">כְּלִיסִין</span> (<span dir=\"rtl\">כלס</span>, enlarg. of <span dir=\"rtl\">כל</span>; cmp. Ges. H. Dict.<sup>10</sup> s. v. <span dir=\"rtl\">כרשׂ</span>) <i>bags</i>. <span class=\"citation\">Tosef. Kil. V, 26</span> <span dir=\"rtl\">אהולין והכ׳ הגרגים וכ׳</span> ed. Zuck. tents and bags, filters &amp;c., v. <a href=\"#\" data-headword=\"*אכסלי\">אכסלי</a>.—Trnsf. <i>pods, a dehiscent fruit</i>, similar to carob. <span class=\"citation\">Ter. XI, 4</span> כ׳ וחרובים <i>k’lisin</i> and carobs; <span class=\"citation\">Ukts. I, 6</span> <a href=\"#\" data-headword=\"כָּלוּ\">כְּלוּ׳</a> (Maim.: a species of <i>figs</i>, v. <a href=\"#\" data-headword=\"כְּלוּפְסִין\">כְּלוּפְסִין</a>).—<span class=\"citation\">Ḥull. 67ᵇ</span> (a species of <i>peas</i>, Rashi); Sifra Sh’mini, Par. 10, ch. XII, a. e. <span dir=\"rtl\">יתושין שבכ׳</span> the bugs found in &amp;c.; Y. Ter. VIII, 45ᵇ bot. <span class=\"citation\">Tosef. Ter. V, 7</span>; <span class=\"citation\">Y. Bicc. III, beg. 65ᶜ</span>; a. e.—[<span class=\"citation\">Ukts. III, 2</span>, v. <a href=\"#\" data-headword=\"בּוּלְבּוֹס\">בּוּלְבּוֹס</a>. Y. Maasr. II, 50ᵃ, v. <a href=\"#\" data-headword=\"כְּלוּפְסִין\">כְּלוּפְסִין</a>.]</div>","alt":[]},"12607":{"h":"כליסריקים","r":"K00745","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כלירכין\">next w.</a></div>","alt":[]},"12608":{"h":"כלירכין","r":"K00746","html":"<div class=\"sense\">, read: <span dir=\"rtl\">כִּילְיָירְכִין</span> m. pl. (χιλιάρχοι, chiliarchi) <i>chiliarchs</i>, commanders of one thousand soldiers. <span class=\"citation\">Koh. R. to XII, 7</span> (expl. <span dir=\"rtl\">לשום כרים</span>, <span class=\"citation\">Ez. XXI</span>, 27ᵃ) <span dir=\"rtl\">(<span dir=\"rtl\">כלור׳</span>) <a href=\"#\" data-headword=\"כלירכין\">כלירכין</a></span> to appoint chiliarchs; [Lam. R., introd. (R. <span class=\"citation\">Josh. 2</span>) <span dir=\"rtl\">פלימרכים</span>, v. <a href=\"#\" data-headword=\"פּוֹלִימַרְכוֹס\">פּוֹלִימַרְכוֹס</a>.]—<span class=\"citation\">Sifré Deut. 317</span> (expl. <a href=\"#\" data-headword=\"כרים\">כרים</a>, <span class=\"citation\">Deut. XXXII, 14</span>) <span dir=\"rtl\">אלו כאליריקין שלהם</span> (ed. Fr. <a href=\"#\" data-headword=\"כליסריקים\">כליסריקים</a>, corr. acc.) this refers to their (the Roman) chiliarchs; <span class=\"citation\">Yalk. Deut. 944</span> <a href=\"#\" data-headword=\"כלירקין\">כלירקין</a>.</div>","alt":[]},"12609":{"h":"כלירקין","r":"K00747","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כלירכין\">preced.</a></div>","alt":[]},"12610":{"h":"כְּלֵיתָא","r":"K00748","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כָּלוּ\">כָּלוּ</a></div>","alt":[]},"12611":{"h":"כַּלָּךְ","r":"K00749","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"כּוּלְּכָא\">כּוּלְכָא</a>) <i>cissaros-blossoms</i>, a woolly substance, v. <a href=\"#\" data-headword=\"*אַגְבִּין\">אַגְבִּין</a>. <span class=\"citation\">Kil. IX, 2</span>, expl. Y. ib. 32ᵃ top <span dir=\"rtl\">אגבין קיסריי</span>. <span class=\"citation\">Sabb. II, 1</span>. <span class=\"citation\">Ib. 20ᵇ</span> <span dir=\"rtl\">היינו כ׳</span> this (metaxa) is <i>kallakh</i>. Ib.; <span class=\"citation\">Men. 39ᵇ</span> <span dir=\"rtl\">השיראים והכ׳ וכ׳</span> (garments of) silk, <i>K</i>. &amp;c. (v. <a href=\"#\" data-headword=\"סְרִיקִין\">סְרִיקִין</a>). <span class=\"citation\">Sabb. 27ᵃ</span>. <span class=\"citation\">Tosef. ib. IX</span> (<span class=\"citation\">X), 3</span> צמר כ׳ <i>Kallakh</i> wool. <span class=\"citation\">Tosef. Kel. B. Bath. V, 11</span> <a href=\"#\" data-headword=\"כּוּלָּךְ\">כולך</a> ed. Zuck. (R. S. to <span class=\"citation\">Kel. XXVIII, 8</span> <span dir=\"rtl\">כלך</span>).</div>","alt":[]},"12612":{"h":"כַּלֵּךְ","r":"K00750","html":"<div class=\"sense\"> (contr. of <span dir=\"rtl\">כַּלֵּה וָלֵךְ</span>, v. <a href=\"#\" data-headword=\"כָּלָה\">כָּלָה</a>) <i>cease and turn!, go!</i> <span class=\"citation\">Yeb. 44ᵃ</span> <span dir=\"rtl\">כ׳ אצל שכמותך</span> turn towards one corresponding to thine own age. <span class=\"citation\">B. Mets. 22ᵃ</span> <span dir=\"rtl\">כ׳ אצל יפות</span> go to better fruits (to take T’rumah from); <span class=\"citation\">Erub. 71ᵃ</span>. <span class=\"citation\">B. Bath. 164ᵇ</span> <span dir=\"rtl\">כ׳ מלשון וכ׳</span> turn away from this kind of slander. Sifra Thazr., Neg., Par. 2, ch. II <span dir=\"rtl\">או כ׳ לדרך זו</span> or turn this way, i.e. I may argue thus; (ib. Emor, Par. 12, ch. XVII <span dir=\"rtl\">או לכה וכ׳</span>). Ib. Vayikra, Ḥobah, Par. 7, ch. XI <span dir=\"rtl\">או כ׳ לך</span> (corr. acc.); a. e.</div>","alt":[]},"12613":{"h":"כִּלְכּוּל","r":"K00751","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כִּלְכֵּל\">כִּלְכֵּל</a>) </div><div class=\"sense\"><b>1)</b> <i>hair-crown</i> (cmp. <a href=\"#\" data-headword=\"כְּלִיל\">כְּלִילָא</a>), <i>front hair</i> from temple to temple. <span class=\"citation\">Sabb. VIII, 4</span> (<span class=\"citation\">78ᵇ</span>) <span dir=\"rtl\">כדי לעשות כ׳</span> (Bab. ed. <span dir=\"rtl\">כלכל</span>; Ms. M. <span dir=\"rtl\">כדי לסוד כי׳</span>, v. Rabb. D. S. a. l. note) enough to produce a crown by depilation of undergrowth. Ib. 80ᵇ, v. <a href=\"#\" data-headword=\"*אַנְדִּיפֵי\">אַנְדִּיפֵי</a>. <span class=\"citation\">Naz. 3ᵃ</span> (ref. to Mish. <span class=\"citation\">ib. I, 1</span> <span dir=\"rtl\">הריני מכלכל</span>) how do we know <span dir=\"rtl\">דהאי כ׳ שערו הוא</span> that this vow refers to letting the hair grow?—<span class=\"citation\">Nidd. 52ᵇ</span>; <span class=\"citation\">Tosef. ib. VI, 6</span> (ref. to the hair around the pudenda as evidence of maturity) <span dir=\"rtl\">כ׳ זה איני יודע</span> (<a href=\"#\" data-headword=\"מָהוּ\">מהו</a>) about this <i>kilkul</i> I know nothing.</div><div class=\"sense\"><b>—2)</b> <i>support, sustenance</i>. Naz. l. c. <span dir=\"rtl\">אימא מיזן עניי</span> I may say that the <i>kilkul</i> (of the Mishnah, v. supra) means supporting the poor.</div>","alt":["כִּילְ׳","כַּלְכָּל"]},"12614":{"h":"*כַּלְכּוּס","r":"K00752","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (χαλκός) <i>a copper, caldron</i>. <span class=\"citation\">B. Kam. 100ᵇ</span> (ref. to Mish. <span class=\"citation\">ib. IX, 4</span> <span dir=\"rtl\">צבאו כעור</span>) [read:] <span dir=\"rtl\">מאי כעור … שצבעו כ׳</span> (v. Rabb. D. S. a. l. note 50) what does, ‘he dyed it <i>kaʿur’</i> mean?… the copper dyed it (cmp. <span dir=\"rtl\">הקדיח׳ היורה</span> ib.); <span dir=\"rtl\">מאי שצבעו כ׳ כפרא דודי</span> (Ms. H.) what does it mean &amp;c.? The sediment of kettles. [Editions a. Mss. have <a href=\"#\" data-headword=\"כַּלְבּוּס\">כלבוס</a>, <a href=\"#\" data-headword=\"קלבוס\">קלבוס</a> with <a href=\"#\" data-headword=\"ב\">ב</a>].—Pl. <span dir=\"rtl\">כַּלְקִין</span>. Y. B. Bath. IV, 14ᶜ bot. <a href=\"#\" data-headword=\"בסלקי\">בסלקי</a>, (read: <span dir=\"rtl\">בית כלקין</span>, corresp. to <span dir=\"rtl\">בית היורות</span> <span class=\"citation\">Tosef. B. Bath. III, 3</span>) the copper room.</div>","alt":[]},"12615":{"h":"כַּלְכִּיד","r":"K00753","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (χαλκίς, -ίδος) <i>chalkis</i>, a small fish resembling sardines (v. Sm. Ant. s. v.). <span class=\"citation\">Y. Ned. VI, 39ᶜ</span> bot. if one says, I will taste no <a href=\"#\" data-headword=\"דָּגָה\">דָּגָה</a>, <span dir=\"rtl\">אינו … אלא בכ׳</span> he is forbidden ony <i>ch</i>. (small fish). Ib.ᵈ top <span dir=\"rtl\">כיל׳ אנא טעים</span> I feel as if I were eating <i>ch</i>.—<span class=\"citation\">Ib.</span> <span dir=\"rtl\">לית … והוא זבין ליה כ׳</span> is it not often the case when a man says to his neighbor, buy me a fish, that he will buy <i>ch</i>. for him?—Y. Erub. III, 20ᵈ top <a href=\"#\" data-headword=\"כלבודא\">כלבודא</a> (corr. acc.); Y. Peah VIII, 21ᵃ top <span dir=\"rtl\">(<span dir=\"rtl\">סלק׳</span>) <a href=\"#\" data-headword=\"כלקורא\">כלקורא</a></span>, read: <a href=\"#\" data-headword=\"כַּלְקִירָא\">כַּלְקִידָא</a>.</div>","alt":["כַּלְכִּידָא"]},"12616":{"h":"כִּלְכִּית","r":"K00754","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּלְכּוּל\">כִּילְ׳</a></div>","alt":[]},"12617":{"h":"כִּלְכֵּל","r":"K00755","html":"<div class=\"sense\"> [<i>to surround</i>,] </div><div class=\"sense\"><b>1)</b> <i>to provide with everything; to sustain</i>. <span class=\"citation\">Naz. 3ᵃ</span>, v. <a href=\"#\" data-headword=\"כִּלְכּוּל\">כִּלְכּוּל</a>. <span class=\"citation\">Ber. 58ᵇ</span> <span dir=\"rtl\">וכ׳ אתכם בדין וכ׳</span> and provided for you (while alive) in justice, and gathered you in justice.</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"כְּלִיל\">כְּלִילָא</a>) <i>to raise a crown of hair, to be a nazir.</i> <span class=\"citation\">Naz. I, 1</span> הריני מְכַלְכֵּל I will grow a crown (as a substitute for, ‘I will be a <i>nazir</i>’, v. <a href=\"#\" data-headword=\"כִּינּוּי\">כִּינּוּי</a>). Y. ib. 51ᵇ top <span dir=\"rtl\">כאומר הריני מן המְכַלְכְּלִין</span> as if he said, I will be one of those who wear a crown of hair.—<span class=\"citation\">Tosef. Nidd. VI, 6</span>; <span class=\"citation\">Nidd. 52ᵇ</span> <span dir=\"rtl\">עד שתְּכַלְכֵּל</span> (euphem.) until she has a full growth of hair (around the pudenda).—</div><div class=\"sense\"><b>*3)</b>  denom. of <a href=\"#\" data-headword=\"כְּלִי\">כֶּלִי</a>) <i>to arm, fit out</i>. <span class=\"citation\">Midr. Till. to Ps. VII</span> <span dir=\"rtl\">א&quot;ל הקב&quot;ה ולא אני כלכלתי בה</span> (read: <span dir=\"rtl\">כִּלְכַּלְתּיו</span>) said the Lord to him (Doëg), is it not I that fitted him (David) out with it (the sword of Goliath deposited in the Sanctuary)?—[The entire sentence is missing in ed. Bub.; note 69 a. l. quotes fr. mss. <span dir=\"rtl\">קלקלתי</span>.]</div><div class=\"sense\"><b>Nithpalp. נִתְכַּלְכֵּל</b> <div class=\"sense\"><i>to be supported</i>. <span class=\"citation\">Pesik. R. s. 4</span> <span dir=\"rtl\">אליהו נ׳ וכ׳</span> (not <span dir=\"rtl\">נתבלבל</span>) Elijah was supported by the woman of Zarephath.</div></div>","alt":[]},"12618":{"h":"כַּלְכָּל","r":"K00756","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּלְכּוּל\">כִּלְכּוּל</a></div>","alt":[]},"12619":{"h":"כַּלְכָּלָה","r":"K00757","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כַּלְכָּל\">preced. art.</a>) </div><div class=\"sense\"><b>1)</b> <i>support, provision</i>. <span class=\"citation\">Ber. 44ᵃ</span> <span dir=\"rtl\">על המחיה ועל הכ׳</span> (be blessed &amp;c.) for sustenance and support.</div><div class=\"sense\"><b>—2)</b> <i>supply</i>, esp. <i>basket containing chosen fruits</i> designated for use. <span class=\"citation\">Eduy. IV, 10</span> (<span class=\"citation\">9</span>); <span class=\"citation\">Maasr. IV, 2</span> <span dir=\"rtl\">כַּלְכָּלַת שבת</span> supply of fruits for the Sabbath (not for sale). Ib. <span dir=\"rtl\">הלוקט הכ׳ וכ׳</span> he who selects figs to send as a present. Y. ib. IV, 51ᵇ כ׳ שבת אינה וכ׳ Sabbath supply must not be sold. <span class=\"citation\">Y. Ter. II, end, 41ᵈ</span> <span dir=\"rtl\">תאינים שבכ׳</span> figs in the provision basket, opp. <a href=\"#\" data-headword=\"מוּקְצֶה\">מוּקְצֶה</a>. <span class=\"citation\">Y. Dem. I, 21ᶜ</span> bot. <span dir=\"rtl\">כ׳ אחת וכ׳</span> there is only one basketful (of the late fruits) which I reserve &amp;c. <span class=\"citation\">Lev. R. s. 33</span>, beg. <span dir=\"rtl\">כ׳ של תאנים</span> a basket of figs for use (subject to tithes even for luncheon, v. <a href=\"#\" data-headword=\"טֶבֶל\">טֶבֶל</a>); a. fr.—Pl. <span dir=\"rtl\">כַּלְכָּלוֹת</span>. <span class=\"citation\">Dem. VII, 6</span>; a. fr.</div>","alt":[]},"12620":{"h":"כָּלַל","r":"K00758","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"כּוּל\">כּוּל</a>) </div><div class=\"sense\"><b>1)</b> <i>to surround, comprise, include</i>. <span class=\"citation\">Gen. R. s. 4</span> <span dir=\"rtl\">חזר וכְלָלָן כולן וכ׳</span> (not <span dir=\"rtl\">וכללו כולו</span>) he again included them all in the praise (<span class=\"citation\">Gen. I, 31</span>). <span class=\"citation\">Shebu. 23ᵇ</span> <span dir=\"rtl\">בכוֹלֵל המותרים וכ׳</span> when he (in his vow) includes permitted things as well as forbidden things. <span class=\"citation\">Ib. 24ᵃ</span>, a. fr. <span dir=\"rtl\">איסור כולל</span>, v. <a href=\"#\" data-headword=\"אִיסּוּר I\">אִיסּוּר</a>. <span class=\"citation\">R. Hash. IV, 5</span> <span dir=\"rtl\">וכולל מלכיות עמהן</span> and inserts that section of prayers concerning the divine rulership, v. <a href=\"#\" data-headword=\"מַלְכוּת\">מַלְכוּת</a>; a. fr.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"כָּלוּל\">כָּלוּל</a>, f. <span dir=\"rtl\">כְּלוּלָה</span> a) <i>included</i>. <span class=\"citation\">Y. Pes. V, 32ᶜ</span> bot. <span dir=\"rtl\">ירידת גשמים כ׳ וכ׳</span> the praise for the rain-fall is included therein (<span class=\"citation\">Ps. CXXXV, 7</span>); <span class=\"citation\">Y. Taan. III, 67ᵃ</span>, end.—<span class=\"citation\">Y. Ber. I, 3ᶜ</span> top <span dir=\"rtl\">עשרת הדברות כְּלוּלִין בהן</span> the Ten Commandments are contained therein.—b) <i>entire</i>, v. <a href=\"#\" data-headword=\"כָּלִיל\">כָּלִיל</a>.</div><div class=\"sense\"><b>—2)</b> <i>to generalize</i> (v. <a href=\"#\" data-headword=\"כְּלָל\">כְּלָל</a>). <span class=\"citation\">B. Kam. 63ᵃ</span> <span dir=\"rtl\"><span dir=\"rtl\">חזר</span> (<span dir=\"rtl\">הדר</span>) <span dir=\"rtl\">וכ׳</span></span> the text generalizes again.—[<span class=\"citation\">Y. Ab. Zar. IV, 44ᵇ</span> top <span dir=\"rtl\">טוחנין … כוללין</span>, read: <a href=\"#\" data-headword=\"כּוֹבְלִין\">כּוֹבְרִין</a>, v. <a href=\"#\" data-headword=\"כָּבַר\">כָּבַר</a>.]</div><div class=\"sense\"><b>Nif. נִכְלָל</b> <div class=\"sense\"><i>to be implied, to be stated in general terms</i>, opp. <a href=\"#\" data-headword=\"פָּרַט\">נפרט</a>. Y. Sot. VII, 21ᵈ top <span dir=\"rtl\">דברים שנִכְלָלוּ ונפרטו</span> things which have been stated both implicitly and specifically.</div></div><div class=\"sense\"><b>Pi. כִּילֵּל</b> <div class=\"sense\"><b>1)</b> <i>to crown</i>. Tanḥ. R’eh 7 <span dir=\"rtl\">אם נוצחין … ומְכַלְּלִין אותו</span> when they (the legions) are victorious, they come and make a wreath, and crown him (the king).</div><div class=\"sense\"><b>—2)</b> <i>to include, imply.</i> <i> Part. pass</i>. <span dir=\"rtl\">מְכוּלָּל</span>, pl. <span dir=\"rtl\">מְכוּלָּלִים</span> <i>enclosed</i> (as a germ), <i>potential</i>. <span class=\"citation\">Gen. R. s. 10</span> (ref. to <span dir=\"rtl\">ויכלו</span>, <span class=\"citation\">Gen. II, 1</span>) <span dir=\"rtl\">מ׳ היו המעשים</span> things had been created potentially, and then they developed more and more.—[Y. Ber. VI, 10ᵃ top <span dir=\"rtl\">יכללו</span>, read: <span dir=\"rtl\">יִבָּלֲלוּ</span>, v. <a href=\"#\" data-headword=\"בָּלַל\">בָּלַל</a>.]</div></div><div class=\"sense\"><b>Hif. הִכְלִיל</b> <div class=\"sense\"><i>to crown, finish, perfect</i>. Part. pass, <span dir=\"rtl\">מוּכְלָל</span>. <span class=\"citation\">Yoma 54ᵇ</span> (expl. <a href=\"#\" data-headword=\"מִכְּלָל\">מכלל</a>, <span class=\"citation\">Ps. L, 2</span>) <span dir=\"rtl\">מציון מ׳ יופיו וכ׳</span> from Zion the beauty of the world was perfected (by religion). [<span class=\"citation\">Cant. R. to V, 11</span>, end <span dir=\"rtl\">מוכללת</span>, read: <span dir=\"rtl\">מוּבְלֶלֶת</span>, v. <a href=\"#\" data-headword=\"בָּלַל\">בָּלַל</a>.]</div></div>","alt":[]},"12621":{"h":"כְּלַל","r":"K00759","html":"<div class=\"sense\"><b>1)</b> <i>to surround, crown</i>. <span class=\"citation\">Targ. Cant. III, 11</span>.</div><div class=\"sense\"><b>—2)</b>  (denom. of <a href=\"#\" data-headword=\"כּוֹל\">כּוֹלָּא</a>) <i>to make whole, combine</i>. <span class=\"citation\">Y. Meg. IV, 75ᵇ</span> bot. <span dir=\"rtl\">לינן חזרין וכָלְלִין לון</span> do we not again combine them (the separated portions)?</div><div class=\"sense\"><b>Pa. כַּלֵּיל</b> <div class=\"sense\"><b>1)</b> <i>to surround, crown</i>. <span class=\"citation\">Targ. Ps. V, 13</span>.</div><div class=\"sense\"><b>—2)</b>  (v. <a href=\"#\" data-headword=\"כִּילָה\">כִּילָה</a>, <a href=\"#\" data-headword=\"כִּילְתָא I\"><span dir=\"rtl\">כִּילְתָא</span> I</a>) <i>to prepare a bridal room</i>. <span class=\"citation\">B. Mets. 101ᵇ</span> <span dir=\"rtl\">כַּלְּלֵיה לבריח</span> if the owner of the rented dwelling gave it to his son as a bridal room (Rashi: if he was making preparations for his son’s wedding, and needed the dwelling for the young couple). <span class=\"citation\">Gen. R. s. 70</span>; <span class=\"citation\">Yalk. Gen. 125</span> <span dir=\"rtl\"><span dir=\"rtl\">כולי יומא הוו מְכַלְּלִין</span> (<a href=\"#\" data-headword=\"בִּיָּא\">ביה</a>) <span dir=\"rtl\">ליה</span></span> the whole day they were helping him to prepare the bridal chamber (decorating it).</div></div><div class=\"sense\"><b>Af. אַכְלֵיל</b> <div class=\"sense\"><i>to crown, surround</i>. <span class=\"citation\">Targ. Ps. LXV, 12</span>. <span class=\"citation\">Ib. CIII, 4</span>; a. e.—[<span class=\"citation\">Kidd. 81ᵇ</span> <span dir=\"rtl\">מכלליה</span>, read: <span dir=\"rtl\">מכלי להו</span>, v. <a href=\"#\" data-headword=\"כְּלֵי ²\"><span dir=\"rtl\">כְּלֵי</span> I</a>.]</div></div><div class=\"sense\"><b>Ithpa. אִיתְכַּלֵּל  אִיכַּלֵּל</b> </div><div class=\"sense\"><b>Ithpe. אִיכְּלִיל</b> <div class=\"sense\"><b>1)</b> <i>to be crowned, to adorn one’s self</i>. <span class=\"citation\">Gen. R. s. 34</span>, beg. (expl. <span class=\"citation\">Ps. CXLII, 8</span>) <span dir=\"rtl\">יִתְכַּלְּלוּן בי וכ׳</span> the righteous shall adorn themselves with me.</div><div class=\"sense\"><b>—2)</b> <i>to be led into the bridal room, be married</i>. <span class=\"citation\">Meg. 27ᵇ</span> <span dir=\"rtl\">כי איכ׳ רבה וכ׳</span> when his son R. was to marry.</div></div>","alt":[]},"12622":{"h":"כְּלָל","r":"K00760","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּלַל\">preced.</a> wds.) </div><div class=\"sense\"><b>1)</b> <i>general rule, principle</i>. Sifra K’dosh., Par. 2, ch. IV (ref. to <span class=\"citation\">Lev. XIX, 18</span>) <span dir=\"rtl\">זה כ׳ גדול וכ׳</span> this (‘love thy neighbor as thyself’) is the most important principle in the Law. <span class=\"citation\">Sabb. VII, 1</span>. <span class=\"citation\">Ḥull. III, 1</span> <span dir=\"rtl\">זה הכ׳</span> this is the general rule; a. v. fr.—Trnsf. <span dir=\"rtl\">בִּכְלַל</span>, <span dir=\"rtl\">לִכְלַל</span> <i>under the influence of</i>. <span class=\"citation\">Sifré Num. 157</span> <span dir=\"rtl\">לפי שהיה בכ׳ כעס בא לכ׳ טעות</span> because he was under the influence of anger, he came under the influence of mistaken judgment; <span class=\"citation\">Yalk. ib. 786</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>community</i>. <span class=\"citation\">Ber. 49ᵇ</span> <span dir=\"rtl\">לעולם אל … מן הכ׳</span> a person must never exclude himself from the community (by saying, ‘Praise ye’, instead of ‘Let us praise’). Mekh. Bo., Pisḥa, s. 18 <span dir=\"rtl\">ולפי שהוציא … מן הכ׳ וכ׳</span> and as he excluded himself from the community (by saying ‘you’) &amp;c.; a. e.</div><div class=\"sense\"><b>—3)</b> <i>total, sum</i>. <span class=\"citation\">B. Bath. 123ᵃ</span> <span dir=\"rtl\">בכְלָלָן אתה וכ׳</span> as their sum total you find seventy (<span class=\"citation\">Gen. XLVI, 27</span>), whereas the detailed record counts only sixty nine.</div><div class=\"sense\"><b>—4)</b> <i>generalization, statement by implication</i>, opp. <span dir=\"rtl\">פרט</span> specification; <i>inclusion, comprehension under a class</i>. <span class=\"citation\">Ber. 26ᵇ</span>, a. fr. <span dir=\"rtl\">עד ועד בכ׳</span>, v. <a href=\"#\" data-headword=\"עַד\">עַד</a>.—Sifra introd. <span dir=\"rtl\">מכ׳ ופרט מפרט וּכְ׳ וכ׳</span> interpretation based upon a general law followed by specification, or specification followed by generalization. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כל דבר שהיה בכ׳ וכ׳</span> when a law is once laid down in general, and in another place a specification is given (e.g. <span class=\"citation\">Lev. VII, 37</span>, a. <span class=\"citation\">ib. 20</span>), it is stated specifically not for its own sake alone, but as applicable to the whole class. Ib. beg. <span dir=\"rtl\">מכ׳ ופרט וּכְ׳ אי אתה דן וכ׳</span> if a general rule is followed by a specification and this again by a generalization, you must be guided by the specification (e.g. <span class=\"citation\">Deut. XIV, 26</span>). <span class=\"citation\">Tosef. Sot. VIII, 10</span>; <span class=\"citation\">Sot. 37ᵃ</span> ברוך בכ׳ … ארור בכ׳ וכ׳ ‘blessed be’ was pronounced on Mount Gerizim in general (corresp. to the general curse, <span class=\"citation\">Deut. XXVII, 26</span>) and was specified (corresp. to ib. 15—25) ; ‘cursed be’ was pronounced on Mount Ebal in general (ib. 26) &amp;c.; a. fr.—מִכְּ׳ <i>by implication</i>. <span class=\"citation\">Ned. 11ᵃ</span>, a. fr. <span dir=\"rtl\">מכ׳ לאו אתה שומע הן</span> from <i>no</i> you understand <i>yes</i>, v. <a href=\"#\" data-headword=\"הֵן\">הֵן</a>.—<span class=\"citation\">Pes. 16ᵇ</span> <span dir=\"rtl\">שהותרה מִכְּלָלָהּ וכ׳</span> which was permitted (dispensed with), by implication, for a community (if unclean, derived fr. <span class=\"citation\">Num. IX, 2</span>, v. <span class=\"citation\">Pes. 77ᵃ</span>). <span class=\"citation\">Ḥull. 37ᵇ</span> <span dir=\"rtl\">מכ׳ דטרפה וכ׳</span> this proves by implication that <i>t’refah</i> is not the same as &amp;c.; a. v. fr.—לאו … כ׳ <i>not at all</i> (cmp. <a href=\"#\" data-headword=\"כְּלוּם\">כְּלוּם</a>). <span class=\"citation\">Ib. 20ᵇ</span>; a. fr.—[Mekh. Bo, beg. <span dir=\"rtl\">כ׳ לדברות</span>, read: <a href=\"#\" data-headword=\"כְּלִי\">כֶּלִי</a>.]—Pl. <span dir=\"rtl\">כְּלָלוֹת</span> (<i>fem</i>.). <span class=\"citation\">Naz. 48ᵇ</span>. <span class=\"citation\">Sot. 37ᵇ</span>. <span class=\"citation\">Erub. 27ᵃ</span> <span dir=\"rtl\">אין למדין מן הכ׳ וכ׳</span> from general rules (the use of the word <span dir=\"rtl\">כל</span>, as <span class=\"citation\">ib. III, 1</span>) we must not derive anything, not even when an exception is stated (as there may be other exceptions); a. fr.—<span class=\"citation\">Ex. R. s. 32</span>, beg. <span dir=\"rtl\">כְּלָלִים</span>.</div>","alt":[]},"12623":{"h":"כְּלָלָא","r":"K00761","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. Deut. XXVII, 26</span> <span dir=\"rtl\">ברכתא בכ׳ וכ׳</span> blessings in general &amp;c. (v. <span class=\"citation\">Sot. 37ᵃ</span> quot. in <a href=\"#\" data-headword=\"כְּלָל\">preced.</a>).—<span class=\"citation\">Sabb. 147ᵃ</span>, a. fr. <span dir=\"rtl\">נקוט האי כ׳ בידך</span> take this as a rule. <span class=\"citation\">B. Mets. 103ᵇ</span>, a. e. <span dir=\"rtl\">כ׳ דמילתא</span> the general rule is &amp;c. <span class=\"citation\">Ḥull. 95ᵃ</span> <span dir=\"rtl\">הא דרב לא בפירוש איתמר אלא מכ׳ איתמר</span> this opinion of Rab has not been delivered explicitly but only arrived at by implication; <span class=\"citation\">Ber. 9ᵃ</span>; a. fr.—<span class=\"citation\">Yeb. 21ᵇ</span> <span dir=\"rtl\">וכ׳ הוא</span> is this rule without exceptions?—<span class=\"citation\">Shebu. 26ᵃ</span> <span dir=\"rtl\">אהני כ׳ לאתויי וכ׳</span> the generalization (after specification) has the effect of including &amp;c.; a. v. fr.—Pl. <span dir=\"rtl\">כְּלָלִין</span>, <span dir=\"rtl\">כְּלָלַיָא</span>, <a href=\"#\" data-headword=\"כְּלָאֵי\">כְּלָלֵי</a>. Y. Ter. I, 40ᶜ <span dir=\"rtl\"><a href=\"#\" data-headword=\"לַיִת\">לית</a> (<span dir=\"rtl\">כללי׳</span>) <span dir=\"rtl\">כְּלָלוֹי דרבי כ׳</span></span> the general rules of Rabbi (in the Mishnah; expressions like <span dir=\"rtl\">זה הכלל</span> or <a href=\"#\" data-headword=\"הַכֹּל\">הכל</a>, <span dir=\"rtl\">כל</span> &amp;c.) are not without exceptions. <span class=\"citation\">Keth. 60ᵃ</span> <span dir=\"rtl\">לא … להני כ׳ דכייל וכ׳</span> do not heed those rules which my brother … laid down. <span class=\"citation\">Gen. R. s. 33</span> [read:] <span dir=\"rtl\">אליף … כל כ׳ דאורייתא ואילין אינון הלכתא דבבלאי</span> (v. ‘Rashi’ a. l.) he taught Rab … all the general rules (of interpretation) of the Law, and these became the guiding laws of the Babylonians.</div>","alt":[]},"12624":{"h":"כָּלַם","r":"K00762","html":"<div class=\"sense\"><i>to be restrained, to be retired</i>.</div><div class=\"sense\"><b>Nif. נִכְלָם</b> <div class=\"sense\"><i>to be retired</i>, (cmp. <a href=\"#\" data-headword=\"*כְּזַז\">כְּזַז</a>) <i>to be put to shame, be rebuked</i>. <span class=\"citation\">Ab. d’R. N. ch. IX</span> (ref. to <span class=\"citation\">Num. XII, 14</span>) <span dir=\"rtl\">שתִּכָּלֵם ז׳ ימים</span> that she should live in retirement for seven days (and not appear before the king); (<span class=\"citation\">Sifré Num. 106</span> <span dir=\"rtl\">שתהא מוּכְלֶמֶת</span>). <span class=\"citation\">Ber. 16ᵇ</span> <span dir=\"rtl\">שלא נבוש ולא נִכָּלֵם מאבותינו</span> (v. Rabb. D. S. a. l. note 4) that we may not be put to shame and not be abashed when compared with our fathers (Y. ib. IV, 7ᵈ bot. <span dir=\"rtl\">שלא נבוש מאבותינו לעו&quot;הב</span>). <span class=\"citation\">Cant. R. to I, 14</span> <span dir=\"rtl\">בהִכָּלְמוֹ</span> in his shyness.</div></div><div class=\"sense\"><b>Hif. הִכְלִים</b> <div class=\"sense\"><i>to cause to retire, to rebuke, shame</i>. <span class=\"citation\">Kidd. 31ᵃ</span> bot. <span dir=\"rtl\">ולא הִכְלִימָהּ</span> and he did not scold her. <span class=\"citation\">Ib. 31ᵇ</span> <span dir=\"rtl\">כלום … ולא הִכְלַמְתָּהּ</span> did she (thy mother) throw a bag of money into the sea in thy presence, and thou didst not reproach her?—<span class=\"citation\">Midr. Till. to Ps. IV, 3</span> <span dir=\"rtl\">עד מתי אתם מַכְלִימִין וכ׳</span> how long will you slander me and my dignity?; a. e.—Part. Hof. <span dir=\"rtl\">מוּכְלָם</span>, f. <span dir=\"rtl\">מוּכְלֶמֶת</span>, v. supra.</div></div>","alt":[]},"12625":{"h":"כְּלַם","r":"K00763","html":"<div class=\"sense\">[<span class=\"citation\">Targ. Y. Deut. XXIX, 4</span> <span dir=\"rtl\">כלמו</span>, Var. <span dir=\"rtl\">בלמו</span>, read: <span dir=\"rtl\">בָּלַת</span> or <span dir=\"rtl\">בְּלִיאוּ</span>, v. <a href=\"#\" data-headword=\"בְּלֵי I\"><span dir=\"rtl\">בְּלֵי</span> I.</a>]</div><div class=\"sense\"><b>Af. אַכְלֵם</b> <div class=\"sense\"> as <a href=\"#\" data-headword=\"כָּלַם\">preced.</a> <i>Hif.</i> <span class=\"citation\">Targ. I Sam. XX, 34</span>. <span class=\"citation\">Ib. I, 16</span>; a. e.—<span class=\"citation\">B. Kam. 86ᵃ</span> bot. <span dir=\"rtl\">דמַכְלְמוּ ליה ומִיכְּלֵם</span> when you rebuke the child and he shrinks back in shame; <span class=\"citation\">ib. 86ᵇ</span> (not <span dir=\"rtl\">דמיכלמו</span>).—Part. pass. <span dir=\"rtl\">מַכְלַם</span>. Y. Yeb. XII, 12ᵈ bot. <span dir=\"rtl\">והיא מַכְלְמָה עלך</span> and she (the young woman) will be put to shame on account of thee (the old man); <span class=\"citation\">ib.</span> <span dir=\"rtl\">והוא מכלמה וכ׳</span> (read: <span dir=\"rtl\">מַכְלַם</span>).</div></div><div class=\"sense\"><b>Ithpa. אִיתְכַּלֵּם</b> </div><div class=\"sense\"><b>Ithpe. אִיתְכְּלַם  אִיכְּלַם</b> <div class=\"sense\"> as <a href=\"#\" data-headword=\"כָּלַם\">preced.</a> <i>Nif.</i> <span class=\"citation\">Targ. O. Num. XII, 14</span>. <span class=\"citation\">Targ. II Sam. X, 5</span>; a. e.—B. Kam. l. c., v. supra.</div></div>","alt":[]},"12626":{"h":"*כְּלָמָא","r":"K00764","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּלַם\">preced.</a>) <i>refraining, warding off</i>.—Pl. <a href=\"#\" data-headword=\"כְּלָאֵי\">כְּלָמֵי</a>. <span class=\"citation\">B. Mets. 103ᵇ</span> Ar. (Ms. <span dir=\"rtl\">כלומ׳</span>, ed. <a href=\"#\" data-headword=\"*בְּלָמָא\">בְּלָמָא</a> q. v.).</div>","alt":["כְּלוּמָא"]},"12627":{"h":"כַּלְמָא","r":"K00765","html":"<div class=\"sense\">, pl. <span dir=\"rtl\">כַּלְמֵי</span> <i>vermin</i>, v. <a href=\"#\" data-headword=\"כַּלְמְתָא\">כַּלְמְתָא</a>.</div>","alt":[]},"12628":{"h":"כְּלָמוּס","r":"K00766","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (χλαμύς) <i>chlamys, officer’s cloak</i> (v. Sm. Ant. s. v.). Y’lamd. to Gen. XXV, 23; 25, quot. in Ar., corresp. to the Jewish garment <a href=\"#\" data-headword=\"טַלִּית\">טַלִּית</a>, v. <a href=\"#\" data-headword=\"*כֹּכְלָא\">כֹּכְלָא</a>.—Tanḥ. Vayera, ed. Bub., 21 [read:] <span dir=\"rtl\">כל הימים … היה מהלך בסגון כיון שנכנס הלביש הכלמוס שלו</span> (v. ib. notes 124; 125) as long as he was on the road, he travelled in a <i>sagum</i> (common soldier’s cloak), when he entered to take office, he put on the chlamys; <span class=\"citation\">Gen. R. s. 50</span>, beg. <span dir=\"rtl\">כפגן … כקאלמין</span>; <span class=\"citation\">Lev. R. s. 26</span> <span dir=\"rtl\">כפגן … כקלאמין</span>; <span class=\"citation\">Yalk. Gen. 84</span> <span dir=\"rtl\">כגפ׳ … כקאלמין</span> (read: <span dir=\"rtl\">בסגון … בכְלָאמִין</span> or <span dir=\"rtl\">בקְלָאמִין</span>).</div>","alt":[]},"12629":{"h":"כַּלְמְתָא","r":"K00767","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (collect. noun; a dialect. adapt. of h.  [<i>nesting</i>, cmp. <span dir=\"rtl\">כלם</span>,] <i>vermin</i>. <span class=\"citation\">Targ. O. Ex. VIII, 12</span> sq. <a href=\"#\" data-headword=\"ק׳\">ק׳</a> (cod. 10 <a href=\"#\" data-headword=\"כ׳\">כ׳</a>, v. Berl. Targ. O. II, p. 21).—<span dir=\"rtl\">כַּלְמֵי</span>, <a href=\"#\" data-headword=\"קִנְטִינָר\">קַ׳</a>. Targ. Y. ib. <a href=\"#\" data-headword=\"ק׳\">ק׳</a>.—<span class=\"citation\">Ber. 51ᵇ</span> <span dir=\"rtl\">ממהדורי … כ׳</span> from peddlers comes gossip, from rags—vermin. <span class=\"citation\">Nidd. 20ᵇ</span> <a href=\"#\" data-headword=\"כ׳\">כ׳</a> (Ar. s. v. <a href=\"#\" data-headword=\"סרק\">סרק</a>: <span dir=\"rtl\">קלמי</span>).</div>","alt":["קַלְ׳"]},"12630":{"h":"כָּלָּן","r":"K00768","html":"<div class=\"sense\">, <span class=\"citation\">Y. Peah VIII, 20ᵈ</span> bot., v. <a href=\"#\" data-headword=\"כּוֹל\">כּוֹל</a></div>","alt":[]},"12631":{"h":"כַּלָּן","r":"K00769","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּלְּתָא\">כַּלְּתָא</a></div>","alt":[]},"12632":{"h":"כלנוס","r":"K00770","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כָּלִינוֹס\">כָּלִינוֹס</a></div>","alt":[]},"12633":{"h":"כְּלָנִידְיָיא","r":"K00771","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (χλανίδιον,—ια) <i>fine cloaks</i> for women. <span class=\"citation\">Y. Sabb. VI, 8ᵇ</span> bot. <a href=\"#\" data-headword=\"כ׳\">כ׳</a> (expl. <span dir=\"rtl\">הרעלות</span>, <span class=\"citation\">Is. III, 19</span>; not <a href=\"#\" data-headword=\"ב׳\">ב׳</a>).</div>","alt":[]},"12634":{"h":"כַּלְנִיתָא","r":"K00772","html":"<div class=\"sense\">, v. <span dir=\"rtl\">כּוּלְנִי׳</span></div>","alt":[]},"12635":{"h":"כְּלֵנְסָא","r":"K00773","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּלוֹנְסָא\">כְּלוּנְסָא</a></div>","alt":[]},"12636":{"h":"כלעס","r":"K00774","html":"<div class=\"sense\">, <span class=\"citation\">Y. Ter. VIII, 46ᵃ</span> <span dir=\"rtl\">ואיתכ׳</span>, v. <a href=\"#\" data-headword=\"בַּלְעֵס\">בַּלְעֵס</a></div>","alt":[]},"12637":{"h":"כְּלַפֵּי","r":"K00775","html":"<div class=\"sense\"> (= <span dir=\"rtl\"><span dir=\"rtl\">כִּ</span> (<span dir=\"rtl\">וון</span>) <span dir=\"rtl\">לאפי</span></span>, v. <a href=\"#\" data-headword=\"אַף I\">אַף</a>, <a href=\"#\" data-headword=\"אַפָּא I\">אַפָּא</a> a. <a href=\"#\" data-headword=\"כּוּן\"><a href=\"#\" data-headword=\"כּוּן\">כּוּן</a>)</a><i>directed towards, opposite, against</i>. <span class=\"citation\">Targ. Job XXIV, 15</span>; a. e.—<span class=\"citation\">Snh. VI, 4</span> <span dir=\"rtl\">פניו כ׳ העם</span> his (the culprit’s) face towards the people; <span dir=\"rtl\">כ׳ העץ</span> towards the cross. Ib. 105ᵃ, v. <a href=\"#\" data-headword=\"חוֹצַף\">חוּצְפָּא</a>. <span class=\"citation\">Pes. 8ᵇ</span> <span dir=\"rtl\">כ׳ שאמרה תורה</span> in the face of what (considering that) the Law says; Y. Macc. II, 31ᵈ top <span dir=\"rtl\">כ׳ שנאמר</span>; a. fr.—<span dir=\"rtl\">כ׳ לייא</span>, <a href=\"#\" data-headword=\"אַלְיָה\">אליה</a>, v. <a href=\"#\" data-headword=\"אַלְיָה\">אַלְיָה</a>.</div>","alt":[]},"12638":{"h":"כְּלֶקְדִּיקָה","r":"K00776","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּלוּגְדְּקָא\">גְּלוּגְדְּקָא</a></div>","alt":[]},"12639":{"h":"כלקורא","r":"K00777","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּלְכִּיד\">כַּלְכִּיד</a></div>","alt":[]},"12640":{"h":"כלקטורים","r":"K00778","html":"<div class=\"sense\"> read:</div>","alt":["כלקטורין"]},"12641":{"h":"כַּלַּקְטֵירִין","r":"K00779","html":"<div class=\"sense\"> (m. pl. χαρακτῆρες) <i>features</i> of the face. <span class=\"citation\">Lev. R. s. 23</span> <span dir=\"rtl\">הריני צר את כל קטורין וכ׳</span> (corr. acc.) I will shape his features in resemblance to &amp;c.; <span class=\"citation\">Pesik. R. s. 24</span> <span dir=\"rtl\">בלקטרים</span>, <span dir=\"rtl\">בלקטירים</span> (corr. acc.). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">יושב וצר בל׳ וכ׳</span> (corr. acc.) was painting the picture of the ruler (Lev. R. l. c. <a href=\"#\" data-headword=\"אִיקוֹנִין\">איקונין</a>). [Ar. s. v. <span dir=\"rtl\">קנכתר</span>: <span dir=\"rtl\">קנכתירין</span>.]—V. also <a href=\"#\" data-headword=\"*כּוֹלֶּקְטָר\">כּוֹלֶּקְטָר</a>.</div>","alt":[]},"12642":{"h":"כַּלְקִירָא","r":"K00780","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּלְכִּיד\">כַּלְכִּיד</a></div>","alt":[]},"12643":{"h":"כַּלְקִיס","r":"K00781","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (Χαλκίς) <i>Chalkis</i>, a town of Cœlesyria. <span class=\"citation\">Y. Meg. I, 70ᶜ</span> bot. <span dir=\"rtl\">פליטת … במדינת כ׳ וכ׳</span> refugee scholars in the city of Ch. and in Beth Zibdin; Y. Taan. II, 66ᵃ <span dir=\"rtl\">(<a href=\"#\" data-headword=\"כּוֹלְיָא\">כול׳</a>) <span dir=\"rtl\">בולקוס</span></span>; Meg. Taan. XII <span dir=\"rtl\">בליקו׳</span> (corr. acc.). [Schol. to Meg. Taan. defining our w.: <span dir=\"rtl\">במדינת קוסליקוס</span>, prob. a corrupt. of Cœlesyria.]</div>","alt":[]},"12644":{"h":"כלקירא","r":"K00782","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּלְכִּיד\">כַּלְכִּיד</a></div>","alt":[]},"12645":{"h":"כלרייה","r":"K00783","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. B. Kam. VII, 4</span> <span dir=\"rtl\">את הכ׳</span> some ed., read: <a href=\"#\" data-headword=\"דְּיֵיה\">דייה</a>, <span dir=\"rtl\">את הכל</span>.</div>","alt":[]},"12646":{"h":"כַּלְּתָא","r":"K00784","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> , <i>bride; daughter-in-law</i>. <span class=\"citation\">Targ. Is. LXI, 10</span> (ed. Wil. <a href=\"#\" data-headword=\"כַּלְּתָא\">כַּלְתָּא</a>). <span class=\"citation\">Targ. Gen. XI, 31</span>; a. fr.—<span class=\"citation\">Gitt. 57ᵃ</span> <span dir=\"rtl\">כי הוו מפקי חתנא וכ׳</span> when they led forth bride and groom in procession. <span class=\"citation\">B. Bath. 143ᵇ</span> <span dir=\"rtl\">כַּלְּתֵיה</span> his daughter-in-law. <span class=\"citation\">Meïl. 19ᵃ</span> <span dir=\"rtl\">דהבא דכלתיה דנון</span> the gold ware of the daughter-in-law of Nun (which was found to have lost in weight); a. fr.—[<span class=\"citation\">Targ. Job XV, 32</span> <span dir=\"rtl\">וכַלְתַיה</span>, v. <a href=\"#\" data-headword=\"כִּילְתָא I\"><span dir=\"rtl\">כִּילְתָא</span> I</a>.]—Pl. <a href=\"#\" data-headword=\"כַּלְּתָא\">כַּלָּתָא</a>, <span dir=\"rtl\">כַּלָּתָה</span>, <a href=\"#\" data-headword=\"כַּלָּן\">כַּלָּן</a>. <span class=\"citation\">Targ. Ruth I, 6</span>. <span class=\"citation\">Targ. Jer. VII, 34</span>.—Meïl. l. c. <span dir=\"rtl\">דהבא דרמיין כַּלָּתָיךְ</span> the gold ware which thy daughters-in-law cast carelessly about (by which they wear off). <span class=\"citation\">Keth. 17ᵃ</span> <span dir=\"rtl\">משרי קמי כ׳</span> they sang before (the processions of) brides. <span class=\"citation\">Yeb. 21ᵇ</span> <span dir=\"rtl\">כלתה דבי …</span> the daughters-in-law of the house of … (where there were wives of his daughter’s sons and wives of his son’s sons).—V. <a href=\"#\" data-headword=\"כַּלַּיָּיה\">כַּלַּיָּיה</a>, <a href=\"#\" data-headword=\"כַּלִּין\">כַּלִּין</a>.</div>","alt":["כַּלְ׳","כַּלָּ׳"]},"12647":{"h":"כלתין","r":"K00785","html":"<div class=\"sense\">, <span class=\"citation\">Y. R. Hash. II, 58ᵃ</span> top, read: <a href=\"#\" data-headword=\"בַּלְתִּי\">בַּלְתִּין</a>.</div>","alt":[]},"12648":{"h":"כְּמָא","r":"K00786","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"כְּ־\">כְּ־</a> a. <a href=\"#\" data-headword=\"מָא\"><a href=\"#\" data-headword=\"מָא\">מָא</a>)</a></div><div class=\"sense\"><b>1)</b>  (followed by <span dir=\"rtl\">ד־</span>) <i>like that which</i>. <span class=\"citation\">Targ. Jud. XI, 39</span> a. fr. [Usu.: <a href=\"#\" data-headword=\"הֵיכְמָא\">הֵיךְ מָא</a>, <a href=\"#\" data-headword=\"הֵיכְמָא\">הֵיכְמָא</a>.]— </div><div class=\"sense\"><b>2)</b>  (mostly <span dir=\"rtl\">כמה</span>) <i>how! how many!, how much!, how long!</i>; (also interrog.) <i>how much?</i> &amp;c. <span class=\"citation\">Targ. Ps. CXXXIX, 17</span>. <span class=\"citation\">Ib. XXXV, 17</span>; a. fr.—<span class=\"citation\">Gen. R. s. 6</span> <span dir=\"rtl\">כ׳ נפשיה וכ׳</span> how the soul of this man’s (my) brother is now chopping cedars and sawing &amp;c. (is in the agony of death)! (Midr. Sam. ch. IX; <span class=\"citation\">Yalk. Ps. 743</span>, only <span dir=\"rtl\">נפשיה וכ׳</span>). <span class=\"citation\">Yoma 22ᵇ</span>, v. <a href=\"#\" data-headword=\"חֲלִי\">חֲלִי</a>. <span class=\"citation\">Ber. 14ᵇ</span> <span dir=\"rtl\">כ׳ מעליא וכ׳</span> how excellent &amp;c. <span class=\"citation\">B. Mets. 86ᵃ</span> <span dir=\"rtl\">כ׳ ככרין וכ׳</span> how many cakes of nardus do we owe to &amp;c.!—<span class=\"citation\">M. Kat. 16ᵇ</span> <span dir=\"rtl\">כל כ׳ דהוה וכ׳</span> as long as &amp;c.; a. fr.—<span class=\"citation\">Y. Ab. Zar. II, 41ᵃ</span> top <span dir=\"rtl\">כְּמָן קטל</span> how many of them did he kill?</div>","alt":["כְּמָה"]},"12649":{"h":"כְּמַאי","r":"K00787","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"כְּמָא\">preced.</a>) <i>as much as</i>. <span class=\"citation\">Yoma 43ᵇ</span> <span dir=\"rtl\">כ׳ דמסיק וכ׳</span> (Var. <span dir=\"rtl\">כמה</span>) as much as a fox carries (on its feet) from a ploughed field; (<span class=\"citation\">Nidd. 65ᵇ</span> <span dir=\"rtl\">כדמסיק</span>).</div>","alt":[]},"12650":{"h":"כְּמָה","r":"K00788","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּמָא\">כְּמָא</a></div>","alt":[]},"12651":{"h":"כַּמֶּה","r":"K00789","html":"<div class=\"sense\">(<a href=\"#\" data-headword=\"כְּמָה\">preced.</a> wds.) </div><div class=\"sense\"><b>1)</b> <i>how much?, how many?</i> <span class=\"citation\">Kidd. 9ᵇ</span> <span dir=\"rtl\">ב׳ אתה נותן וכ׳</span> how much (dowry) wilt thou give &amp;c.? <span class=\"citation\">Ber. 14ᵃ</span> <span dir=\"rtl\">עד כ׳</span> up to how much? <span class=\"citation\">Ib. 30ᵇ</span> <span dir=\"rtl\">כ׳ ישהה וכ׳</span> how long must he pause between &amp;c.?; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>how!, how many!, how much!</i> <span class=\"citation\">Sabb. 12ᵇ</span> <span dir=\"rtl\">כ׳ גדולים דברי וכ׳</span> how grand are the words of &amp;c.; a. fr.—<span dir=\"rtl\">על אחת כ׳ וכ׳</span>, v. <a href=\"#\" data-headword=\"אֶחָד\">אֶחָד</a>.</div><div class=\"sense\"><b>—3)</b>  (I don’t know) <i>how many, many</i>. <span class=\"citation\">M. Kat. 16ᵇ</span> איבדתי כ׳ דוד מפניו I should have destroyed many Davids for his sake. <span class=\"citation\">Y. Keth. V, 30ᵃ</span> bot. <span dir=\"rtl\">לאחר כ׳ ימים</span> after ever so many days. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אפי כ׳</span> even much longer; a. fr.—[<span class=\"citation\">Y. Succ. I, 51ᵈ</span> top <span dir=\"rtl\">גבוה מכמה</span>, prob. to be read: <span dir=\"rtl\">מכ׳ אמה</span> = <span dir=\"rtl\">מעשרים</span> ib.]</div>","alt":["כַּמָּה"]},"12652":{"h":"כְּמֵהוֹת","r":"K00790","html":"<div class=\"sense\"> c. pl. (כָּמַהּ <i>to be hot, to thirst, long for</i>) a kind of <i>mushroom, morils</i>. <span class=\"citation\">Gen. R. s. 69</span>, beg. (ref. to <span dir=\"rtl\">כמה</span>, <span class=\"citation\">Ps. LXIII, 2</span>) <span dir=\"rtl\">ככ׳ הללו שהן מצפין וכ׳</span> like those morils which look out for water; <span class=\"citation\">Yalk. Gen. 119</span> <span dir=\"rtl\">כַּכְּמֵהִיּוֹת</span> (not <span dir=\"rtl\">כמ׳</span>); <span class=\"citation\">Yalk. Ps. 786</span> <span dir=\"rtl\">כאמבטאות</span> (corr. acc.). <span class=\"citation\">Ned. 55ᵇ</span>; Y. Maasr. I, 48ᵈ top, <span dir=\"rtl\">כ׳ ופטריות</span> morils and truffles which are not planted; <span class=\"citation\">Ber. 40ᵇ</span>; a. fr.</div>","alt":["כְּמֵהִים","כְּמֵהִין","כְּמֵי׳"]},"12653":{"h":"כְּמֵהִין","r":"K00791","html":"<div class=\"sense\"><span class=\"citation\">Y. Bets. V, end, 63ᵇ</span></div>","alt":[]},"12654":{"h":"כְּמוֹ","r":"K00792","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"כְּמָה\">כְּמָה</a>) <i>as, like</i>. <span class=\"citation\">Yalk. Ex. 246</span> <span dir=\"rtl\">הקשו לבם כ׳ אבן</span> they made their hearts hard like stones (Mekh. B’shall., Shirah, s. 5 <span dir=\"rtl\">כאבן</span>). With suffixes: <span dir=\"rtl\">כָּמוֹנִי</span>, <span dir=\"rtl\">כָּמוֹךָ</span> &amp;c. <i>like me, like thee</i> &amp;c. <span class=\"citation\">Ned. 9ᵇ</span>, v. <a href=\"#\" data-headword=\"כְּמוֹת\">כְּמוֹת</a>. Mekh. l. c., s. 8; a. fr.—V. <a href=\"#\" data-headword=\"כְּמוֹת\">כְּמוֹת</a>.</div>","alt":[]},"12655":{"h":"כמון","r":"K00793","html":"<div class=\"sense\">, a word in a charm formula. <span class=\"citation\">Sabb. 67ᵃ</span> (v. next wds.).</div>","alt":[]},"12656":{"h":"כַּמּוֹן","r":"K00794","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>cumin.</i> <span class=\"citation\">Dem. II, 1</span>. <span class=\"citation\">Ter. X, 4</span> <span dir=\"rtl\">בכ׳ של וכ׳</span> with cumin stalks of T’rumah.</div>","alt":[]},"12657":{"h":"כַּמּוֹנָא","r":"K00795","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Is. XXVIII, 25</span>; <span class=\"citation\">27</span>.—<span class=\"citation\">Ab. Zar. 29ᵃ</span>, v. <a href=\"#\" data-headword=\"כָּרַוְיָא\">כְּרַוְיָא</a>.—Pl. <span dir=\"rtl\">כְּמוֹנַיָּא</span>, <span dir=\"rtl\">כְּמוֹנֵי</span>. <span class=\"citation\">Sabb. 67ᵃ</span> <span dir=\"rtl\">כמוניא</span> (Rashi: <span dir=\"rtl\">כמוני</span>; Ms. M. sing.), v. <a href=\"#\" data-headword=\"בִּינְתָא I\"><span dir=\"rtl\">בִּינְתָא</span> I</a>.</div>","alt":["כְּמוֹנָא"]},"12658":{"h":"כָּמוֹנָא","r":"K00796","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּמַן\">כְּמַן</a>) <i>insidiousness, crafty plan</i>. <span class=\"citation\">Targ. Y. II, Ex. XXI, 14</span> (h. text <span dir=\"rtl\">ערמה</span>).—V. <a href=\"#\" data-headword=\"כְּמָנָא\">כְּמָנָא</a>.</div>","alt":[]},"12659":{"h":"כְּמוֹת","r":"K00797","html":"<div class=\"sense\"> (= <span dir=\"rtl\">כְּמוֹ את</span>, cmp. <a href=\"#\" data-headword=\"כְּוָת\">כְּוָת</a>) <i>like, as</i>. <span class=\"citation\">Y. Maas. Sh. IV, 54ᵈ</span> <span dir=\"rtl\">כ׳ שהוא מוכר</span> according to the selling price. <span class=\"citation\">Sabb. 51ᵃ</span>, a. fr. <span dir=\"rtl\">כ׳ שהוא</span> (<a href=\"#\" data-headword=\"חַי\">חי</a>) in its natural condition (raw). <span class=\"citation\">Keth. 17ᵃ</span> <span dir=\"rtl\">כלה כ׳ שהיא</span> the bride at weddings must be praised according to her perfections (without exaggeration); a. fr.—With suffixes: <span dir=\"rtl\">כְּמוֹתִי</span>, <span dir=\"rtl\">כְּמוֹתְךָ</span> &amp;c. <i>like myself, like thyself</i> &amp;c. <span class=\"citation\">B. Mets. 59ᵇ</span> <span dir=\"rtl\">אם הלכה כ׳</span> if the law is in accordance with my opinion, v. <a href=\"#\" data-headword=\"כְּוָת\">כְּוָת</a>. <span class=\"citation\">Y. Ned. I, 36ᵈ</span> bot. <span dir=\"rtl\">כ׳ ירבו וכ׳</span> may there be many like thee &amp;c.; (Bab. <span class=\"citation\">ib. 9ᵇ</span> <span dir=\"rtl\">כָּמוֹךָ</span>). <span class=\"citation\">Ber. V, 5</span>, a. fr. <span dir=\"rtl\">שלוחו של אדם כְּמוֹתוֹ</span> a man’s messenger is like himself, i.e. action by proxy is legal; a. fr.</div>","alt":[]},"12660":{"h":"כְּמֵיהוֹת","r":"K00798","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"כְּמֵהוֹת\">כְּמֵה׳</a>.</div>","alt":["… יהִים","… יהִין"]},"12661":{"h":"כמיך","r":"K00799","html":"<div class=\"sense\">, a word in a charm formula. <span class=\"citation\">Sabb. 67ᵃ</span></div>","alt":[]},"12662":{"h":"כָּמֵין","r":"K00800","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּמַן\">כְּמַן</a></div>","alt":[]},"12663":{"h":"כְּמֵינָא","r":"K00801","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּמָנָא\">כְּמָנָא</a></div>","alt":[]},"12664":{"h":"כְּמֵיסַת","r":"K00802","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּמֵסַת\">כְּמֵסַת</a></div>","alt":[]},"12665":{"h":"כְּמֵישׁ","r":"K00803","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּמַשׁ\">כְּמַשׁ</a></div>","alt":[]},"12666":{"h":"כָּמַךְ","r":"K00804","html":"<div class=\"sense\">, m. (Pers. Kâmakh, Arab. Kâmaḥ, Fl. to Levy Talm. Dict. II, 452<sup>2</sup>) <i>Kamakh, a Persian sauce</i> of milk, curdled milk &amp;c.; cmp. <a href=\"#\" data-headword=\"כּוּתָּח\">כּוּתָּח</a>. <span class=\"citation\">Nidd. 51ᵇ</span> <span dir=\"rtl\">שבת העשויה לכ׳</span> dill intended to be put into the <i>k</i></div>","alt":[]},"12667":{"h":"כָּמְכָא","r":"K00805","html":"<div class=\"sense\"><span class=\"citation\">Pes. 30ᵃ</span> Ar. (ed. <a href=\"#\" data-headword=\"כּוּתַּח\">כותחא</a>). Ib. 76ᵇ Ar. (ed. <a href=\"#\" data-headword=\"כּוּתַּח\">כותחא</a>). <span class=\"citation\">Hor. 12ᵃ</span> Ms. M. (ed. <a href=\"#\" data-headword=\"כּוֹתְנִיאָס\">כות׳</a>). <span class=\"citation\">Ḥull. 112ᵃ</span>; a. e.</div>","alt":[]},"12668":{"h":"כְּמָן","r":"K00806","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּמָא\">כְּמָא</a></div>","alt":[]},"12669":{"h":"כָּמַן","r":"K00807","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"כָּמַר\">כָּמַר</a>) [<i>to be heated</i> in the ground,] <i>to be hidden, lie in wait</i>.</div><div class=\"sense\"><b>*. כִּמֵּן</b> <div class=\"sense\"><i>to hide fruits</i> in the ground. <span class=\"citation\">Maasr. IV, 1</span> המְכַמֵּן Mish. a. Bab. ed. (Ms. M. <span dir=\"rtl\">המכמיר</span>, Y. ed. <span dir=\"rtl\">המכמר</span>, v. <a href=\"#\" data-headword=\"כָּמַר\">כָּמַר</a>).</div></div><div class=\"sense\"><b>Hif. הִכְמִין</b> <div class=\"sense\"><i>to keep witnesses hidden</i>, a proceeding applied only against seducers to idolatry (v. <a href=\"#\" data-headword=\"מֵסִית\">מֵסִית</a>). <span class=\"citation\">Snh. VII, 10</span> <span dir=\"rtl\">מַכְמִינִין לו עדים וכ׳</span> the court puts witnesses in wait for him behind an enclosure. Y. Yeb. XVI, 15ᵈ bot.; a. e.—Y. Snh. VIII, 21ᶜ top <span dir=\"rtl\">המַכְמִין עדיו וכ׳</span> he who keeps witnesses hidden (while eliciting a confession of indebtedness from his debtor), has done nothing, i.e. the confession has no legal consequences.</div></div>","alt":[]},"12670":{"h":"כְּמַן","r":"K00808","html":"<div class=\"sense\"><span class=\"citation\">Targ. O. Ex. XXI, 13</span>; a. fr.—Part. <a href=\"#\" data-headword=\"כָּמֵין\">כָּמֵין</a>, f. <span dir=\"rtl\">(<a href=\"#\" data-headword=\"כְּמָנָא\">כָּמְנָא</a>) <a href=\"#\" data-headword=\"כְּמֵינָא\">כָּמֵינָא</a></span>. <span class=\"citation\">Targ. Jer. IX, 3</span> <span dir=\"rtl\">מִכְמַן כ׳</span> (h. text <span dir=\"rtl\">עקב יעקב</span>). <span class=\"citation\">Targ. Prov. VII, 12</span>.—<span class=\"citation\">Koh. R. to IV, 14</span>; <span class=\"citation\">Midr. Till. to Ps. IX</span>, v. <a href=\"#\" data-headword=\"*כַּשְׂכֵּשׂ\">כַּשְׂכֵּשׂ</a>.</div><div class=\"sense\"><b>Pa. כַּמֵּין</b> <div class=\"sense\"><i>to hide, cover</i>. <span class=\"citation\">Targ. Prov. X, 18</span> מְכַמֵּין Ms. (ed. <span dir=\"rtl\">מַכְמֵין</span> <i>Hif.</i>).—Part. pass. <span dir=\"rtl\">מְכַמַּן</span> <i>lurking</i>. <span class=\"citation\">Targ. Lam. III, 10</span> (ed. Amst. <span dir=\"rtl\">מְכַמֵּן</span>; h. text <span dir=\"rtl\">א̇רֵב</span>).</div></div><div class=\"sense\"><b>Af. אַכְמִין</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"כָּמַן\">same</a>, v. supra.—2) as <a href=\"#\" data-headword=\"כָּמַן\">preced.</a> </div><div class=\"sense\"><i>Hif.</i> <span class=\"citation\">Snh. 29ᵇ</span>.</div></div>","alt":[]},"12671":{"h":"כַּמָּן","r":"K00809","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּמָּנוֹן\">כִּמָּנוֹן</a></div>","alt":[]},"12672":{"h":"כְּמָנָא","r":"K00810","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כַּמָּן\">preced.</a> wds.) <i>ambush, trap; insidiousness</i>. <span class=\"citation\">Targ. Jud. IX, 35</span>. <span class=\"citation\">Targ. II Sam. XIII, 32</span> (ed. Lag. <a href=\"#\" data-headword=\"כְּמֵינָא\">כְּמֵינָא</a>; h. text <a href=\"#\" data-headword=\"שִׂימָה\">שימה</a>); a. e.—Pl. <span dir=\"rtl\">כְּמָנַיָּא</span>, constr. <span dir=\"rtl\">כְּמָנֵי</span>. <span class=\"citation\">Targ. I Chr. I, 20</span> (ed. Lag. <a href=\"#\" data-headword=\"כְּמֵינָא\">כמינא</a>). <span class=\"citation\">Targ. Ps. X, 8</span>; <span class=\"citation\">10</span>.—V. <a href=\"#\" data-headword=\"כָּמוֹנָא\">כָּמוֹנָא</a>.</div>","alt":[]},"12673":{"h":"כְּמָנָה","r":"K00811","html":"<p class=\"morphology\">f.</p><div class=\"sense\">—Pl. <span dir=\"rtl\">כְּמָנוֹת</span>. <span class=\"citation\">Yalk. Deut. 804</span> … <span dir=\"rtl\">אין שאין בה כ׳</span> there is no road on which ambushes are not to be apprehended; Sifré <span class=\"citation\">ib. 20</span> <span dir=\"rtl\">מקומות</span> (corr. acc.).</div>","alt":[]},"12674":{"h":"כִּמָּנוֹן","r":"K00812","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּמָנָה\">preced.</a> wds.) <i>craft, artfulness</i>. <span class=\"citation\">Koh. R. to IX, 14</span> (expl. <span dir=\"rtl\">מצודים</span> ib.) <span dir=\"rtl\">כ׳ ועקמון</span> Craft and Trap (allegorical names of towers); <span class=\"citation\">Yalk. ib. 989</span> <a href=\"#\" data-headword=\"כַּמָּן\">כַּמָּן</a>; <span class=\"citation\">Gen. R. s. 33</span> עַקְמָן וכַמְנָן Tricky and Wily.</div>","alt":[]},"12675":{"h":"כָּמַס","r":"K00813","html":"<div class=\"sense\"><i>to hide, store away</i>. Part. pass. <span dir=\"rtl\">כָּמוּס</span>. <span class=\"citation\">Yalk. Ex. 165</span> <span dir=\"rtl\">הוא כ׳ מעינינו</span> he is hidden from our sight; <span class=\"citation\">Pirké d’R. El. ch. XLVIII</span>.—V. <a href=\"#\" data-headword=\"כּוֹמְסָה\">כּוֹמְסָה</a>.</div>","alt":[]},"12676":{"h":"כְּמָס","r":"K00814","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּמַס\">preced.</a>) <i>subterranean prison</i> (carcer). <span class=\"citation\">Yalk. Hos. 532</span> <span dir=\"rtl\">בתחלה קורא אילוגין … נותן לו כ׳ וכ׳</span> first he reads the charge, then he strikes him (to extort confession), and then he assigns to him a prison &amp;c.; Pesik. Shub., p. 159ᵇ (corr. acc.).</div>","alt":[]},"12677":{"h":"כְּמָס ²","r":"K00815","html":"<div class=\"sense\">(v. <a href=\"#\" data-headword=\"כְּמָס\">preced.</a>) <i>store-room, cellar</i> (Assyr. <span dir=\"rtl\">כמס</span>, Schr. KAT<sup>2</sup> p. 559). <span class=\"citation\">B. Bath. 145ᵇ</span> <span dir=\"rtl\">עתיר כ׳</span> rich of stores.</div>","alt":[]},"12678":{"h":"כְּמֵסַת","r":"K00816","html":"<div class=\"sense\"> c. (v. <a href=\"#\" data-headword=\"מִסְּתָא\">מִסְּתָא</a>; a phrase borrowed fr. <span class=\"citation\">Deut. XVI, 10</span>; <span class=\"citation\">17</span>, v. Targ. Y.; = h. <a href=\"#\" data-headword=\"כְּדָיי\">כְּדָיי</a>) <i>adequate, able, worthy</i>. <span class=\"citation\">Targ. Y. II, Lev. XXIII, 29</span> <span dir=\"rtl\">דכ׳ וכ׳</span> that is able (or of adequate age) to fast. <span class=\"citation\">Targ. Y. Gen. XX, 16</span>. <span class=\"citation\">Targ. II Sam. VII, 18</span>; <span class=\"citation\">Targ. I Chr. XVII, 16</span> לית אנא כ׳ I am not worthy (h. text <span dir=\"rtl\">מי אנכי</span>).</div>","alt":["כְּמֵיסַת"]},"12679":{"h":"כָּמַר","r":"K00817","html":"<div class=\"sense\"> v. <span dir=\"rtl\">כָּמַהּ</span>, </div><div class=\"sense\"><b>1)</b>  [<i>to heat</i>,] <i>to make</i> <a href=\"#\" data-headword=\"כּוֹמֶר I\">כּוֹמֶר</a> (v. <a href=\"#\" data-headword=\"כּוֹמֶר I\"><span dir=\"rtl\">כּוֹמֶר</span> I</a>), <i>to produce shrinking and maturing of fruits by underground storage</i> or <i>by exposure to the sun</i>. <span class=\"citation\">Tosef. Men. IX, 10</span> <span dir=\"rtl\">לא היו … וכוֹמְרִין אותן</span> (Var. <span dir=\"rtl\">וכורמין</span>) they did not cut the grapes and let them shrink (before putting them in the press), but cut and immediately pressed them. <span class=\"citation\">B. Mets. 89ᵇ</span> <span dir=\"rtl\">ולא יִכְמוֹר באדמה וכ׳</span> (Ar. <span dir=\"rtl\">יְכַמֵּר</span> <i>Pi.</i>, v. Rabb. D. S. a. l. note 90) the laborer must not hide grapes in the ground (to eat them afterwards).</div><div class=\"sense\"><b>—2)</b>  (trnsf.) <i>to watch, guard</i>.—Denom. <a href=\"#\" data-headword=\"כּוֹמֶר II\"><span dir=\"rtl\">כּוֹמֶר</span> II</a>.</div><div class=\"sense\"><b>—3)</b> <i>to lay a trap</i>, v. infra.</div><div class=\"sense\"><b>Pi. כִּימֵּר</b> </div><div class=\"sense\"><b>Hif. הִכְמִיר</b> <div class=\"sense\"><b>1)</b> <i>to hide in the ground, heat.</i> <span class=\"citation\">Maasr. IV, 1</span>, v. <a href=\"#\" data-headword=\"כָּמַן\">כָּמַן</a>. B. Mets. l. c., v. supra.</div><div class=\"sense\"><b>—2)</b>  (denom. of <a href=\"#\" data-headword=\"מִכְמָר\">מִכְמָר</a>) <i>to lay a trap, net</i>. <span class=\"citation\">Tosef. Yeb. XIV, 6</span> <span dir=\"rtl\">שהיו מְכַמְּרִין מכמרות</span> that were laying nets; <span class=\"citation\">Yeb. 121ᵃ</span> <span dir=\"rtl\">מְכַ׳ מכמורין</span>; Y. ib. XVI, 15ᵈ top <span dir=\"rtl\">לִכְמוֹר מ׳</span>.</div></div><div class=\"sense\"><b>Nif. נִכְמַר</b> <div class=\"sense\"><b>1)</b> <i>to shrink, fall in by the effect of the heat, to tumble inward</i>. Y. B. Mets. X, beg. 12ᶜ <span dir=\"rtl\">נ׳ כתנור</span> if the house fell in like a furnace, opp. <span dir=\"rtl\">נפל לחוץ</span>.</div><div class=\"sense\"><b>—2)</b>  (trnsf.) with <a href=\"#\" data-headword=\"רַחֲמִים\">רחמים</a>, <i>to be bent over, to feel compassion</i> (cmp. <a href=\"#\" data-headword=\"גִּלְגֵּל\">גִּלְגֵּל</a>). <span class=\"citation\">Yalk. Gen. 150</span> נִכְמְרוּ רחמיו של יוסף Joseph was moved to compassion; (Tanḥ. Vayigg. 4 <span dir=\"rtl\">נתגלגלו ר׳</span>).</div></div>","alt":[]},"12680":{"h":"כְּמַר","r":"K00818","html":"<div class=\"sense\"><b>1)</b> <i>to hide, keep warm</i> (corresp. to h. <a href=\"#\" data-headword=\"טָמַן\">טָמַן</a>). <span class=\"citation\">Y. Sabb. IV, beg. 6ᵈ</span> (read:] <span dir=\"rtl\">כַּמְרָאִי גו גיפתא</span>, v. <a href=\"#\" data-headword=\"גִּיפְתָּא\">גִּיפְתָּא</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כַּמְרָהּ גו וכ׳</span> put it in &amp;c. <span class=\"citation\">B. Mets. 74ᵃ</span> <span dir=\"rtl\">מחוסר מִכְמַר ועיולי וכ׳</span> requiring heating (of grapes) and carrying to the press.</div><div class=\"sense\"><b>—2)</b> <i>to shrink, be wrinkled</i>. <span class=\"citation\">Pes. 58ᵃ</span> <span dir=\"rtl\">מכמר בישרא</span> the shrinking and drying up of the meat (from lying over too long).</div><div class=\"sense\"><b>—3)</b>  (with <a href=\"#\" data-headword=\"רַחֲמִין\">רחמין</a> as object) <i>to feel compassion</i>. <span class=\"citation\">Targ. Y. Deut. XIII, 18</span>. <span class=\"citation\">Targ. Ps. LXXVII, 10</span>.—[<span class=\"citation\">Kidd. 81ᵇ</span>, v. <a href=\"#\" data-headword=\"*אִכְמַר\">אִכְמַר</a>.]</div>","alt":[]},"12681":{"h":"כֹּמֶר","r":"K00819","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כּוֹמֶר I\">כּוֹמֶר</a>, <a href=\"#\" data-headword=\"כּוּמָרָא\"><a href=\"#\" data-headword=\"כּוּמָרָא\">כּוּמְרָא</a>.</a></div>","alt":["כְּמָרָא"]},"12682":{"h":"כְּמַרְיָאתָא","r":"K00820","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כֹּמֶר\">preced.</a> wds.) <i>withered, black fruits</i>. <span class=\"citation\">Lam. R. to V, 10</span> (expl. <span dir=\"rtl\">נכמרו</span> ib.) <span dir=\"rtl\">כאילין כ׳</span> wrinkled like withered fruits.</div>","alt":[]},"12683":{"h":"כמרוסא","r":"K00821","html":"<div class=\"sense\">, <span class=\"citation\">Num. R. s. 12</span>, v. <a href=\"#\" data-headword=\"קַמְרוֹטָא\">קַמְרוֹטָא</a></div>","alt":[]},"12684":{"h":"כָּמַשׁ","r":"K00822","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"כָּמַר\">כָּמַר</a>) <i>to wrinkle, wither</i>. <span class=\"citation\">Y. Maas. Sh. IV, 54ᵈ</span> bot. <span dir=\"rtl\">עד שיִכְמוֹשוּ</span> until they are withered.—Part. pass. <span dir=\"rtl\">כָּמוּשׁ</span>, f. <a href=\"#\" data-headword=\"כָּפוּרְתָּא\">כְּמוּשָׁה</a>; pl. <span dir=\"rtl\">כְּמוּשִׁין</span>, <span dir=\"rtl\">כְּמוּשׁוֹת</span>. <span class=\"citation\">Lev. R. s. 23</span>; <span class=\"citation\">Cant. R. to II, 2</span> <span dir=\"rtl\">מה שושנה … והיא כ׳ וכ׳</span> as the lily, when the heat comes upon it, is withered, but blooms again when the dew falls … <span dir=\"rtl\">נראין כ׳ וכ׳</span> so does Israel … seem to be withered &amp;c. <span class=\"citation\">Succ. 31ᵃ</span> bot. <span dir=\"rtl\">כמושין</span> withered fruits, contrad. to <span dir=\"rtl\">יבשין</span> dried up; a. fr.</div><div class=\"sense\"><b>Nif. נִכְמַשׁ</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"כמרוסא\">same</a>. <span class=\"citation\">Cant. R. to II, 1</span> <span dir=\"rtl\">נוחה להִכָּמֵשׁ</span> withers easily.</div></div>","alt":[]},"12685":{"h":"כְּמַשׁ","r":"K00823","html":"<div class=\"sense\"><span class=\"citation\">B. Bath. 16ᵇ</span> <span dir=\"rtl\">וכיון דכַמְשֵׁי וכ׳</span> and when they withered, they knew (that an accident had befallen their friend).—Part. <a href=\"#\" data-headword=\"כְּמֵישׁ\">כָּמִישׁ</a>, pl. <span dir=\"rtl\">כְּמִישִׁין</span>. <span class=\"citation\">Y. Pes. IV, end, 31ᶜ</span>; <span class=\"citation\">Esth. R. to I, 4</span>, v. <a href=\"#\" data-headword=\"זְלִיל\">זְלִיל</a></div>","alt":[]},"12686":{"h":"כְּמָת־","r":"K00824","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"כְּמָא\">כְּמָא</a> a. <a href=\"#\" data-headword=\"דִּכְמָא\"><a href=\"#\" data-headword=\"דִּכְמָא\">דִּכְמָא</a>)</a><i>like</i>.—<span class=\"citation\">Targ. Ps. LXXIII, 15</span> <span dir=\"rtl\">דְּמִכְּמָתְהוֹן</span> ed. Lag. (oth. ed. <span dir=\"rtl\">דכמתהון</span>) (something) which is of the nature of their speeches.</div>","alt":[]},"12687":{"h":"כַּן","r":"K00825","html":"<div class=\"sense\"><i>here</i>, v. <a href=\"#\" data-headword=\"כַּאַן\">כַּאַן</a>.</div>","alt":[]},"12688":{"h":"כֵּן I","r":"K00826","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"כִּי\">כִּי</a>, <i>so, thus</i>. <span class=\"citation\">Ber. 11ᵇ</span> <span dir=\"rtl\">וכן הוא אומר</span> and so we read; a. v. fr.—<span dir=\"rtl\">אם כן</span>, <span dir=\"rtl\">אלא אם כן</span>, v. <a href=\"#\" data-headword=\"אִם\">אִם</a>.—לָכֵן <i>for such a purpose</i>. <span class=\"citation\">Y. Maas. Sh. II, 53ᵇ</span> bot. <span dir=\"rtl\">דרכו ל׳</span> it is usually employed for such a purpose. <span class=\"citation\">Y. Erub. VII, beg. 24ᵇ</span> <span dir=\"rtl\">ייחדו ל׳</span> he devoted it to such &amp;c.—<span dir=\"rtl\">יתר על כן</span>, <span dir=\"rtl\">יתר מִכֵּן</span>, v. <a href=\"#\" data-headword=\"יֶתֶר I\"><span dir=\"rtl\">יֶתֶר</span> I</a>.</div>","alt":[]},"12689":{"h":"כֵּן","r":"K00827","html":"<div class=\"sense\">, ch. <a href=\"#\" data-headword=\"כֵּן I\">same</a>. <span class=\"citation\">Targ. Is. LI, 6</span>. <span class=\"citation\">Targ. O. Ex. I, 12</span>; a. fr.—<span class=\"citation\">Ber. 11ᵇ</span> <span dir=\"rtl\">וכן אורי ליה וכ׳</span> and so taught R. El. &amp;c.; a. v. fr.—<span dir=\"rtl\">בתר כן</span>, contr. <a href=\"#\" data-headword=\"בְּכֵין\">בְּכֵן</a>, <i>after this; therefore</i>. <span class=\"citation\">Targ. II Sam. II, 1</span>; a. fr.—<span class=\"citation\">Ib. XXII, 47</span>; a. e.—<span dir=\"rtl\">וּלְהָלָא מִבְּכֵן</span>, <span dir=\"rtl\">וּלְהָלָה מִבְּכֵין</span> from now and further on = h. <span dir=\"rtl\">מכאן ואילך</span>. <span class=\"citation\">Targ. I Kings XIV, 14</span>.—<span class=\"citation\">Y. Sabb. XIV, 14ᵈ</span> <span dir=\"rtl\">ר&quot;י מטתיה כן</span> such (disease) befell R. J.; <span class=\"citation\">Y. Ab. Zar. II, 40ᵈ</span> <span dir=\"rtl\">הוה ליה כן</span>. Ib. bot. <span dir=\"rtl\">ימות ולא כן</span> let him rather die than do this (idolatrous cure); a. fr.—<span class=\"citation\">Y. Ber. III, 6ᵇ</span> top <span dir=\"rtl\">לָכֵן דאתינן</span> (v. <a href=\"#\" data-headword=\"כֵּן I\">preced.</a>) it is for this purpose that we came here (to be reminded of death).—<span dir=\"rtl\">דִּל כֵּן</span>, <a href=\"#\" data-headword=\"דִּלָכֵן\">דִּלָכֵן</a>, v. <a href=\"#\" data-headword=\"דִּל\">דִּל</a>.—<span dir=\"rtl\">כל דכן</span>, v. <a href=\"#\" data-headword=\"כּוֹל\">כּוֹל</a>.—<a href=\"#\" data-headword=\"כֵּינִי\">כֵּינִי</a> = <span dir=\"rtl\">כין הי</span> <i>it is so</i>; (interrog.) <i>is it so, indeed?</i> <span class=\"citation\">Y. Peah II, 17ᵃ</span> bot. <span dir=\"rtl\">וכ׳ אלא כ׳</span> is that so? (No,) but it is thus. Ib. III, 17ᶜ top <a href=\"#\" data-headword=\"כ׳\">כ׳</a> (insert <a href=\"#\" data-headword=\"מַתְנִיתָא\">מתניתא</a>); ib. II, beg. 16ᵈ <span dir=\"rtl\">כ׳ מתניתא</span> (not <a href=\"#\" data-headword=\"ב׳\">ב׳</a>) so is the Mishnah to be read. Y. B. Mets. III, beg. 9ᵃ <span dir=\"rtl\">וְאִין כ׳</span> but if this be so; a. fr.</div>","alt":["כֵּין"]},"12690":{"h":"כֵּן II","r":"K00828","html":"<div class=\"sense\">, with suff. <span dir=\"rtl\">כַּנּ־</span>, m. (b. h.; <a href=\"#\" data-headword=\"כּוּן\">כּוּן</a> or <a href=\"#\" data-headword=\"כָּנַן\">כָּנַן</a>) </div><div class=\"sense\"><b>1)</b> <i>base, stand, rest</i>. <span class=\"citation\">Cant. R. to I, 1</span> (ref. to <span dir=\"rtl\">והנה חלום</span>, <span class=\"citation\">I Kings III, 15</span>) <span dir=\"rtl\">החלום … על כַּנּוֹ</span> the dream (after he awoke) remained standing on its firm stand (was realized); <span class=\"citation\">Yalk. Kings 175</span>. <span class=\"citation\">Yoma V, 3</span>, sq. <span dir=\"rtl\">הניחו על כ׳ וכ׳</span> he set it down on the stand. <span class=\"citation\">Tosef. Kel. B. Mets. II, 17</span> <span dir=\"rtl\">מחוסרין כן</span> vessels that have lost their rest; a. fr.—Pl. <span dir=\"rtl\">כַּנִּים</span>, constr. <a href=\"#\" data-headword=\"כני\">כַּנֵּי</a>. <span class=\"citation\">Kel. XI, 3</span>.— Trnsf. <i>social status</i>. <span class=\"citation\">Yeb. 77ᵇ</span> <span dir=\"rtl\">גיורת מכַּנָּהּ</span> a proselyte of her own status, i.e. born after the conversion of her parents both of whom were of the same nation.</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"כּוּן\">כּוּן</a> <i>Pi.</i>) <i>ruler</i>. Ib. XII, 8; <span class=\"citation\">Tosef. Kel. B. Bath. VII, 12</span> <span dir=\"rtl\">הכן והכַּנָּה</span> (Var. <span dir=\"rtl\">והכַּנָּא</span>) the ruler and that which is ruled (the writing material); oth. opin.: the ruled material and the ruler; [oth. opin.: (cmp. σταθμός) the <i>base</i> of the scales and the <i>scales</i>; oth. opin. <i>the strike</i> and <i>the measure</i>.]</div>","alt":[]},"12691":{"h":"כַּנָּא","r":"K00829","html":"<div class=\"sense\"><b>1)</b> <i>base, fixed place, line</i>.—Pl. <span dir=\"rtl\">כַּנַּיָּיא</span>. <span class=\"citation\">Ber. 57ᵇ</span> <span dir=\"rtl\">בכַנַּיְיהוּ חזי</span> (Ms. M. <span dir=\"rtl\">בב׳</span>) he saw them (in his dream) in the regular places (as planted in the field). V. <a href=\"#\" data-headword=\"*כַּנְהָא\">כַּנְהָא</a>.</div><div class=\"sense\"><b>—2)</b> <i>kanna</i>, a small measure (v. <a href=\"#\" data-headword=\"כֵּן II\">preced.</a>). <span class=\"citation\">Keth. 99ᵇ</span>; <span class=\"citation\">Meïl. 21ᵇ</span> <span dir=\"rtl\">כ׳ כ׳ בפרוטה</span> each <i>k</i>. for a P’rutah (no reduction for larger quantities).—Pl. <a href=\"#\" data-headword=\"כני\">כַּנֵּי</a>. Ib.</div>","alt":[]},"12692":{"h":"כִּנָּא","r":"K00830","html":"<div class=\"sense\"><i>louse</i>, v. <a href=\"#\" data-headword=\"כִּינָּא\">כִּינָּא</a>. [<span class=\"citation\">Targ. Y. II, Gen. XXXVIII, 26</span> <a href=\"#\" data-headword=\"בכנא\">בכנא</a> some ed., read: <span dir=\"rtl\">בדינא</span>.]</div>","alt":[]},"12693":{"h":"*כַּנְגַּד","r":"K00831","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (prob. = <a href=\"#\" data-headword=\"גִּנְגִּידִין\">גִּנְגִּידִין</a>) a kind of <i>chervil</i>. <span class=\"citation\">Sabb. 109ᵇ</span> אניגרון כ׳ וכ׳ Ms. M. (ed. <a href=\"#\" data-headword=\"אבנגר\">אבנגר</a>, Ar. <span dir=\"rtl\">כנגר</span>; Rashi ed. Sonc. <span dir=\"rtl\">כנגדי</span>, v. Rabb. D. S. a. l.) elaiogaron, <i>kangad</i> and theriacon are good for &amp;c., v. <a href=\"#\" data-headword=\"גִּילּוּיָיא\">גִּילּוּיָא</a>. [Ar.: = ḥantal, <i>cucumis colocynthis</i>; Löw Pfl. p. 294: = Κανάρα <i>artichoke</i>.]</div>","alt":[]},"12694":{"h":"כַּנְדָּא I","r":"K00832","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (κάνδυς, Pers.) <i>a gown</i> with wide sleeves.—Pl. <span dir=\"rtl\">כַּנְדֵּי</span>. <span class=\"citation\">M. Kat. 24ᵃ</span> תליסר כ׳ מאני Ar. (ed. <span dir=\"rtl\">תריסר מני</span>; Ms. M. <span dir=\"rtl\">תל׳ בגדי מני</span>, <a href=\"#\" data-headword=\"מני\">מני</a> being a gloss to our w.).</div>","alt":[]},"12695":{"h":"כַּנְדָּא II","r":"K00833","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (dial. for <a href=\"#\" data-headword=\"כַּר ²\">כַּרָּא</a>, cmp. <a href=\"#\" data-headword=\"גּוּנְבְּרָא\">גּוּנְדְּרָא</a>) <i>pitcher, pot</i>. [<span class=\"citation\">Pes. 111ᵇ</span>, v. <a href=\"#\" data-headword=\"כִּנָּרָא\">כִּנָּרָא</a>.]—Pl. <span dir=\"rtl\">כַּנְרֵּי</span>. <span class=\"citation\">Pes. 30ᵃ</span> <span dir=\"rtl\">מזבני כ׳</span> sellers of earthen ware. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אשוו זביני אכַּנְדַּיְיכוּ</span> (not <span dir=\"rtl\">דיכי …</span>; Ms. M. <span dir=\"rtl\">אשוו זבינייכו</span>) set a fair price on your pots.—<span class=\"citation\">Ḥull. 48ᵇ</span> <span dir=\"rtl\">דקיימו כ׳ כ׳</span> lungs upon which there are pot-like excrescences.—[<span class=\"citation\">Ber. 40ᵇ</span>, v. <a href=\"#\" data-headword=\"כִּנָּרָא\">כִּנָּרָא</a>.]</div>","alt":[]},"12696":{"h":"כַּנְדּוֹקָא","r":"K00834","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>Kandoka</i>, surname of one Minyomin. <span class=\"citation\">Ḥull. 49ᵇ</span>. [Rashi: <i>dealer in pottery</i>, cmp. Syr. <a href=\"#\" data-headword=\"כַּנְדּוֹקָא\">כנדוקא</a>, P. Sm. 1764; v. Fl. to Levy Talm. Dict. II, 452ᵇ.]</div>","alt":[]},"12697":{"h":"כִּנָּה","r":"K00835","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּינָּה\">כִּינָּה</a></div>","alt":[]},"12698":{"h":"כַּנָּה","r":"K00836","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"כֵּן II\"><span dir=\"rtl\">כֵּן</span> II</a>) </div><div class=\"sense\"><b>1)</b> <i>base, stand.</i> <span class=\"citation\">Kel. VII, 6</span> <span dir=\"rtl\">נותן את חכ׳ וכ׳</span> he places the base of a stove between them; [oth. opin. he puts <i>a ruler</i> between, measuring a straight line.]</div><div class=\"sense\"><b>—2)</b> <i>ruler</i> or <i>ruled material</i>. Ib. XII, 8, v. <a href=\"#\" data-headword=\"כֵּן II\"><span dir=\"rtl\">כֵּן</span> II</a>.</div>","alt":[]},"12699":{"h":"כָּנָה","r":"K00837","html":"<div class=\"sense\">, <i>Pi.</i> <a href=\"#\" data-headword=\"כִּינָּה\">כִּינָּה</a>, v. <a href=\"#\" data-headword=\"כני\">כני</a>.</div>","alt":[]},"12700":{"h":"*כַּנְהָא","r":"K00838","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"כני\">כני</a>; cmp. <span class=\"citation\">Ezra IV, 9</span>; <span class=\"citation\">17</span>) <i>of the same class, rank</i>.—Pl. <span dir=\"rtl\">כַּנְהַיָּיא</span>. <span class=\"citation\">Kerith. 3ᵇ</span> תנא יתהון בכַנְהֵיהוֹן Ar. (ed. <span dir=\"rtl\">אבינכיהון</span>, <span dir=\"rtl\">בינכיהון</span>, v. <a href=\"#\" data-headword=\"*בִּינְכָא\">בִּינְכָא</a>) the redactor specifies them among their classes.</div>","alt":[]},"12701":{"h":"*כְּנָוָותָה","r":"K00839","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"*כַּנְהָא\">preced.</a>) <i>K’navatha</i>, an adaptation of the name of a Babylonian festive time and fair. <span class=\"citation\">Y. Ab. Zar. I, 39ᶜ</span> <span dir=\"rtl\">מחורי וכנוני וכ׳</span>; cmp. <a href=\"#\" data-headword=\"אַקְנָיָיתָא\">אַקְנָיָיתָא</a>.</div>","alt":[]},"12702":{"h":"כִּנּוּי","r":"K00840","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּנֶּרֶת\">כִּינּ׳</a></div>","alt":["כִּנּוּיָא"]},"12703":{"h":"כָּנוֹן","r":"K00841","html":"<div class=\"sense\"><i>, </i> pl. <span dir=\"rtl\">כָּנוֹנִים</span>, v. <a href=\"#\" data-headword=\"כּוֹנָנִית\">כּוֹנָנִית</a>.</div>","alt":[]},"12704":{"h":"כָּנוֹנָא","r":"K00842","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּנַן\">כנן</a>) <i>a</i> (<i>fire</i>) <i>stand, a portable brazier</i>, v. <a href=\"#\" data-headword=\"כַּנָּה\">כַּנָּה</a>. <span class=\"citation\">Bets. 21ᵇ</span>; <span class=\"citation\">Sabb. 47ᵃ</span></div>","alt":[]},"12705":{"h":"כָּנוֹנֵי","r":"K00843","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּנוֹנָא\">preced.</a>) an adaptation of a <i>Babylonian festive season</i> and fair., v. <a href=\"#\" data-headword=\"*כְּנָוָותָה\">כְּנָוָותָה</a>.</div>","alt":[]},"12706":{"h":"כִּנּוּס","r":"K00844","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּינּוּס\">כִּינּוּס</a></div>","alt":[]},"12707":{"h":"כְּנוּפְיָא","r":"K00845","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (כְּנַף I) <i>crowd, assembly</i> (cmp. <a href=\"#\" data-headword=\"דּוּחֲקָא\">דּוֹחֲקָא</a>). <span class=\"citation\">Targ. Y. Num. XXXIII, 25</span> (transl. <span dir=\"rtl\">מקהלות</span>) <span dir=\"rtl\">אתר כ׳</span>.—<span class=\"citation\">Sabb. 60ᵇ</span> <span dir=\"rtl\">איכא כי׳</span> there is a large gathering (in synagogues &amp;c.). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כי׳ דאיסורא</span> gathering on a day when labor is not permitted. <span class=\"citation\">R. Hash. 27ᵃ</span> <span dir=\"rtl\">כל כי׳ דכסף הוא</span> all signals for assemblies were blown on silver horns. <span class=\"citation\">Yoma 51ᵃ</span> <span dir=\"rtl\">אתי בכ׳</span> is offered by large crowds. <span class=\"citation\">Gitt. 11ᵃ</span> כ׳ דארמאי Ar. a. Rashi (ed. <span dir=\"rtl\">כְּנוּפְיָאתָא</span> pl.) popular assemblies of gentiles, opp. <a href=\"#\" data-headword=\"עַרְכָאוֹת\">ערכאות</a>, v. <a href=\"#\" data-headword=\"עַרְכִי\">עַרְכִי</a>. <span class=\"citation\">B. Kam. 113ᵃ</span> <span dir=\"rtl\">וכי לדידכו כְּנוּפַיְכוּ</span> is your gathering (v. <a href=\"#\" data-headword=\"כַּלָּה\">כַּלָּה</a>) held for your individual benefit? (Var. v. <a href=\"#\" data-headword=\"כְּנַף I\"><span dir=\"rtl\">כְּנַף</span> I</a>).—Pl. <span dir=\"rtl\">כְּנוּפְיָאתָא</span>, v. supra.</div>","alt":["כִּינּוּפְיָא"]},"12708":{"h":"כִּנּוֹר","r":"K00846","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>lute, cithern</i>. <span class=\"citation\">Arakh. 13ᵇ</span> <span dir=\"rtl\">כ׳ של מקדש וכ׳</span> the <i>kinnor</i> of the Temple was seven-stringed. <span class=\"citation\">Ber. 3ᵇ</span>; Y. ib. I, 2ᵈ כ׳ היה תלוי וכ׳ David had a lute suspended &amp;c. <span class=\"citation\">Snh. 101ᵃ</span> <span dir=\"rtl\">עשאוני בניך ככ׳ וכ׳</span> thy children made me (the Law) like an instrument upon which the scorners play; a. fr.—Pl. <span dir=\"rtl\">כִּנּוֹרוֹת</span>, <span dir=\"rtl\">כִּנּוֹרִים</span>, <a href=\"#\" data-headword=\"כָּבֵד I\">כִּי׳</a>. <span class=\"citation\">Arakh. II, 5</span>. <span class=\"citation\">Shebu. 15ᵇ</span>. Kinnim III, 6 <span dir=\"rtl\">בני מעיו לכ׳</span> its small bowels are used for strings for the cithern; <span class=\"citation\">Ab. Zar. 47ᵃ</span> מהו לכ׳ Ms. M. (ed. <span dir=\"rtl\">לפארות</span>). <span class=\"citation\">Pesik. R. s. 26</span>; a. e.</div>","alt":["כִּינּוֹר"]},"12709":{"h":"כִּנּוֹרָא","r":"K00847","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Gen. IV, 21</span> (v. Berl. Targ. O. II, p. 3). <span class=\"citation\">Targ. Job XXX, 31</span> <a href=\"#\" data-headword=\"כִּנֶּרֶת\">כִּינָּ׳</a> (ed. Wil. <a href=\"#\" data-headword=\"כִּינּוּיָא\">כִּנָ׳</a>); a. fr.—Pl. <span dir=\"rtl\">כִּנָּרַיָּא</span>, <span dir=\"rtl\">כִּנָּרִין</span>, <a href=\"#\" data-headword=\"כִּינּוּיָא\">כִּנְּ׳</a>, <a href=\"#\" data-headword=\"כָּבֵד I\">כִּי׳</a>. <span class=\"citation\">Targ. Ps. XCII, 4</span>. <span class=\"citation\">Targ. Y. Gen. XXXI, 27</span> (O. <span dir=\"rtl\">חִנְגִּין</span>, v. Berl. l. c. p. 12). <span class=\"citation\">Targ. Is. XVI, 11</span> (ed. Lag. sing.); a. fr.</div>","alt":["כִּינּוֹ׳","כִּנָרָא"]},"12710":{"h":"כְּנוֹשָׁאָה","r":"K00848","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּנַשׁ\">כְּנַשׁ</a>) <i>sweeper</i>.—Pl. <a href=\"#\" data-headword=\"כְּנוֹשָׁאָה\">כְּנוֹשָׁאֵי</a>. <span class=\"citation\">Ḥull. 60ᵃ</span>, v. <a href=\"#\" data-headword=\"זְלוֹחאָה\">זְלוֹחָאָה</a>.</div>","alt":[]},"12711":{"h":"כני","r":"K00849","html":"<div class=\"sense\">, <i>Pi.</i> <a href=\"#\" data-headword=\"כִּנָּה\">כִּנָּה</a>, <a href=\"#\" data-headword=\"כִּינָּה\">כִּינָּה</a> (b. h., v. <a href=\"#\" data-headword=\"כֵּן I\"><span dir=\"rtl\">כֵּן</span> I</a>) </div><div class=\"sense\"><b>1)</b> <i>to qualify, define; to surname, to nickname; to modify an expression, circumscribe; to compare</i>. <span class=\"citation\">B. Mets. 58ᵇ</span> <span dir=\"rtl\">המְכַנֶּה שם רע וכ׳</span> he who calls his neighbor by a nickname. <span class=\"citation\">Shebu. 36ᵃ</span> <a href=\"#\" data-headword=\"כַּנָּה\">כַּנֵּה</a> circumscribe (use the third person as euphemism). <span class=\"citation\">Sifré Num. 84</span>, a. fr. <span dir=\"rtl\">כי׳ הכתוב</span> the Bible modifies the expression (to avoid anthropomorphism, e.g. <span class=\"citation\">Zech. II, 12</span> <span dir=\"rtl\">עינו</span> for <span dir=\"rtl\">עיני</span>). <span class=\"citation\">Meg. IV, 9</span> <span dir=\"rtl\">המבנה בעריות</span> he who modifies (symbolizes) in translating the laws of incest (e.g. <span class=\"citation\">Lev. XVIII, 7</span>, ‘uncover not thy parents’ weakness or disgrace’). <span class=\"citation\">Yalk. Num. 771</span>, v. <a href=\"#\" data-headword=\"פּוֹלְיָיטוֹן\">פּוֹלְיָיטוֹן</a>; a. fr. Part. pass. <a href=\"#\" data-headword=\"מְכוֹנָה\">מְכוּנֶּה</a>. Tanḥ. Ki Thissa 17 (ref. to <span dir=\"rtl\">באדם</span>, <span class=\"citation\">Ps. LXVIII, 19</span>) <span dir=\"rtl\">מכ׳ משה באדם</span> (not <span dir=\"rtl\">לאדם</span>) the name of Moses is here disguised by the substitute <i>Adam</i>.—[<span class=\"citation\">Yalk. Ps. 832</span> <a href=\"#\" data-headword=\"מְכוֹנָה\">מכונה</a>, v. <a href=\"#\" data-headword=\"כָּנַן\">כָּנַן</a>.]</div>","alt":["כָּנָה"]},"12712":{"h":"כני ²","r":"K00850","html":"<div class=\"sense\">, <i>Pa</i>. <a href=\"#\" data-headword=\"כני\">כַּנֵּי</a> ch. same. <span class=\"citation\">Targ. Y. Gen. IV, 26</span>.—<span class=\"citation\">Shebu. 36ᵃ</span> <span dir=\"rtl\">לא מְכַנִּינָן</span> we must not modify the (Biblical) expression (to avoid cacophemism).—[<span class=\"citation\">Bets. 33ᵇ</span> <span dir=\"rtl\">מכניא</span>, read: <span dir=\"rtl\">מכניף</span>, v. <a href=\"#\" data-headword=\"כְּנַף I\"><span dir=\"rtl\">כְּנַף</span> I</a>.]</div><div class=\"sense\"><b>Ithpa. אִתְכַּנֵּי</b> </div><div class=\"sense\"><b>Ithpe. אִתְכְּנֵי</b> <div class=\"sense\"><b>1)</b> <i>to be surnamed</i>. <span class=\"citation\">Targ. Is. I, 4</span>.—</div><div class=\"sense\"><b>*2)</b> <i>to associate one’s self</i> (v. <a href=\"#\" data-headword=\"*כַּנְהָא\">כַּנְהָא</a>). <span class=\"citation\">Targ. Ez. XXIX, 7</span> <span dir=\"rtl\">באִתְכְּנָיוּתְהוֹן וכ׳</span> when they form an alliance with thee (h. text <span dir=\"rtl\">בתפשם</span>; Kimḥi quotes a Var. <span dir=\"rtl\">באתכנעותהון</span>, v. <a href=\"#\" data-headword=\"כְּנַע\">כְּנַע</a>).</div></div>","alt":[]},"12713":{"h":"כַּנְיָא","r":"K00851","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>Kanya Parva</i>, name of an unclean bird. <span class=\"citation\">Ḥull. 62ᵇ</span> כ׳ פ׳ אסיר Ar. (ed. <span dir=\"rtl\">בוניא שרי פ׳ אסיר</span>).</div>","alt":["כ׳ פַּרְוָוא"]},"12714":{"h":"כְּנִימָּה","r":"K00852","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"כִּנָּא\">כִּנָּם</a>; cmp. <a href=\"#\" data-headword=\"כַּלְמְתָא\">כַּלְמְתָא</a>) <i>vermin, moth</i>. <span class=\"citation\">Sifré Deut. 40</span>. <span class=\"citation\">Y. B. Kam. IX, beg. 6ᵈ</span> <span dir=\"rtl\">הרקיבו מן הכ׳</span> if the grain became ruined by moths, contrad. to <span dir=\"rtl\">תולעים</span>. <span class=\"citation\">Makhsh. VI, 1</span>; <span class=\"citation\">Tosef. ib. III, 1</span> <span dir=\"rtl\">מפני הכ׳</span> in order to prevent the grain from getting mothy.—Pl. <span dir=\"rtl\">כְּנִימּוֹת</span>. <span class=\"citation\">Midr. Till. to Ps. XXIII</span>, <span dir=\"rtl\">ולא היו עושין כ׳</span> (ed. Bub. <span dir=\"rtl\">עושין בהם כִּנָּמִיּוֹת …</span>; v. note a. l.) but did they not get vermin?; <span class=\"citation\">Cant. R. to IV, 11</span> <span dir=\"rtl\">כִּנָּמִיּוֹת</span>; (<span class=\"citation\">Yalk. Ps. 691</span> <a href=\"#\" data-headword=\"בְּלָאוֹת\">בלאות</a>; <span class=\"citation\">Deut. R. s. 7</span> <a href=\"#\" data-headword=\"מַאֲכוֹלֶת\">מאכולת</a>)</div>","alt":[]},"12715":{"h":"כְּנִיסָא","r":"K00853","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּנִישָׁא\">כְּנִישָׁא</a></div>","alt":[]},"12716":{"h":"כְּנִיסָה","r":"K00854","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּנַס\">כָּנַס</a>) </div><div class=\"sense\"><b>1)</b> <i>gathering, assembly</i>. <span class=\"citation\">Meg. I, 1</span> <span dir=\"rtl\">מקדימין ליום הכ׳</span> read the M’gillah in advance on the gathering (market) day before Purim. Ib. 4ᵇ; a. e.</div><div class=\"sense\"><b>—2)</b> <i>entering</i>, opp. <a href=\"#\" data-headword=\"יְצִיאָה\">יציאה</a>. <span class=\"citation\">Y. Erub. V, 22ᶜ</span>; <span class=\"citation\">Midd. I, 3</span>, v. <a href=\"#\" data-headword=\"יְצִיאָה\">יְצִיאָה</a>.—<span class=\"citation\">B. Mets. 104ᵃ</span> <span dir=\"rtl\">בשעת כְּנִיסָתָן לחופה</span> when they were being led to the wedding chamber. <span class=\"citation\">Keth. 12ᵃ</span>. <span class=\"citation\">Ber. IV, 2</span> <span dir=\"rtl\">בכְנִיסָתוֹ לבה&quot;מ</span> on his entering college (for teaching and judging). <span class=\"citation\">B. Mets. 83ᵇ</span> <span dir=\"rtl\">בכְנִיסָתוֹ</span> the time consumed in going home, v. <a href=\"#\" data-headword=\"פּוֹעֵל\">פּוֹעֵל</a>; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>keeping in, detention</i>. <span class=\"citation\">Yalk. Num. 782</span>, v. <a href=\"#\" data-headword=\"עֲצִירָה\">עֲצִירָה</a>.—[<span class=\"citation\">Y. Shebi. VII, beg. 37ᵇ</span> <span dir=\"rtl\">כניסות</span>, v. <a href=\"#\" data-headword=\"כְּבִיסָה\">כְּבִיסָה</a>.]</div><div class=\"sense\"><b>—4)</b> <i>recess, settle</i>. <span class=\"citation\">Men. 97ᵇ</span>, interch. with <a href=\"#\" data-headword=\"כּוֹנְסָה\">כּוֹנְסָה</a> a. <a href=\"#\" data-headword=\"כְּנָסָה\">כְּנָסָה</a>.</div>","alt":[]},"12717":{"h":"כניסתא","r":"K00855","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Prov. XXV, 23</span> some ed., read <a href=\"#\" data-headword=\"בְּנִיסָא\">בְּנִיסָתָא</a>, v. <a href=\"#\" data-headword=\"בְּנִיסָא\">בְּנִיסָא</a>.</div>","alt":[]},"12718":{"h":"כְּנִישׁ","r":"K00856","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּנַשׁ\">כְּנַשׁ</a>) <i>festive gathering</i>. <span class=\"citation\">Targ. O. Deut. XVI, 8</span>. <span class=\"citation\">Targ. II Chr. VII, 9</span> (h. text <a href=\"#\" data-headword=\"עֲצֶרֶת\">עצרת</a>).</div>","alt":[]},"12719":{"h":"כְּנִישָׁא","r":"K00857","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּנִישׁ\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>gathering</i>;<i> assembly</i>. <span class=\"citation\">Targ. O. Gen. I, 10</span> <span dir=\"rtl\">בית כְּנִישַׁת מיא</span> (h. text <a href=\"#\" data-headword=\"מִקְוֶה\">מקוה</a>). <span class=\"citation\">Targ. Ex. XXXV, 1</span> (ed. Amst. <span dir=\"rtl\">כְּנִישְׂ׳</span>). <span class=\"citation\">Targ. Joel I, 14</span>. <span class=\"citation\">Targ. Ps. XLVIII, 12</span> (some ed. <a href=\"#\" data-headword=\"כְּנִישָׁא\">כְּנִישָׁתָא</a> pl., h. text <a href=\"#\" data-headword=\"בָּנוֹת\">בנות</a>); a. fr.—Y. Peah I, 15ᵈ <span dir=\"rtl\">איזיל צור כ׳ עליה</span> shall I call a meeting against him?; a. e.</div><div class=\"sense\"><b>—2)</b>  <a href=\"#\" data-headword=\"כ׳\">כ׳</a> or (<span dir=\"rtl\">בי</span>) <span dir=\"rtl\">בית כ׳</span> <i>synagogue, school-house</i>. <span class=\"citation\">Targ. Ez. XI, 16</span>; a. fr.—<span class=\"citation\">Y. M. Kat. III, 81ᵈ</span> bot. <span dir=\"rtl\">קומי חדא כ׳</span> before a certain synagogue. <span class=\"citation\">Ber. 7ᵇ</span>; a. fr.—כ׳ רבתא <i>the Great Synagogue, Synagoga Magna</i>, v. <a href=\"#\" data-headword=\"כְּנֶסֶת\">כְּנֶסֶת</a>. <span class=\"citation\">Targ. Cant. VI, 5</span>; a. e.—Pl. <a href=\"#\" data-headword=\"כְּנִישָׁא\">כְּנִישָׁתָא</a>, v. supra; <a href=\"#\" data-headword=\"כְּנִישָׁא\">כְּנִישָׁן</a>, <a href=\"#\" data-headword=\"כְּנִיסָא\">כְּנִיסָן</a>. <span class=\"citation\">Y. Kil. IX, 32ᵇ</span> top <span dir=\"rtl\">אשירוניה תמני עסרי כ׳</span> they stopped the funeral procession eighteen times for mourning assemblies; <span class=\"citation\">Y. Keth. XII, 35ᵃ</span> <a href=\"#\" data-headword=\"בניסן\">בניסן</a> (corr. acc.).—[<span class=\"citation\">B. Mets. 21ᵃ</span> כ׳ דבי דרי Ar., v. <a href=\"#\" data-headword=\"מַכְנַשְׁתָּא\">מַכְנַשְׁתָּא</a>.]</div>","alt":["כְּנִישְׁתָּא","כְּנִשְׁ׳"]},"12720":{"h":"כַּנְכָּב","r":"K00858","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּבְכָּב\">כַּבְכָּב</a></div>","alt":[]},"12721":{"h":"כָּנַן","r":"K00859","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"כּוּן\">כּוּן</a> a. <a href=\"#\" data-headword=\"כּוֹנָנִית\">כּוֹנָנִית</a>) <i>to nest</i>.—Denom. <a href=\"#\" data-headword=\"כִּינָּה\">כִּינָּה</a>.</div><div class=\"sense\"><b>Pi. כִּנֵּן</b> <div class=\"sense\"><i>to form circles, to wind around.</i> <span class=\"citation\">Par. VII, 7</span> <span dir=\"rtl\">המְכַנֵּן … על יד על יד</span> (Talm. ed. only once <span dir=\"rtl\">על יד</span>) he who winds the rope (for drawing the bucket up) around his hand until a sufficient length is wound up; <span dir=\"rtl\">ואם כִּנְּנוֹ באחרונה</span> but if he winds it after he has finished drawing; Tosef. ib. VII (VI), 4 <span dir=\"rtl\">וחזר ובנאו</span> ed. Zuck. (Var. <span dir=\"rtl\">וכי</span>, read: <span dir=\"rtl\">וכיננו</span> as R. S. to Par. l. c.).—<i>Part. pass</i>. <span dir=\"rtl\">מְכוּנָּן</span> a) <i>wound around.</i> <span class=\"citation\">Makhsh. IV, 1</span> <span dir=\"rtl\">בחבל שהוא מכ׳ וכ׳</span> with the rope which is wound around the neck of the vessel.—2) <i>nested</i>. <span class=\"citation\">Gen. R. s. 37</span> <span dir=\"rtl\">מכ׳ כביצה</span> shut up in the nest like an egg, i.e. selfish; <span class=\"citation\">Yalk. Ps. 832</span> <a href=\"#\" data-headword=\"מְכוֹנָה\">מכונה</a> (corr. acc.).</div></div>","alt":[]},"12722":{"h":"כָּנַס","r":"K00860","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"כּוֹס I\"><span dir=\"rtl\">כּוֹס</span> I</a>) </div><div class=\"sense\"><b>1)</b> <i>to collect, gather; to cover, shelter, bring home</i>. <span class=\"citation\">B. Kam. VI, 1</span> <span dir=\"rtl\">הכּוֹנס צאן לדיר</span> he who takes the flock into the stall; a. fr.—כ׳ משקה <i>to absorb</i> liquids through pores, opp. to <a href=\"#\" data-headword=\"יָצָא\">הוציא</a> to let liquids escape through pores. <span class=\"citation\">Nidd. 49ᵃ</span> <span dir=\"rtl\">יביא … אם כָּנְסָה וכ׳</span> get a tub full of water and put the pot in, if it draws water &amp;c. <span class=\"citation\">Kel. X, 8</span> <span dir=\"rtl\">היו בכוֹנֵס משקה</span> (sub. <span dir=\"rtl\">נקובין</span>) if the vessels were so porous as to be called absorbers of liquids. Nidd. l. c. <span dir=\"rtl\">כיצד … לידע אם ניקב בכונס משקה</span> how do we examine to find out whether a vessel is porous to the extent of absorbing liquids? (v. supra); a. fr.—Esp. <i>to take a woman home, to consummate a marriage by conducting a woman to one’s house, to wed</i>, v. <a href=\"#\" data-headword=\"אֵירוּסִין\">אֵירוּסִין</a> a. <a href=\"#\" data-headword=\"נִישּׂוּאִין\">נִישּׂוּאִין</a>. <span class=\"citation\">Keth. 3ᵇ</span> <span dir=\"rtl\">וברביעי כּוֹנְסָהּ</span> and on the fourth day of the week he weds her. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ומסכנה ואילך נהגו … לִכְנוֹס וכ׳</span> and from the days of persecution … the people adopted the custom to wed on the third day; … <span dir=\"rtl\">ובשני לא יִכְנוֹס</span> but on the second day one must not marry. <span class=\"citation\">Y. Yeb. IV, 6ᵇ</span> <span dir=\"rtl\">כְּנָסָהּ ולא וכ׳</span> he took her to his home but did not touch her &amp;c.; a. fr.—Part. pass. <a href=\"#\" data-headword=\"כְּבוּסָה\">כְּנוּסָה</a>. <span class=\"citation\">Y. Sot. II, 18ᵇ</span> top <span dir=\"rtl\">שומרת יבם וכ׳</span> neither while waiting for the <i>yabam</i> nor after having been taken to his house.</div><div class=\"sense\"><b>—2)</b>  (of a sore) [<i>to gather</i>,] <i>to grow smaller, to contract</i>, opp. <span dir=\"rtl\">פשה</span>. <span class=\"citation\">Neg. IV, 7</span>; <span class=\"citation\">Tosef. ib. II, 6</span>; Sifra Thazr., Neg., Par. 2, ch. II; a. e.</div><div class=\"sense\"><b>—3)</b>  (archit.) <i>to recede, to form a settle</i> or <i>recess</i> in a wall. <span class=\"citation\">Midd. III, 1</span> <span dir=\"rtl\">עלה אמה וכ׳ אמה</span> (the altar) rose one cubit and then receded one cubit; <span class=\"citation\">Men. 97ᵇ</span>.—<span class=\"citation\">Y. Erub. VII, 24ᵇ</span> bot. (of an inclined plane) <span dir=\"rtl\">עולה אמה וכוֹנֵס שלש</span> it rises vertically one cubit, while the incline measures three cubits, v. <a href=\"#\" data-headword=\"כִּיבּוּשׁ\">כִּיבּוּשׁ</a>.—Part. pass. <a href=\"#\" data-headword=\"כִּנּוּס\">כָּנוּס</a>, f. <a href=\"#\" data-headword=\"כְּבוּסָה\">כְּנוּסָה</a>. <span class=\"citation\">Tosef. Erub. I, 10</span> <span dir=\"rtl\">כותל שצידו אחד כ׳ מחבירו וכ׳</span> a wall which is more receding on one side than on the other, either the inner wall being even &amp;c.; <span class=\"citation\">Erub. 9ᵇ</span>; <span class=\"citation\">15ᵃ</span>; (Y. ib. 19ᵇ top <span dir=\"rtl\">כותל הנכנס</span>). <span class=\"citation\">Y. Succ. I, 52ᵃ</span> <span dir=\"rtl\">אפי׳ כנוסה כמה</span> even if the reduction be ever so large.</div><div class=\"sense\"><b>Nif. נִכְנַס</b> <div class=\"sense\"><b>1)</b> <i>to be brought in, to enter</i>, opp. <span dir=\"rtl\">יצא</span>; <i>to assemble, meet</i>. <span class=\"citation\">Erub. 65ᵃ</span>, v. <a href=\"#\" data-headword=\"סוֹד\">סוֹד</a>. <span class=\"citation\">Ib. 15ᵇ</span> <span dir=\"rtl\">נ׳ ויוצא</span> is easily passed in and out. <span class=\"citation\">Kel. IX, 7</span> <span dir=\"rtl\">מלא … נ׳</span> when a piece of the size … can be passed, <span dir=\"rtl\">לא נ׳</span> when it cannot pass (exactly fitting in). Y. Erub. I, 18ᶜ bot. <span dir=\"rtl\">אין … לִיכָּנֵס וכ׳</span> it is not the habit of man to enter through one door and leave through another.—<span class=\"citation\">Ḥull. 3ᵃ</span>, a. fr. <span dir=\"rtl\">יוצא ונ׳</span> superintending by going in and out. <span class=\"citation\">Sabb. 137ᵇ</span> <span dir=\"rtl\">כשם שנ׳ … יִכָּנס וכ׳</span> as he (the child) has been entered into the covenant, so may he be introduced to the study of the Law &amp;c. <span class=\"citation\">Snh. 101ᵃ</span> <span dir=\"rtl\">נִכְנְסוּ תלמידיו וכ׳</span> his pupils came together to visit him. Tosef. Ber. VII (VI), 19, a. e. <span dir=\"rtl\">לא יִכָּנֵס אדם להר וכ׳</span> one must not enter the Temple mount &amp;c.—<span class=\"citation\">Meg. I, 3</span> <span dir=\"rtl\">מקום שנִכְנָסִין וכ׳</span> a place where the country people are in the habit of assembling on Mondays &amp;c.; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to form a recess</i> or <i>settle</i>. Y. Erub. I, 19ᵇ top, v. supra.</div><div class=\"sense\"><b>—3)</b> <i>to be married</i>, v. supra. Y. Yeb. IV, 6ᵇ <span dir=\"rtl\">הִיכָּנְסִי וכ׳</span> be my wife and raise thy sister’s children; <span class=\"citation\">Koh. R. to IX, 9</span>; a. fr.</div></div><div class=\"sense\"><b>Pi. כִּינֵּס</b> <div class=\"sense\"><i>to gather, collect</i>. Tosef. Ber. VII (VI), 24 <span dir=\"rtl\">בשעת המְכַנְּסִין … כַּנֵּס</span> when people collect (learning), scatter, when they scatter (are indifferent), gather in (withdraw); v. <a href=\"#\" data-headword=\"בְּדַר\">בְּדַר</a>; <span class=\"citation\">Ber. 63ᵃ</span> <span dir=\"rtl\">המכניסים</span> (read: <span dir=\"rtl\">המְכַנְּ׳</span>, v. Rabb. D. S. a. l. note 9). <span class=\"citation\">Ex. R. s. 17</span>, beg. <span dir=\"rtl\">שכִּינְּסָן מעל הארץ</span> which (waters) he gathered from upon the land. <span class=\"citation\">Deut. R. s. 3</span> <span dir=\"rtl\">כִּינְּסָה את בניה</span> she assembled her children; a. fr.—Part. pass. <span dir=\"rtl\">מְכוּנָּס</span>, f. <span dir=\"rtl\">מְכוּנֶּסֶת</span>; pl. <span dir=\"rtl\">מְכוּנָּסִין</span>, <span dir=\"rtl\">מְכוּנָּסוֹת</span>. <span class=\"citation\">Erub. 21ᵃ</span> <span dir=\"rtl\">(<a href=\"#\" data-headword=\"מַיִם\">מים</a>) <a href=\"#\" data-headword=\"מ׳\">מ׳</a></span> collected water, opp. <span dir=\"rtl\">מים חיים</span>. <span class=\"citation\">Midr. Till. to Ps. LXX</span> <span dir=\"rtl\">הרי הצאן מכ׳</span> the flock is gathered again. <span class=\"citation\">Neg. IV, 3</span> <span dir=\"rtl\">במ׳</span> when the hairs on the leprous spot are close together, opp. <span dir=\"rtl\">מפוזר</span>; a. fr.</div></div><div class=\"sense\"><b>Hif. הִכְנִיס</b> <div class=\"sense\"><i>to bring in, to lay in, store up; to introduce, pass; to initiate</i>. <span class=\"citation\">Lev. R. s. 9</span> <span dir=\"rtl\">הִכְנִיסוֹ לביתו</span> he invited him to his house. <span class=\"citation\">Ex. R. s. 20</span> <span dir=\"rtl\">אם אני מַכְנִיסָן וכ׳</span> if I lead them now into the land. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ה׳ יינו וכ׳</span> he stored his wine in the cellar. <span class=\"citation\">Men. 97ᵃ</span> <span dir=\"rtl\">ומכניס קנה וכ׳</span> and passes a tube under it. <span class=\"citation\">Sabb. 118ᵇ</span> <span dir=\"rtl\">ה׳ ידו וכ׳</span> put his hand under his belt. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מַכְנִיסֵי שבת</span> who usher the Sabbath in (with prayer). Ib. 137ᵇ <span dir=\"rtl\">להַכְנִיסוֹ בבריתו וכ׳</span> to initiate him into the covenant &amp;c. (v. supra). Y. Yeb. I, 3ᵃ bot. <span dir=\"rtl\">הרי אתם מַכְנִיסִין ראשי וכ׳</span> you want me to put my head between two great mountains. Mekh. B’shall., Shir., s. 6 <span dir=\"rtl\">לא מוציא ולא מַכְנִיס</span> neither lets escape nor receives, v. <a href=\"#\" data-headword=\"נוֹד\">נוֹד</a>; a. fr.</div></div><div class=\"sense\"><b>Hithpa. הִתְכַּנֵּס</b> </div><div class=\"sense\"><b>Nithpa. נִתְכַּנֵּס</b> <div class=\"sense\"><b>1)</b> <i>to assemble, meet, be reunited</i>. <span class=\"citation\">Taan. 27ᵇ</span> <span dir=\"rtl\">מִתְכַּנְּסִין לבה&quot;כ</span> meet at the synagogue. <span class=\"citation\">Gen. R. s. 39</span>, a. e. <span dir=\"rtl\">אם מתכנסין כל וכ׳</span> if all human beings were to join for creating &amp;c.; <span class=\"citation\">Cant. R. to I, 3</span> <span dir=\"rtl\">מִתְכַּנְּשִׁין</span>. Mekh. B’shall. s. 6 <span dir=\"rtl\">אין הגליות מִתְכַּנְּסוֹת וכ׳</span> the diaspora will be reunited only as a reward for faith; a. fr.—<span class=\"citation\">Gen. R. s. 12</span>, beg. <span dir=\"rtl\">מתכנסין ויוצאין</span>; (Koh. R. to II, 12 <span dir=\"rtl\">נכנסין</span>) they go in and out.</div><div class=\"sense\"><b>—2)</b> <i>to gather, become closer</i> (v. supra). <span class=\"citation\">Neg. I, 6</span> <span dir=\"rtl\">נִתְכַּנְּסָה</span> the sore gathered.</div></div>","alt":[]},"12723":{"h":"כְּנַס","r":"K00861","html":"<div class=\"sense\"><b>1)</b> <i>to gather, receive</i>. <span class=\"citation\">Targ. Ps. XLI, 7</span> Ms. (ed. <a href=\"#\" data-headword=\"כְּנַף I\">כנף</a>, h. text <span dir=\"rtl\">קבץ</span>). <span class=\"citation\">Targ. Esth. IV, 16</span> (Targ. II Esth. ib. <span dir=\"rtl\">כנוש</span>). <span class=\"citation\">Targ. Y. Gen. XVIII, 3</span> אֵיכְנוֹס וכ׳ I shall receive the passers-by.—V. <a href=\"#\" data-headword=\"כְּנַשׁ\">כְּנַשׁ</a>.</div><div class=\"sense\"><b>—2)</b> <i>to marry</i>. <span class=\"citation\">Y. Erub. III, 21ᵇ</span> top <span dir=\"rtl\">ומִיכְנַסְנִיךְ ליום פלן</span> and to marry thee before such a date; <span class=\"citation\">Y. Gitt. VII, end, 49ᵃ</span> <span dir=\"rtl\">ומנכסיך</span> (corr. acc.). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ולא כְנַסְתִּיךְ</span> and I shall not have married thee. <span class=\"citation\">Y. Keth. I, beg. 24ᵈ</span> <span dir=\"rtl\">אילין דכַנְסִין וכ׳</span> those who marry widows; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>to enter</i>. <span class=\"citation\">Y. Snh. VI, 23ᶜ</span> bot. <span dir=\"rtl\">כיון דכ׳</span> when he had entered; a. e.—[<span class=\"citation\">Targ. Esth. II, 21</span>; <span class=\"citation\">IV, 17</span>, v. <a href=\"#\" data-headword=\"בְּנַס\">בְּנַס</a>.]</div><div class=\"sense\"><b>Pa. כַּנֵּס</b> <div class=\"sense\"><i>to gather, heap</i>. <span class=\"citation\">Targ. Ps. XXXIII, 7</span> Ms. (ed. <a href=\"#\" data-headword=\"מכניס\">מַכְנִיס</a> <i>Af</i>.). <span class=\"citation\">Ib. CXLVII, 2</span> (Ms. <i>Pe</i>.).</div></div><div class=\"sense\"><b>Ithpe. אִתְכְּנֵס</b> <div class=\"sense\"><i>to be gathered, to assemble</i>. <span class=\"citation\">Targ. I Chr. XI, 1</span> (ed. Lag. a. Rahmer <span dir=\"rtl\">אתכניש׳</span>). <span class=\"citation\">Targ. Ps. XLVII, 10</span> Ms. (ed. <span dir=\"rtl\">אתכנש׳</span>).</div></div>","alt":[]},"12724":{"h":"כנסא","r":"K00862","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Job XVI, 10</span> Ms., v. <a href=\"#\" data-headword=\"בְּנָסָא\">בְּנָסָא</a></div>","alt":[]},"12725":{"h":"כְּנָסָה","r":"K00863","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּנִיסָה\">כְּנִיסָה</a> end.</div>","alt":[]},"12726":{"h":"כְּנֵסִיָּה","r":"K00864","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּנָסָה\">preced.</a> wds.) <i>gathering, union.</i> <span class=\"citation\">Ab. IV, 11</span> <span dir=\"rtl\">כל כ׳ וכ׳</span> every union for a sacred purpose. <span class=\"citation\">Ex. R. s. 21</span>; <span class=\"citation\">Midr. Till. to Ps. XIX</span>; <span class=\"citation\">Midr. Till. to Ps. LXXXVIII</span>, end <span dir=\"rtl\">כ׳ האחרונה</span> the latest gathering (for prayers); <span class=\"citation\">Yalk. ib. 840</span> <a href=\"#\" data-headword=\"כְּנֶסֶת\">כנסת</a>; a. e.—[<span class=\"citation\">Num. R. s. 1</span> <span dir=\"rtl\">אני בונה כ׳</span>, read: <a href=\"#\" data-headword=\"אַכְסַנְיָא\">אַכְסַנְיָא</a>, v. Tanḥ. B’midb. 2.]—Pl. <span dir=\"rtl\">כְּנֵסִיּוֹת</span>, v. <a href=\"#\" data-headword=\"כְּנֶסֶת\">next w.</a></div>","alt":[]},"12727":{"h":"כְּנֶסֶת","r":"K00865","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּנֵסִיָּה\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>gathering, storage</i>. <span class=\"citation\">Y. B. Bath. IV, 14ᶜ</span> bot. <span dir=\"rtl\">בית הכ׳ שלעצים</span> a store-house for wood (= <a href=\"#\" data-headword=\"אוֹצָר\">אוֹצָר</a>).</div><div class=\"sense\"><b>—2)</b> <i>assembly, community, congregation</i>, esp. <i>congregation of worshippers</i>. <span class=\"citation\">Ex. R. s. 21</span> (interch. with <a href=\"#\" data-headword=\"כְּנֵסִיָּה\">preced. w.</a>); <span class=\"citation\">Yalk. Ps. 840</span>, v. preced.—<span dir=\"rtl\">בית הכ׳</span> (abbr. <span dir=\"rtl\">בה&quot;כ</span>) <i>synagogue</i>. <span class=\"citation\">Ber. 6ᵃ</span>. <span class=\"citation\">Meg. III, 1</span> (<span class=\"citation\">25ᵇ</span>); a. fr.—<span class=\"citation\">Sot. VII, 7</span> <span dir=\"rtl\">חזן הכ׳</span> the sexton of the synagogue within the Temple precincts; <span class=\"citation\">Succ. 51ᵇ</span> of the synagogue of Alexandria, v. <a href=\"#\" data-headword=\"חַזָּן\">חַזָּן</a>; a. fr.—<span dir=\"rtl\">כ׳ ישראל</span> (abbrev. <a href=\"#\" data-headword=\"כי\">כ&quot;י</a>) the congregation of Israel, <i>the Ecclesia</i>, (often personified as a woman betrothed to the Lord). <span class=\"citation\">Cant. R. to I, 4</span>; a. fr.—<span dir=\"rtl\">כ׳ הגדולה</span> (abbr. <span dir=\"rtl\">כה&quot;ג</span>) <i>the Great Assembly, Ecclesia</i> or <i>Synagoga Magna</i>, a supreme authority established under Ezra and Nehemiah. <span class=\"citation\">Ab. I, 1</span>, a. fr. <span dir=\"rtl\">אנשי כ׳ הג׳</span> the men of the original Great Synagogue. <span class=\"citation\">Ib. 2</span> <span dir=\"rtl\">שירי כה&quot;ג</span> the last members of the Great Synagogue.—Pl. <span dir=\"rtl\">כְּנֵסִיּוֹת</span>, <span dir=\"rtl\">כְּנֵיסִ׳</span>. Lam. R. introd. (R. Yitsḥ. 3) <span dir=\"rtl\">בני כְּנֵסִיּוֹתָיו</span> his fellow-members in the royal council; (<span class=\"citation\">Yalk. Is. 318</span> <span dir=\"rtl\">בני המלך</span>).—<span dir=\"rtl\">בתי כ׳</span> synagogues. <span class=\"citation\">Meg. 6ᵃ</span>. Y. ib. III, beg. 73ᵈ <span dir=\"rtl\">ארבע … ב׳ כ׳ וכ׳</span> there were four hundred and eighty synagogues in Jerusalem, and each had a school &amp;c. <span class=\"citation\">Ḥull. 51ᵃ</span> <span dir=\"rtl\">מפטיר כ׳</span> janitor at meetings of scholars in college. <span class=\"citation\">Pes. 49ᵇ</span> <span dir=\"rtl\">ראשי כ׳</span> chiefs of congregations or synagogues.</div>","alt":[]},"12728":{"h":"כְּנַע","r":"K00866","html":"<div class=\"sense\"><i>to press, oppress</i>.—Part. pass. <span dir=\"rtl\">כְּנִיעַ</span>, pl. <span dir=\"rtl\">כְּנִיעִין</span> <i>depressed, mournful</i>. <span class=\"citation\">Y. Ter. XI, end, 48ᵇ</span> <span dir=\"rtl\">ע&quot;י דאינון כ׳</span> because they are low-spirited.</div><div class=\"sense\"><b>Ithpa. אִתְכַּנַּע</b> </div><div class=\"sense\"><b>Ithpe. אִיכְּנַע</b> <div class=\"sense\"><i>to lower one’s self, be humble</i>. <span class=\"citation\">Targ. Y. Gen. XVI, 9</span> (h. text <span dir=\"rtl\">התעני</span>). <span class=\"citation\">Targ. I Kings XXI, 29</span>. <span class=\"citation\">Targ. Is. XLI, 11</span> (h. text <span dir=\"rtl\">יכלמו</span>); a. fr.—<span class=\"citation\">Targ. Ez. XXIX, 7</span> באִתְכְּנָעוּתְהוֹן Var., v. <a href=\"#\" data-headword=\"כני\">כני</a> ch.—Y. Taan. III, 66ᶜ bot. <span dir=\"rtl\">מִתְכַּנְּעִין</span> they humble themselves (in penitence).—Esp. <i>to bow to a superior, to salute</i>. <span class=\"citation\">Gen. R. s. 33</span> <span dir=\"rtl\">ולא א׳ מיניה</span> and he did not salute him. <span class=\"citation\">M. Kat. 16ᵇ</span> <span dir=\"rtl\">ולא אִיכְנְעָא מקמיה</span> and she did not bow to him; a. e.</div></div>","alt":[]},"12729":{"h":"כנעה","r":"K00867","html":"<div class=\"sense\">, <span class=\"citation\">Y. Ned. III, 37ᵈ</span> bot., read: <a href=\"#\" data-headword=\"נַנְעָא\">נַנְעָה</a>.</div>","alt":[]},"12730":{"h":"כְּנַעַן","r":"K00868","html":"<div class=\"sense\"> (b. h.) pr. n. <i>Canaan</i>, </div><div class=\"sense\"><b>1)</b>  son of Ham. <span class=\"citation\">Gen. R. s. 36</span> חם חטא וכ׳ וכ׳ Ham sinned and C. was cursed?; Tanḥ. Noah 15; a. e.</div><div class=\"sense\"><b>—2)</b> <i>the land of Canaan</i>. <span class=\"citation\">R. Hash. 3ᵃ</span> <span dir=\"rtl\">כ׳ על שם מלכותו</span> (Sihon is named) C. from his kingdom; a. fr.</div>","alt":[]},"12731":{"h":"כְּנַעֲנָאָה","r":"K00869","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <span class=\"citation\">Targ. O. Gen. XII, 6</span>.—Pl. <span dir=\"rtl\">כְּנַעֲנָאִין</span>, <a href=\"#\" data-headword=\"כְּנַעֲנָאָה\">כְּנַעֲנָאֵי</a>. Targ. Y. ib. <span class=\"citation\">Targ. Gen. X, 18</span>; a. fr.</div>","alt":[]},"12732":{"h":"כְּנַעֲנִי","r":"K00870","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>Canaanite</i>. <span class=\"citation\">Tosef. B. Kam. VIII, 19</span>. Mekh. Mishp., Nzikin, s. 7 (ref. to <span class=\"citation\">Ex. XXI, 26</span>) <span dir=\"rtl\">בכ׳ וכ׳</span> the text speaks of a Canaanite slave, opp. to <span dir=\"rtl\">עבד עברי</span>. <span class=\"citation\">Kidd. I, 3</span> <span dir=\"rtl\">עבד כ׳ נקנה וכ׳</span> a Canaanite slave is taken possession of &amp;c.; a. fr.—Pl. <a href=\"#\" data-headword=\"כְּנַעֲנִי\">כְּנַעֲנִים</a>. <span class=\"citation\">Tosef. B. Kam. IX, 10</span>. Mekh. l. c. s. 3 <span dir=\"rtl\">כדרך שהכ׳ וכ׳</span> as the Canaanite slaves go free. <span class=\"citation\">Sot. 35ᵇ</span> כ׳ שבח&quot;ל Canaanites outside of Palestine.</div><div class=\"sense\"><b>—2)</b> <i>Phœnician, merchant</i>. <span class=\"citation\">Sifré Deut. 306</span>; <span class=\"citation\">Yalk. ib. 942</span> (ref. to <span dir=\"rtl\">יערף</span>, <span class=\"citation\">Deut. XXXII, 2</span>) <span dir=\"rtl\">לשון כ׳ וכ׳</span> it is a merchant’s expression, f. i., a man says not to his neighbor, ‘change for me &amp;c.,’ but ‘break &amp;c.’ <span dir=\"rtl\">(ערוף</span>).</div>","alt":[]},"12733":{"h":"כָּנַף","r":"K00871","html":"<div class=\"sense\"> (b. h.) <i>to bend; to cover</i>.</div><div class=\"sense\"><b>Nif. נִכְנַף</b> <div class=\"sense\"><i>to be covered, hidden</i>. Pesik. Zachor, p. 29ᵃ, a. e., v. <a href=\"#\" data-headword=\"כָּנָף\">כָּנָף</a>.</div></div>","alt":[]},"12734":{"h":"כְּנַף I","r":"K00872","html":"<div class=\"sense\">, <i>to press, crowd; to gather</i>. <span class=\"citation\">Targ. Ps. XLI, 7</span> (v. <a href=\"#\" data-headword=\"כְּנַס\">כְּנַס</a>).—<span class=\"citation\">Taan. 23ᵇ</span> ניתי לִיכְנוֹף גבי הדדי Ms. M. (ed. <span dir=\"rtl\">נִיכְּנִיף הדדי</span>) let us go and crowd together (for prayer). <span class=\"citation\">Ab. Zar. 19ᵇ</span> <span dir=\"rtl\">כָּנוּף ואתי וכ׳</span> all the world crowded about him.—Part. pass. <a href=\"#\" data-headword=\"כְּנַף I\">כְּנִיף</a>. <span class=\"citation\">Snh. 29ᵇ</span> <span dir=\"rtl\">כְּנִיפֵי ויתבי</span> if they (before whom he made the admission, v. <a href=\"#\" data-headword=\"אוֹדִיתָא\">אוֹדִיתָא</a>) were assembled (for some other business), opp. to <span dir=\"rtl\">כּנּפִינְהוּ איהו</span> if he himself called them to a meeting.</div><div class=\"sense\"><b>Pa. כַּנֵּיף</b> <div class=\"sense\"><b>1)</b> <i>to collect, grab</i> (corresp. to <a href=\"#\" data-headword=\"גָּבַב\">גָּבַב</a>). <span class=\"citation\">Sabb. 73ᵇ</span> <span dir=\"rtl\">האי מאן דכ׳ וכ׳</span> he who grabs (skims with his palm) salt out of the salina. <span class=\"citation\">Bets. 33ᵇ</span> מחזי כמאן דמְכַנֵּיף וכ׳ Ms. M. (ed. <span dir=\"rtl\">מכניא</span>, corr. acc.) it looks as though he raked together for the next day.</div><div class=\"sense\"><b>—2)</b> <i>to assemble, call a meeting</i>. <span class=\"citation\">Targ. Y. I Deut. I, 1</span>.—Snh. l. c., v. supra. <span class=\"citation\">B. Kam. 113ᵃ</span> לדידכו כַּנְּפִינְהוּ Ms. M. (ed. v. <a href=\"#\" data-headword=\"כְּנוּפְיָא\">כְּנוּפְיָא</a>) have we assembled them for your individual benefit?—Part. pass. <span dir=\"rtl\">מְכַנַּף</span>. <span class=\"citation\">Ber. 58ᵇ</span> <span dir=\"rtl\">כמאה … דמְכַנְּפֵי</span> like one hundred stars … collected in one spot, opp. <span dir=\"rtl\">מבדרי</span>. <span class=\"citation\">Gitt. 20ᵃ</span>, v. infra.</div><div class=\"sense\"><b>—3)</b>  (corresp. to <a href=\"#\" data-headword=\"קָפַל I\">קָפַל</a>) <i>to fold, crease</i>. <span class=\"citation\">Sabb. 147ᵃ</span> <span dir=\"rtl\">אדעתא דלכַנּוּפֵי</span> with the intention of creasing.</div></div><div class=\"sense\"><b>Ithpa. אִתְכַּנַף</b> </div><div class=\"sense\"><b>Ithpe. אִתְכְּנִיף  אִיכְּנִיף</b> <div class=\"sense\"><b>1)</b> <i>to be assembled, to meet, join</i>. <span class=\"citation\">Targ. Cant. VIII, 7</span>.—<span class=\"citation\">Taan. 23ᵇ</span>, v. supra.</div><div class=\"sense\"><b>—2)</b> <i>to be compressed</i>. <span class=\"citation\">Gitt. 20ᵃ</span> <span dir=\"rtl\">כַּנּוּפֵי מִכְּנִיף</span> (ed. Rashi <span dir=\"rtl\">מְכַנַּף</span>), v. <a href=\"#\" data-headword=\"חֲרַץ\">חֲרַץ</a>.</div></div>","alt":[]},"12735":{"h":"כָּנָף","r":"K00873","html":"<div class=\"sense\"> (mostly) m.(b. h.;  [<i>bend</i>,] </div><div class=\"sense\"><b>1)</b> <i>wing, wing-feather.</i> <span class=\"citation\">Kel. XVII, 14</span> <span dir=\"rtl\">כְּנַף העוז</span> things made of feathers of the sea-eagle; a. e.—<i>Du.</i> <span dir=\"rtl\">כְּנָפַיִם</span>, pl. <span dir=\"rtl\">כְּנָפִים</span>, <span dir=\"rtl\">כַּנְפוֹת</span>. Ib. <span class=\"citation\">Toh. I, 2</span>. <span class=\"citation\">Ḥull. III, 4</span> <span dir=\"rtl\">נמרטו כנָפֶיהָ</span> if the wing-feathers are plucked out, v. <a href=\"#\" data-headword=\"נוֹצָה\">נוֹצָה</a>. <span class=\"citation\">Ib. 7</span> <span dir=\"rtl\">כל שיש לו ארבע כ׳ … וכְנָפָיו וכ׳ …</span> that (locust) which has four feet and four wings …, and whose wings cover the larger portion of its body (is clean); a. fr.</div><div class=\"sense\"><b>—2)</b> <i>border, lap</i>. <span class=\"citation\">Sifré Num. 115</span> <span dir=\"rtl\">מן הכ׳</span>, v. <a href=\"#\" data-headword=\"גְּדִילָה II\"><span dir=\"rtl\">גְּדִילָה</span> II</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מצות כ׳</span> the law concerning the borders of garments (<span class=\"citation\">Num. XV, 38</span>).—Pl. as ab. <span class=\"citation\">Lev. R. s. 18</span>; <span class=\"citation\">Koh. R. to XII, 3</span> (ref. to <span dir=\"rtl\">הראות</span> ib.) <span dir=\"rtl\">אלו כַּנְפֵי הריאה</span> those are the laps (extreme ends) of the lungs. <span class=\"citation\">Ḥull. 45ᵃ</span> <span dir=\"rtl\">עד כנפי ריאה התחתונה</span> to the borders of the lowest lung (of the animal suspended by its feet).—Euphem. for <i>a woman’s lap</i> (<i>pudenda</i>). <span class=\"citation\">Yeb. 4ᵃ</span>; <span class=\"citation\">49ᵃ</span> (expl. <span class=\"citation\">Deut. XXIII, 1</span>) <span dir=\"rtl\">כ׳ שראה אביו</span> the lap which his father has seen, i.e. any woman with whom his father has had sexual connection.</div><div class=\"sense\"><b>—3)</b> <i>cover</i>. Pesik. Zakh., p. 29ᵃ; <span class=\"citation\">Pesik. R. s. 12</span>; Tanḥ. Ki Thetsé 11 (ref. to <span dir=\"rtl\">יִכָּנֵף</span>, <span class=\"citation\">Is. XXX, 20</span>) … <span dir=\"rtl\">כל זמן כ׳ מכסה וכ׳</span></div><div class=\"sense\"><b>—4)</b>  (<i>pl.</i>) <i>hands, arms</i>; (of animals) <i>shoulders, fore-legs</i>. <span class=\"citation\">Pes. VII, 11</span> (<span class=\"citation\">84ᵃ</span>) <span dir=\"rtl\">ראשי כ׳</span> the cartilaginous tops of the fore-legs. <span class=\"citation\">Y. Naz. VI, 55ᶜ</span> bot. (ref. to <span class=\"citation\">Num. VI, 19</span>) <span dir=\"rtl\">בין שיש לו כ׳ וכ׳</span> whether or not he has hands (to receive the offerings; Bab. <span class=\"citation\">Naz. 46ᵇ</span> <span dir=\"rtl\">כַּפַּיִם</span>). <span class=\"citation\">Tosef. Dem. II, 11</span> <span dir=\"rtl\">מקבלין לכ׳</span> we accept a <i>ḥaber</i> (v. <a href=\"#\" data-headword=\"חָבֵר\">חָבֵר</a>), if he promises to observe levitical cleanness of hands; <span class=\"citation\">Bekh. 30ᵇ</span>. <span class=\"citation\">Y. Dem. II, 23ᵃ</span> top <span dir=\"rtl\">מקריבין לכ׳</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כ׳ מדפות וכ׳</span> the laws concerning hands, &amp;c., v. <a href=\"#\" data-headword=\"מִדָּף\">מִדָּף</a>.—<span dir=\"rtl\">אלישע בעל כ׳</span> one Elisha, a <i>ḥaber</i> observing cleanness of hands. Y. Ber. I, 4ᶜ bot.; <span class=\"citation\">Sabb. 49ᵃ</span>; <span class=\"citation\">130ᵃ</span> (legendary origin of the surname).—<span class=\"citation\">Lev. R. s. 32</span> <span dir=\"rtl\">בעל כ׳</span> the winged angel.</div><div class=\"sense\"><b>—5)</b> <i>curved attachments, handles</i> &amp;c. <span class=\"citation\">Kel. XI, 6</span>; Tosef. ib. <span class=\"citation\">B. Mets. I, 7</span>, v. <a href=\"#\" data-headword=\"סִימְפּוֹנְיָא\">סִימְפּוֹנְיָא</a>. <span class=\"citation\">Kel. XIV, 4</span> <span dir=\"rtl\">הכ׳ המקבלות וכ׳</span> the curves on the harness for holding the reins; <span class=\"citation\">ib. 5</span> <span dir=\"rtl\">כ׳ העשוים לנוי</span> for ornament.—Trnsf. <span dir=\"rtl\">כנפי השכינה</span> or <a href=\"#\" data-headword=\"כ׳\">כ׳</a> <i>divine protection</i>; <span dir=\"rtl\">תחת כ׳ הש׳</span> under the wings of divine Majesty, i.e. <i>belief and faith in God, Jewish religion</i>. <span class=\"citation\">Lev. R. s. 2</span> <span dir=\"rtl\">פושטין … להכניסו תחת כ׳ הש׳</span> we must reach out a hand to him (the proselyte) in order to take him in &amp;c. Mekh. B’shall., Amalek, s. 2 <span dir=\"rtl\">לאבד … מתחת כְּנָפֶיךָ</span> to lead thy people away from the faith in thee.—<span class=\"citation\">Ruth R. to II, 12</span>; a. fr.</div>","alt":[]},"12736":{"h":"כְּנַף II","r":"K00874","html":"<div class=\"sense\"><b>1)</b> <i>wing, lap</i>. <span class=\"citation\">Targ. I Kings VI, 24</span>; a. fr.—<span class=\"citation\">Targ. Zech. VIII, 23</span>; a. fr.—<span class=\"citation\">B. Mets. 85ᵃ</span> <span dir=\"rtl\">בכַנְפֵיה דרבו</span> in the lap of Rabbi’s garment. <span class=\"citation\">Sabb. 5ᵃ</span> <span dir=\"rtl\">פשיט כנפיה וכ׳</span> he spread the lap of his garment and received it. <span class=\"citation\">B. Bath. 12ᵇ</span> <span dir=\"rtl\">בכנפיה דאבוה</span> on her father’s lap. <span class=\"citation\">Ib. 58ᵃ</span> <span dir=\"rtl\">בכַנְפָהּ דשרה</span> in Sarah’s lap; a. fr.—[Euphem. <span class=\"citation\">Targ. Deut. XXIII, 1</span>, v. preced.]—Trnsf. <i>protection</i>. Targ. II Esth. IX, 14.—Pl. <span dir=\"rtl\">כַּנְפִין</span>, <span dir=\"rtl\">כַּנְפַיָּא</span>, <span dir=\"rtl\">כַּנְפֵי</span>. Ib. <span class=\"citation\">Targ. Ez. XVII, 3</span>. <span class=\"citation\">Targ. O. Num. XV, 38</span>; a. fr.—[<span dir=\"rtl\">כַּנְפָתָא</span>, constr. <a href=\"#\" data-headword=\"כְּנַף II\">כַּנְפָת</a>. Targ. Y. II ib., emend. by Bxt., ed. <span dir=\"rtl\">צָנְפַת</span>.]</div><div class=\"sense\"><b>—2)</b>  <span dir=\"rtl\">בַּת כַּנְפָא</span> name of an unclean <i>bird</i>. <span class=\"citation\">Targ. O. Deut. XIV, 13</span> (h. text <a href=\"#\" data-headword=\"ראי\">הראה</a>).</div>","alt":["כַּנְפָא"]},"12737":{"h":"כִּנָּר","r":"K00875","html":"<div class=\"sense\"> m., pl. <span dir=\"rtl\">כִּנָּרִים</span>, <a href=\"#\" data-headword=\"כָּבֵד I\">כִּי׳</a> = <a href=\"#\" data-headword=\"כִּנָּרָא\">next w.</a> <span class=\"citation\">Y. Meg. I, 70ᵃ</span> bot., v. <a href=\"#\" data-headword=\"כִּנָּרָא\">next w.</a></div>","alt":[]},"12738":{"h":"כִּנָּרָא","r":"K00876","html":"<p class=\"morphology\">m.</p><div class=\"sense\">name of <i>a shrubby tree, Christ’s-thorn</i> or <i>lote</i> (Greek adapt. κόνναρος, v. Löw, Pfl., p. 283 sq.). <span class=\"citation\">Meg. 6ᵃ</span> Kinnereth is Ginnosar (Gennesareth) and why is it called Kinnereth <span dir=\"rtl\">משום דמתיקי פירהא ככ׳</span> Ar. (v. Rabb. D. S. note 3) because its fruits are as sweet as those of the Kinnara; [Var. quot. in Ar. <span dir=\"rtl\">כי קלא דכ׳</span> as sweet as the sound of the <i>lute</i>; Ms. O. <span dir=\"rtl\">כקוליא דכ׳</span>]. Y. ib. I, 70ᵃ bot. (hebr.) <span dir=\"rtl\">שהן מגדלות כִּינָּרִים</span> because they produce <i>Kinnars</i>. <span class=\"citation\">Pes. 111ᵇ</span> טולא דכינורא Ms. M. (ed. <span dir=\"rtl\">דכנדא</span>, Ms. M. 2 <span dir=\"rtl\">דכנארא</span>; Ms. O. <span dir=\"rtl\">דכנרא</span>, v. Rabb. D. S. a. l. note) the shade of a <i>K</i>. <span class=\"citation\">B. Bath. 48ᵇ</span> תלא לפאפי אכי׳ Tabi suspended P. on a Kinnara (to force him to sell a field of his; for oth. opin., v. comment.).—Pl. <span dir=\"rtl\">כִּינָּרֵי</span>, <a href=\"#\" data-headword=\"כָּבֵד I\">כִּי׳</a>. <span class=\"citation\">Ber. 40ᵇ</span> רימין כ׳ Ar. a. Ms. F. (v. Rabb. D. S. a. l. note 30; ed. <span dir=\"rtl\">כנדי</span>) <i>Rimin</i> (<span class=\"citation\">Dem. I, 1</span>) means <i>K</i>.</div>","alt":["כִּי׳ I"]},"12739":{"h":"כִּנְּרָא","r":"K00877","html":"<div class=\"sense\">, <i>lute</i>, v. <a href=\"#\" data-headword=\"כִּנּוֹרָא\">כִּנּוֹרָא</a>.</div>","alt":["כִּנָּרָא II"]},"12740":{"h":"כנריות","r":"K00878","html":"<div class=\"sense\">, <span class=\"citation\">Gen. R. s. 45</span> Ar., v. <a href=\"#\" data-headword=\"בַּנְּרִיּוֹת\">בַּנְּרִיּוֹת</a></div>","alt":[]},"12741":{"h":"כִּנֶּרֶת","r":"K00879","html":"<div class=\"sense\"> (b. h.) pr. n. <i>Kinnereth</i> (Gennesareth), name of a town and of a lake in Galilee. <span class=\"citation\">Meg. 6ᵃ</span>; Y. ib. I, 70ᵃ bot., v. <a href=\"#\" data-headword=\"כִּנָּרָא\">כִּנָּרָא</a>.</div>","alt":["כִּינֶּ׳"]},"12742":{"h":"כָּנַשׁ","r":"K00880","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"כָּנַס\">כָּנַס</a>, <i>Hithpa.</i> <a href=\"#\" data-headword=\"כָּבַשׁ\">הִתְכַּנֵּשׁ</a>. <span class=\"citation\">Cant. R. to I, 3</span> <span dir=\"rtl\">מִתְכַּנְּשִׁין</span>, v. <a href=\"#\" data-headword=\"כָּנַס\">כָּנַס</a>.</div>","alt":[]},"12743":{"h":"כְּנַשׁ","r":"K00881","html":"<div class=\"sense\">(v. <a href=\"#\" data-headword=\"כָּנַשׁ\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>to gather, collect; to gather in</i>. <span class=\"citation\">Targ. Ex. XXXV, 1</span> (ed. Amst. <a href=\"#\" data-headword=\"כְּנַשׁ\">כְּנַשׁ</a>). <span class=\"citation\">Targ. Koh. II, 8</span>. <span class=\"citation\">Targ. Is. XXIV, 22</span>; a. fr.—Y. Maas. Sh. IV, end, 55ᶜ <span dir=\"rtl\">לית את כ׳</span> thou shalt not harvest; a. fr.</div><div class=\"sense\"><b>—2)</b>  (cmp. <span dir=\"rtl\">גבב</span>) <i>to rake together, to sweep</i>. <span class=\"citation\">B. Mets. 85ᵃ</span> קכַנְשָׁא ביתא Ms. M. (v. Rabb. D. S. a. l. note) was sweeping the house. <span class=\"citation\">Ḥull. 60ᵃ</span> <span dir=\"rtl\">אתא … כַּנְשֵׁיה לימא</span> a blast of wind came and swept it (the store of provision) into the sea.</div><div class=\"sense\"><b>Pa. כַּנֵּישׁ</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"כָּנַשׁ\">same</a>. <span class=\"citation\">Targ. Mic. II, 12</span>; a. e.—<span class=\"citation\">Lev. R. s. 25</span> <span dir=\"rtl\">היא מְכַנְּשָׁא להון</span> she calls the chickens together. Y. Ber. IX, end 14ᵈ <span dir=\"rtl\">דמְכַנְּשִׁין</span>, v. <a href=\"#\" data-headword=\"בְּדַר\">בְּדַר</a>; a. e.</div></div><div class=\"sense\"><b>Af. אַכְנֵישׁ</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"כָּנַשׁ\">same</a>. <span class=\"citation\">Targ. Ez. XI, 17</span> (ed. Lag. <span dir=\"rtl\">אִיכְנֵישׁ</span> <i>Pe</i>.); a. e.</div></div><div class=\"sense\"><b>Ithpa. אִתְכַּנַּשׁ</b> </div><div class=\"sense\"><b>Ithpe. אִתְכְּנִישׁ  אִתְכְּנַשׁ</b> <div class=\"sense\"><i>to be gathered, to be called in; to retire</i>. <span class=\"citation\">Targ. Jud. XII, 1</span> (ed. Wil. … <span dir=\"rtl\">שׂ</span>) <span class=\"citation\">Targ. Gen. XXV, 8</span>. <span class=\"citation\">Targ. Jer. XLVII, 6</span>; a. fr.—<span class=\"citation\">Koh. R. to IX, 10</span> <span dir=\"rtl\">אִתְכַּנְּשׁוּן כל קרייתא וכ׳</span> all the towns (people) met to mourn for him. Tanḥ. Ki Thetsé 4 <span dir=\"rtl\">טב ליה לצדיקא דאי׳ בשלם</span> (not <span dir=\"rtl\">לצדיקיא</span>) it is better for the righteous man to be gathered in (die) in peace; Pesik. Zakh., p. 23ᵃ <span dir=\"rtl\">טב ליה מִתְכְּנַשׁ בשלם</span>; <span class=\"citation\">Yalk. Ps. 868</span> <span dir=\"rtl\">טב ליה לההיא סבא דמִתְכְּנִישׁ וכ׳</span>.</div></div>","alt":[]},"12744":{"h":"כִּנְשָׁא","r":"K00882","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּנַשׁ\">preced.</a>) <i>gathering, people</i>.—Pl. <a href=\"#\" data-headword=\"כִּבְשָׁן\">כִּנְשָׁן</a>, <a href=\"#\" data-headword=\"כָּבֵד I\">כִּי׳</a>. <span class=\"citation\">Targ. O. Gen. XVII, 16</span> (Y. <span dir=\"rtl\">כִּנְשִׁין</span> m.; h. text <span dir=\"rtl\">גוים</span>).</div>","alt":["כִּי׳"]},"12745":{"h":"כְּנִשְׁתָּא","r":"K00883","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּנִישָׁא\">כְּנִישְׁתָּא</a></div>","alt":[]},"12746":{"h":"כַּנְתָא","r":"K00884","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּנַן\">כנן</a>) <i>winding, convolution</i>, </div><div class=\"sense\"><b>1)</b>  (sub. <span dir=\"rtl\">דמעיא</span>) <i>ileum</i>, the third division of the small intestines. <span class=\"citation\">Ḥull. 48ᵇ</span>; <span class=\"citation\">113ᵃ</span>, v. <a href=\"#\" data-headword=\"הֲדוּרָא\">הֲדוּרָא</a>. <span class=\"citation\">Gitt. 69ᵃ</span> <span dir=\"rtl\">כ׳ פטירתא</span> the ileum of a first-born.—<span class=\"citation\">Yalk. Koh. 976</span> (counting ten stations of the digestive process) <span dir=\"rtl\">מכרוכא עבה לכְנַת מעיא</span> from the large winding (jejunum) to the ileum (corresp. to <span dir=\"rtl\"><a href=\"#\" data-headword=\"סני\">סני</a>(<a href=\"#\" data-headword=\"א\">א</a>) <a href=\"#\" data-headword=\"דִּיבֵי\">דיבי</a></span>, <span class=\"citation\">Lev. R. s. 3</span>, a. <span class=\"citation\">Koh. R. to VII, 19</span>). [Koh. R. l. c. <span dir=\"rtl\">כנת מעיא</span> some ed., read <span dir=\"rtl\">בנת</span>.]</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"כֶּרֶךְ\">כֶּרֶךְ</a>, <a href=\"#\" data-headword=\"אִמְבּוּרְקְלוֹן\">אִמְבּוּרְקְלוֹן</a>) <i>wrapper</i> of loosely woven matting. <span class=\"citation\">Succ. 20ᵇ</span> חזו לכ׳ דפירי Ar. (ed. <span dir=\"rtl\">לכינ׳</span>, Ms. M. <span dir=\"rtl\">לבנ׳</span>; v. Rabb. D. S. a. l. note) are fit for baling fruits. <span class=\"citation\">Keth. 105ᵇ</span> <span dir=\"rtl\">כ׳ דפירי</span> a bale of fruits, <span dir=\"rtl\">כ׳ דגלדני</span> of small fish.</div>","alt":[]},"12747":{"h":"כנתי","r":"K00885","html":"<div class=\"sense\">, a word in a charm formula. <span class=\"citation\">Yoma 84ᵃ</span> <span dir=\"rtl\">כ׳ כ׳ קלירוס</span> (Ms. M. <span dir=\"rtl\">קנגי קנדי קליריס</span>).</div>","alt":[]},"12748":{"h":"כס","r":"K00886","html":"<div class=\"sense\">, <span class=\"citation\">Num. R. s. 1</span> <span dir=\"rtl\">כס נאה</span>, read <a href=\"#\" data-headword=\"אַכְסַנְיָא\">אַכְסַנְיָא</a>, v. Tanḥ. B’midb. 2.—<span class=\"citation\">Sabb. 67ᵃ</span>, v. <a href=\"#\" data-headword=\"כַּסְכְּסַיָּיה\">כַּסְכְּסַיָּיה</a>.</div>","alt":[]},"12749":{"h":"כָּס","r":"K00887","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כָּסַס\">כָּסַס</a>, <a href=\"#\" data-headword=\"כְּסַס\">כְּסַס</a> a. <a href=\"#\" data-headword=\"נְכַס\"><a href=\"#\" data-headword=\"נְכַס\">נְכַס</a>.</a></div>","alt":["כַּס"]},"12750":{"h":"כֹּס","r":"K00888","html":"<div class=\"sense\">, <i>cup</i>, v. <a href=\"#\" data-headword=\"כּוֹס I\">כּוֹס</a>, <a href=\"#\" data-headword=\"כַּסָּא I\"><a href=\"#\" data-headword=\"כַּסָּא I\">כַּסָּא</a>.</a></div>","alt":["כָּס"]},"12751":{"h":"כְּסָא I","r":"K00889","html":"<div class=\"sense\"><i>to cover</i>, v. <span dir=\"rtl\">כְּסֵי II</span>.</div>","alt":[]},"12752":{"h":"כְּסָא II","r":"K00890","html":"<div class=\"sense\"><i>to reprehend</i>, v. <a href=\"#\" data-headword=\"כְּסַס\">כְּסַס</a> a. <a href=\"#\" data-headword=\"כְּסַן\"><a href=\"#\" data-headword=\"כְּסַן\">כְּסַן</a>.</a></div>","alt":[]},"12753":{"h":"כַּסָּא I","r":"K00891","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , <i>cup, calyx</i>. <span class=\"citation\">Targ. Gen. XL, 11</span>; a. fr.—<span class=\"citation\">Targ. I Kings VII, 26</span>; a. fr.—<span class=\"citation\">Targ. II Sam. XII, 3</span> <span dir=\"rtl\">כָּסֵיה</span> ed. Lag. (oth. <span dir=\"rtl\">כּוֹסֵיה</span>).—<span class=\"citation\">Ber. 28ᵃ</span>, v. <a href=\"#\" data-headword=\"יְקָר ²\">יְקָרָא</a>. <span class=\"citation\">Ib. 51ᵇ</span>, v. <a href=\"#\" data-headword=\"בִּרְכְתָא\">בִּרְכְתָא</a>. <span class=\"citation\">Y. Ḥag. II, 78ᵃ</span> bot., v. <a href=\"#\" data-headword=\"*בִּשְׂרוּתָה\">בִּשְׂרוּתָה</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כ׳ דקיסא וכ׳</span> out of a cup of sharp-edged glass drink quickly (ere it cut your lip); [Y. Bets. II, 61ᶜ top <a href=\"#\" data-headword=\"סַמָּא I\">סמא</a>; Y. Maas. Sh. V, 56ᶜ top <a href=\"#\" data-headword=\"סְבָא\">סבא</a>, Meïri to <span class=\"citation\">Bets. 20ᵇ</span> <a href=\"#\" data-headword=\"סָסָא\">ססא</a>]; a. fr.—Pl. <a href=\"#\" data-headword=\"כְּסַן\">כַּסִּין</a>, <span dir=\"rtl\">כַּסַּיָּיא</span>, <a href=\"#\" data-headword=\"כְּסֵי ²\">כַּסֵּי</a>, <a href=\"#\" data-headword=\"כָּס\">כָּס׳</a>. <span class=\"citation\">Targ. Jer. XXXV, 5</span>.—<span class=\"citation\">Y. Nidd. II, end, 50ᵇ</span> <span dir=\"rtl\">כ׳ טיברייאי</span> (not … <span dir=\"rtl\">אה</span>) Tiberian glass cups (transparent). <span class=\"citation\">Pes. 110ᵃ</span>; a. fr.—<span dir=\"rtl\">(<a href=\"#\" data-headword=\"בִּית\">בּית</a>) <span dir=\"rtl\">בּי כַּסַּיָּא</span></span> = h. <span dir=\"rtl\">בית הכוסות</span>, v. <a href=\"#\" data-headword=\"כּוֹס I\">כּוֹס</a>. <span class=\"citation\">Lev. R. s. 3</span>; [<span class=\"citation\">Koh. R. to VII, 19</span> (of the human body) <span dir=\"rtl\">בית כסא</span>, by mistake borrowed from Lev. R. l. c.; v. <span class=\"citation\">Yalk. Koh. 976</span>].</div>","alt":["כָּסָא","כָּס"]},"12754":{"h":"כַּסָּא II","r":"K00892","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּסַס\">כְּסַס</a>) </div><div class=\"sense\"><b>1)</b> <i>fodder</i>, v. <a href=\"#\" data-headword=\"כִּיסְתָא II\"><span dir=\"rtl\">כִּיסְתָא</span> II</a>.</div><div class=\"sense\"><b>—2)</b> <i>hash</i>. <span dir=\"rtl\">כ׳ דהרסנא</span>, v. <a href=\"#\" data-headword=\"הַרְסָנָא\">הַרְסָנָא</a>.—Pl. <a href=\"#\" data-headword=\"כְּסֵי ²\">כַּסֵּי</a>. <span class=\"citation\">Ab. Zar. 38ᵃ</span> ed.</div>","alt":[]},"12755":{"h":"כִּסֵּא","r":"K00893","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>bolsters, chair, throne</i>. <span class=\"citation\">Tosef. Bets. III, 11</span>. <span class=\"citation\">Ib. 17</span> <span dir=\"rtl\">אין יוצאין בכִּסֵּה</span> ed. Zuck. (Var. <span dir=\"rtl\">בכסא</span>) you must not be carried out on a sedan chair (on Holy Days); <span class=\"citation\">Bets. 25ᵇ</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כ׳ מה אתון ביה</span> what is your opinion about carrying a person on a chair &amp;c.?—<span class=\"citation\">Kel. XXII, 3</span> <span dir=\"rtl\">הכ׳ שלפני קתידרא</span> the bolster in front of the cathedra (a kind of footstool). <span class=\"citation\">Ib. 4</span>, v. <a href=\"#\" data-headword=\"חִפּוּי\">חִפּוּי</a>; a. fr.—<span dir=\"rtl\">כ׳ הכבוד</span> the throne of Divine Majesty. <span class=\"citation\">Ḥag. 13ᵃ</span>; a. fr.—<span dir=\"rtl\">כ׳ הדין</span> the throne of Divine judgment; <span dir=\"rtl\">כ׳ רחמים</span> mercy-seat. <span class=\"citation\">Lev. R. s. 29</span> אני עומד מכ׳ הדין וכ׳ I rise from the throne of judgment and seat myself on the throne of mercy; a. fr.—Euphem. <span dir=\"rtl\">בית הכ׳</span> <i>privy</i>. <span class=\"citation\">Tam. I, 1</span> <span dir=\"rtl\">בית הכ׳ של כבוד</span> a chaste privy. <span class=\"citation\">Ber. 25ᵃ</span>; a. fr.—Pl. <span dir=\"rtl\">כִּסָּאוֹת</span>, <span dir=\"rtl\">כִּסָּיוֹת</span>, <a href=\"#\" data-headword=\"כָּבֵד I\">כִּי׳</a>; with suff. <span dir=\"rtl\">כִּסְאֵי־</span>. <span class=\"citation\">Ex. R. s. 31</span>; a. fr.—<span class=\"citation\">Tosef. Kel. B. Mets. X, 6</span> <span dir=\"rtl\">הכיסיות שבבימה</span> (not <span dir=\"rtl\">הכו׳</span>) the (stationary) seats in public courts. <span class=\"citation\">Pesik. R. s. 23-24</span> <span dir=\"rtl\">עמדו מכִּסְאֵיהֶם</span> arose from their thrones.—[<span class=\"citation\">Zab. IV, 4</span> <span dir=\"rtl\">כסאות</span>, v. <a href=\"#\" data-headword=\"כֶּסֶת\">כֶּסֶת</a>.]</div>","alt":[]},"12756":{"h":"כֶּסֶא","r":"K00894","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (כָּסָה I) <i>mark, distinction; marked, appointed time</i>. <span class=\"citation\">Lev. R. s. 29</span>; Pesik. Baḥod., p. 153ᵃ (ref. to <span class=\"citation\">Ps. LXXXI, 4</span>) <span dir=\"rtl\">וכי כל החדשים אינן חדש אלא בכ׳</span> ‘on the New Moon’, are all other new moons no New Moons (festive days)?; but (therefore is added) <i>bakkesé</i>, on the distinguished (month), v. <a href=\"#\" data-headword=\"כסי\"><span dir=\"rtl\">כָּסָה</span> I</a>. [<span class=\"citation\">Pirké d’R. El. ch. VII</span>, end, a. <span class=\"citation\">Bets. 16ᵃ</span> our w. is taken in the sense of <i>cover</i>.]</div>","alt":["כֶּסֶה"]},"12757":{"h":"כְּסָאן","r":"K00895","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּסָן\">כְּסָן</a></div>","alt":[]},"12758":{"h":"כְּסָאנִין","r":"K00896","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּיסָנִין\">כִּיסָנִין</a>, <a href=\"#\" data-headword=\"כִּיסְנִין\"><a href=\"#\" data-headword=\"כִּיסְנִין\">כִּיסְנִין</a>.</a></div>","alt":[]},"12759":{"h":"כָּסְבַּר","r":"K00897","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כּוּסְבַּר\">כּוּסְבַּר</a></div>","alt":[]},"12760":{"h":"כַּסְדָּאָה","r":"K00898","html":"<div class=\"sense\">, v. <span dir=\"rtl\">כַּשְׂדָּ׳</span></div>","alt":[]},"12761":{"h":"כִּסֵּה","r":"K00899","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּסֵּא\">כִּסֵּא</a></div>","alt":[]},"12762":{"h":"כֶּסֶה","r":"K00900","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כֶּסֶא\">כֶּסֶא</a></div>","alt":[]},"12763":{"h":"כָּסָה","r":"K00901","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כסי\">כסי</a></div>","alt":[]},"12764":{"h":"כְּסוּ","r":"K00902","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּסוּתָא\">כּסוּתָא</a></div>","alt":[]},"12765":{"h":"כִּסּוּחַ","r":"K00903","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּיסְתָא II\">כִּיסּ׳</a></div>","alt":[]},"12766":{"h":"כְּסוּי","r":"K00904","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּסוּתָא\">כְּסוּתָא</a></div>","alt":[]},"12767":{"h":"כִּסּוּי","r":"K00905","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"כִּיסְתָא II\">כִּיסּ׳</a>.</div>","alt":["כִּסּוּיָא"]},"12768":{"h":"כָּסוּל","r":"K00906","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"כֶּסֶל\">כֶּסֶל</a>) <i>an animal with a deformed hip</i>. <span class=\"citation\">Bekh. VI, 7</span> (<span class=\"citation\">40ᵃ</span>) <span dir=\"rtl\">כ׳ שאחת מירכותיו גבוהה</span> (Talm. ed. <span dir=\"rtl\">גבוהות</span>, corr. acc.) a <i>kasul</i> is one whose one hip is higher than the other. Ib. 40ᵃ <span dir=\"rtl\">כ׳ שרגלו אחד וכ׳</span> a <i>k</i>. is he whose one foot is seated in the loin and the other over the loin; Tosef. ib. IV, 10 <span dir=\"rtl\">איזהו פסול</span> (corr. acc.).</div>","alt":[]},"12769":{"h":"כְּסוּסְטָא","r":"K00907","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּסִיסְטָא\">כְּסִיסְטָא</a></div>","alt":[]},"12770":{"h":"כְּסוּסְטְרָא","r":"K00908","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>balcony</i>, v. <a href=\"#\" data-headword=\"בְּצוֹצְרָה\">בְּצוֹצְרָה</a> a. <a href=\"#\" data-headword=\"גְּזוּזְטְרָא\"><a href=\"#\" data-headword=\"גְּזוּזְטְרָא\">גְּזוֹזְטְרָא</a>.</a></div>","alt":[]},"12771":{"h":"כִּסּוּפָא","r":"K00909","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּיסְתָא II\">כִּיסּ׳</a></div>","alt":[]},"12772":{"h":"כסוריא","r":"K00910","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֶכְסוֹרִיָּה\">אֶכְסוֹרִיָּה</a></div>","alt":[]},"12773":{"h":"כְּסוּת","r":"K00911","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>cover, clothing</i>. <span class=\"citation\">B. Bath. 9ᵃ</span> <span dir=\"rtl\">אין בודקין לכ׳</span> we must not investigate in the case of a poor man asking for clothes; <span class=\"citation\">Y. Peah VIII, 21ᵃ</span>, v. <a href=\"#\" data-headword=\"דִּקְדֵּק\">דִּקְדֵּק</a>. <span class=\"citation\">Tam. I, 1</span> <span dir=\"rtl\">ומתכסין בכ׳ עצמן</span> and covered themselves with their own (private) garments; a. fr.—[Y. Ḥag. II, end, 78ᶜ <span dir=\"rtl\">ואפי׳ כ׳</span>, read <a href=\"#\" data-headword=\"כָּפוּת\">כָּפוּת</a>, v. <a href=\"#\" data-headword=\"יָבַל I\">יָבַל</a>.]</div>","alt":[]},"12774":{"h":"כְּסוּתָא","r":"K00912","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <span class=\"citation\">Targ. O. Ex. XXII, 8</span> <span dir=\"rtl\">כסו</span> ed. Berl. (oth. ed. a. Y. <a href=\"#\" data-headword=\"כְּסוּי\">כּסוּי</a> <i>m</i>.). Ib. 25; a. fr.</div>","alt":["כְּסוּ"]},"12775":{"h":"כָּסַח","r":"K00913","html":"<div class=\"sense\"><i>to cut down, clear</i> (of thorns, bushes &amp;c.); <i>to trim</i>. <span class=\"citation\">Cant. R. to I, 1</span>; <span class=\"citation\">Gen. R. s. 12</span>; (Koh. R. to II, 12 כיסח <i>Pi.</i>). <span class=\"citation\">Gen. R. s. 49</span> <span dir=\"rtl\">למגל כּוֹסֶחֶת וכ׳</span> like a scythe cutting thorns and not being satisfied &amp;c.; a. fr.—Part. pass. <a href=\"#\" data-headword=\"כִּסּוּחַ\">כָּסוּחַ</a>, pl. <span dir=\"rtl\">כְּסוּחִים</span>, <span dir=\"rtl\">כְּסוּחִין</span>. <span class=\"citation\">Y. Maasr. III, 50ᵈ</span> bot. <span dir=\"rtl\">קוצין כ׳ כָּסַחְתִּי</span> (not <span dir=\"rtl\">כסיחין</span>) I cut mowed thorns, i.e. I only put to death doomed culprits; Pesik. B’shall., p. 92ᵃ <span dir=\"rtl\">כוסים כוסחים</span> (corr. acc.), v. <a href=\"#\" data-headword=\"*כּוֹס II\"><span dir=\"rtl\">כּוֹס</span> II</a>.</div><div class=\"sense\"><b>Pi. כִּיסֵּחַ</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"כְּסוּתָא\">same</a>. <span class=\"citation\">Kil. II, 5</span> <span dir=\"rtl\">אם נכש או כ׳</span> if he weeded or cut. <span class=\"citation\">Shebi. II, 10</span> <span dir=\"rtl\">אין מְכַסְּחִין</span> you must not cut (trim) rice plants (in the Sabbath year). Y. Shek. V, beg. 48ᶜ <span dir=\"rtl\">הראשונים … כִּיסְּחוּ וכ׳</span> our predecessors sowed …, cleared …, yet we have nothing to eat, i.e. they did their utmost for the Law, but we do not profit by their labors. Sifra B’ḥuck. Par. 2, ch. V <span dir=\"rtl\">כיסת</span>, <a href=\"#\" data-headword=\"כסי ²\">כיסה</a> ed. Weiss (corr. acc.); a. e.</div></div>","alt":[]},"12776":{"h":"כְּסַח","r":"K00914","html":"<div class=\"sense\"><span class=\"citation\">Targ. O. Lev. XXV, 3</span>, sq.; a. e.—<span class=\"citation\">Snh. 26ᵃ</span>. [<span class=\"citation\">Y. Sabb. VI, end, 8ᵈ</span> <span dir=\"rtl\">קריב למכסח</span>, v. <a href=\"#\" data-headword=\"מוֹכֵס ²\">מוֹכְסָא</a>.]</div><div class=\"sense\"><b>Pa. כַּסֵּחַ</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"כָּסַח\">same</a>. <span class=\"citation\">Targ. Ps. LXXX, 13</span>.</div></div>","alt":[]},"12777":{"h":"כסי","r":"K00915","html":"<div class=\"sense\"> (cmp. <span dir=\"rtl\">כסח</span>) <i>to make incisions, mark, count.</i> <i> Part. pass</i>. <a href=\"#\" data-headword=\"כְּסוּי\">כָּסוּי</a> <i>marked, distinguished</i>. <span class=\"citation\">Pesik. R. s. 39</span> (ref. to <span class=\"citation\">Ps. LXXXI, 4</span>, v. <a href=\"#\" data-headword=\"כֶּסֶא\">כֶּסֶא</a>) <span dir=\"rtl\">מהו בכסא בחדש שהוא כ׳</span> (not <a href=\"#\" data-headword=\"כִּיסּוּי\">כיסוי</a>) what is <i>bakkesé?</i> In the month which is marked (v. infra).</div><div class=\"sense\"><b>Nif. נִכְסֶה</b> </div><div class=\"sense\"><b>Nithpa. נִתְכַּסֶּה</b> <div class=\"sense\"><i>to be marked, distinguished</i>. <span class=\"citation\">Lev. R. s. 29</span> (ref. to Ps. l. c.) <span dir=\"rtl\">וכל החדשים אינן נִכְסִין אלא ליום חגנו</span> are all other months (or New Moon Days) not marked?—But (it must be marked by) ‘a festive day’; [read:] <span dir=\"rtl\">חגו בפני עצמו והלא ניסן חדש נִכְסֶה ויש לו חג</span>: (Ar. … <span dir=\"rtl\">חדש ונתכסה</span>) but is not Nisan a marked month with a festival? (Answ.) Its festival is separate from it (not coinciding with the New Moon Day); <span dir=\"rtl\">אלא איזהו חדש נ׳ ויש לו חג וכ׳</span> but what month is there that is marked and has a festival, and that on the same day?; Pesik. Baḥod., p. 153ᵃ</div></div>","alt":["כָּסָה I"]},"12778":{"h":"כְּסֵי","r":"K00916","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּסַן\">כְּסַן</a></div>","alt":["כְּסָא"]},"12779":{"h":"כסי ²","r":"K00917","html":"<div class=\"sense\"> (b. h.) <i>to cover</i>.—Part. pass. <a href=\"#\" data-headword=\"כְּסוּי\">כָּסוּי</a>, f. <span dir=\"rtl\">כְּסוּיָה</span>; pl. <span dir=\"rtl\">כְּסוּיִים</span>, <span dir=\"rtl\">כְּסוּיִין</span>; <span dir=\"rtl\">כְּסוּיוֹת</span>. <span class=\"citation\">Gen. R. s. 52</span> <span dir=\"rtl\">אתם כִּסִּיתֶם … כְּסוּי עינים</span> you have concealed from me the sight (of truth), therefore the son that you will raise will be of covered eyes (blind); <span class=\"citation\">Yalk. Gen. 91</span> <a href=\"#\" data-headword=\"כְּסוּת\">כסות</a> (corr. acc.); <span class=\"citation\">B. Kam. 93ᵃ</span> <span dir=\"rtl\">הואיל וכִיסִּית … בנים כְּסוּיֵי עיניים</span> (v. Rabb. D. S. a. l. note). <span class=\"citation\">Y. Ter. VIII, 45ᵈ</span> <span dir=\"rtl\">הכְּסוּיִין</span> (not <span dir=\"rtl\">הכיסוין</span>) the covered liquids.</div><div class=\"sense\"><b>Pi. כִּיסָּה  כִּסָּה</b> <div class=\"sense\"><i>to cover, hide</i>. <span class=\"citation\">Ḥull. VI, 4</span> … <span dir=\"rtl\">שחט ולא כ׳ לכַסּוֹת</span> if one slaughters and fails to cover the blood, and another person sees it, he is bound to cover it. <span class=\"citation\">Pes. 119ᵃ</span> (ref. to <span class=\"citation\">Is. XXIII, 18</span>) <span dir=\"rtl\">זהו המְכַסֶּה דברים וכ׳</span> he who keeps secret the things which the Old of Days has covered (mysteries). B. Kam. l. c.; Gen. R. l. c., v. supra. <span class=\"citation\">Pesik. R. s. 26</span> <span dir=\"rtl\">מְכַסָּה אני ממך</span> shall I conceal it from thee?—<span class=\"citation\">Gen. R. s. 87</span> <span dir=\"rtl\">כִּסְּתָה פניה</span> she covered her (the idol’s) face. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">לא כ׳ עליהם הכתוב</span> the Bible did not cover their guilt (v. <a href=\"#\" data-headword=\"חָפָה\">חָפָה</a>); a. fr.—Part. pass. <span dir=\"rtl\">מְכוּסֶּה</span>, f. <span dir=\"rtl\">מְכוּסָּה</span>; pl. <span dir=\"rtl\">מְכוּסִּים</span>, <span dir=\"rtl\">מְכוּסִּין</span>; <span dir=\"rtl\">מְכוּסּוֹת</span>. Ib. s. 52 (ref. to <span class=\"citation\">Gen. XX, 16</span> [read:] <span dir=\"rtl\">עשאה מטרונה כסות עינים שהיא מכ׳ מן העין</span> he (Abimelech) made a matron of her (Sarah) (giving her) ‘a cover of the eyes’, by which she was protected from the gaze (of men). <span class=\"citation\">Pes. 54ᵇ</span> <span dir=\"rtl\">שבעה … מכ׳ וכ׳</span> seven things are hidden from man; a. fr.—[<span class=\"citation\">Gen. R. s. 79</span>, end <span dir=\"rtl\">מה את מכסה בי</span>, read: <span dir=\"rtl\">מב׳</span>, v. <a href=\"#\" data-headword=\"בְּסָא\">בְּסָא</a>.—Sifra B’ḥuck., Par. 2, ch. V <a href=\"#\" data-headword=\"כסי ²\">כיסה</a>, v. <a href=\"#\" data-headword=\"כָּסַח\">כָּסַח</a>.]</div></div><div class=\"sense\"><b>Nif. נִכְסָה</b> <div class=\"sense\"><i>to be covered, hidden</i>. <span class=\"citation\">Snh. II, 1</span> (<span class=\"citation\">18ᵃ</span>; <span class=\"citation\">19ᵃ</span>) <span dir=\"rtl\">הן נִכְסִין … והוא נ׳</span> when they (who form the funeral cortege) are hidden from his view (when entering an alley), he (the high priest) appears; when they emerge, he disappears (in the alley). <span class=\"citation\">Cant. R. to II, 9</span> <span dir=\"rtl\">נראה וחוזר ונ׳</span> is visible and disappears again; Ruth. R. to II, 14; Pesik. Haḥod., p. 49ᵇ. <span class=\"citation\">Num. R. s. 22</span> (play on <a href=\"#\" data-headword=\"נְכָסִים\">נְכָסִים</a>) <span dir=\"rtl\">נ׳ מזה וכ׳</span> they disappear from one and appear to the other; a. fr.</div></div><div class=\"sense\"><b>Hithpa. הִתְכַּסֶּה</b> <div class=\"sense\"><i>to be covered, clothed</i>. <span class=\"citation\">Bets. 16ᵃ</span> (ref. to <span dir=\"rtl\">בַּכֶּסֶה</span>, <span class=\"citation\">Ps. LXXXI, 4</span>) <span dir=\"rtl\">איזהו חג שהחדש מִתְכַּסֶּה בו</span> what festival is that on which the new moon is hidden (seen only by a few)?; <span class=\"citation\">Pirké d’R. El. ch. VII</span>, end <span dir=\"rtl\">ביום שמ׳ כולו</span> on the day when the moon is entirely covered. <span class=\"citation\">Deut. R. s. 3</span> <span dir=\"rtl\">מתכ׳ משלו</span> clothed himself at his (the fosterfather’s) expense. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כל … אוכל ומתכ׳ וכ׳</span> all that is spent on you for eating and clothing &amp;c. <span class=\"citation\">Keth. V, 8</span> <span dir=\"rtl\">מִתְכַּסָּה</span>, v. <a href=\"#\" data-headword=\"בְּלָאוֹת\">בְּלָאוֹת</a>. <span class=\"citation\">Tam. I, 1</span> <span dir=\"rtl\">מִתְכַּסִּין</span>, v. <a href=\"#\" data-headword=\"כְּסוּת\">כְּסוּת</a>; a. fr.</div></div>","alt":["כָּסָה II"]},"12780":{"h":"כְּסֵי ²","r":"K00918","html":"<div class=\"sense\">, <i>Part.</i> <i> pass</i>. <a href=\"#\" data-headword=\"כְּסֵי\">כְּסִי</a>, f. <a href=\"#\" data-headword=\"כַּסִּי\">כַּסְיָא</a> <i>hidden</i>. <span class=\"citation\">Targ. I Sam. III, 1</span> כְּסִי Bxt. (ed. <a href=\"#\" data-headword=\"כַּסִּי\">כַּסִּי</a>, <a href=\"#\" data-headword=\"כְּסֵי ²\">כַּסֵּי</a>; h. text <span dir=\"rtl\">יקר</span>). <span class=\"citation\">Targ. II Kings VI, 8</span> (h. text <span dir=\"rtl\">פלני</span>). <span class=\"citation\">Targ. Job XXVIII, 21</span>. <span class=\"citation\">Targ. II Kings VI, 9</span> <a href=\"#\" data-headword=\"כְּסָן\">כָּסָן</a> (h. text <span dir=\"rtl\">נְחִתִּים</span>).</div><div class=\"sense\"><b>Pa. כַּסֵּי</b> <div class=\"sense\"><i>to cover, hide, conceal</i>. <span class=\"citation\">Targ. O. Gen. XXXVIII, 15</span> (Y. <span dir=\"rtl\">כעיסת</span>). Ib. XLVII, 18; a. fr.—<i>Part. pass</i>. <span dir=\"rtl\">מְכַסָּא</span> <i>unknown, remote</i>. <span class=\"citation\">Targ. II Kings XIX, 2</span>. <span class=\"citation\">Targ. O. Lev. IV, 13</span>. <span class=\"citation\">Targ. II Sam. XIII, 2</span> (h. text <span dir=\"rtl\">ויפלא</span>); a. e.—<span class=\"citation\">Sabb. 156ᵇ</span> <span dir=\"rtl\">כַּסִּי רישיך וכ׳</span> keep thy head covered in order that the fear of the Lord may rest upon thee. <span class=\"citation\">Ib. 125ᵃ</span> <span dir=\"rtl\">לכַסּוּיֵי בהו וכ׳</span> to cover a nuisance with it. <span class=\"citation\">Gen. R. s. 52</span>, [read as:] <span class=\"citation\">Yalk. ib. 91</span> <span dir=\"rtl\">וכסי עיניך מינאי</span> and close thine eye from upon me, i.e. take the indulgence money. <span class=\"citation\">Taan. 25ᵃ</span> רקיע … כסי פניך ולא אִיכַּסִי ‘cover thy face, O sky,’ but the sky was not covered. <span class=\"citation\">Ḥull. 87ᵃ</span> <span dir=\"rtl\">אפשר … ומְכַסֵּי בחדא</span> he may kill with one hand and cover (the blood) with the other; a. fr.</div></div><div class=\"sense\"><b>Ithpa. אִיתְכַּסִּי  אִיכַּסִּי</b> <div class=\"sense\"><i>to be covered, hidden; to cover one’s self; to conceal one’s self, withdraw</i>. <span class=\"citation\">Targ. Y. Gen. XX, 16</span>. <span class=\"citation\">Targ. Y. Lev. IV, 13</span>. <span class=\"citation\">Targ. Gen. XVIII, 14</span> (h. text <span dir=\"rtl\">יפלא</span>, v. supra); a. fr.—<span class=\"citation\">Targ. Ps. CXXXIX, 6</span> <span dir=\"rtl\">מִכַּסְיָא</span>.—Taan. l. c., v. supra. Ib. 23ᵃ <span dir=\"rtl\">א׳ מעינא ונים וכ׳</span> he disappeared and slept seventy years. <span class=\"citation\">Keth. 63ᵃ</span> <span dir=\"rtl\">שאילי … ואִיכַּסָּאִי</span> borrow some garments and dress thyself; a. fr.</div></div>","alt":["כְּסָא"]},"12781":{"h":"כַּסִּי","r":"K00919","html":"<div class=\"sense\"><i>hidden</i>, v. preced.—[<a href=\"#\" data-headword=\"כסי\">כסי</a>, <span class=\"citation\">Tosef. Kel. B. Mets. II, 9</span>, v. <a href=\"#\" data-headword=\"כִּיסּוּי\">כִּיסּוּי</a>.]</div>","alt":["כַּסְיָא"]},"12782":{"h":"כַּסְיָאן","r":"K00920","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּסָן\">כְּסָן</a></div>","alt":[]},"12783":{"h":"כסידא","r":"K00921","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Y. Ex. IX, 31</span>, read: <a href=\"#\" data-headword=\"בְּסִיר\">בְּסִירָא</a>, v. <a href=\"#\" data-headword=\"בְּשַׂר ²\"><span dir=\"rtl\">בְּסַר</span> II</a></div>","alt":[]},"12784":{"h":"כְּסִיטְנָא","r":"K00922","html":"<div class=\"sense\"> = <span dir=\"rtl\">כִּסּוּי טֶנֶא</span>, v. <a href=\"#\" data-headword=\"כִּיסּוּי\">כִּיסּוּי</a></div>","alt":[]},"12785":{"h":"כְּסִיָּיה","r":"K00923","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (כָּסָה II) <i>covering</i>; <span dir=\"rtl\">כְּסִיַּית עינים</span> <i>blindness</i>. <span class=\"citation\">Meg. 28ᵃ</span> <span dir=\"rtl\">א&quot;ת כסות אלא כ׳ ע׳</span> ed., v. <a href=\"#\" data-headword=\"כֵּהוּת\">כֵּהוּת</a>.</div>","alt":[]},"12786":{"h":"כְּסִיל","r":"K00924","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b>  (a denom. of <a href=\"#\" data-headword=\"כֶּסֶל\">כֶּסֶל</a> q. v.) [<i>one with thick loins, stout</i>,] (cmp. <a href=\"#\" data-headword=\"טִפֵּשׁ\">טִפֵּשׁ</a>) <i>fool, foolish, overbearing</i>. <span class=\"citation\">Y. Peah I, 15ᵇ</span> bot.; <span class=\"citation\">Yalk. Ex. 415</span> (ref. to <span class=\"citation\">Prov. III, 26</span>) <span dir=\"rtl\">דברים שאתה כ׳ בהם וכ׳</span> in things in which thou art foolish (ignorant), He will guard thy foot &amp;c.—Pl. <span dir=\"rtl\">כְּסִילִים</span>. <span class=\"citation\">Num. R. s. 16</span> (ref. to <span class=\"citation\">Prov. XXVI, 6</span>) <span dir=\"rtl\">עשו עצמן כ׳</span> they (the spies) made fools of themselves.</div><div class=\"sense\"><b>—2)</b> <i>K’sil</i>, the constellation <i>Orion</i> (v. Winer, Reallex. s. v. Nimrod). <span class=\"citation\">Ber. 58ᵇ</span></div>","alt":[]},"12787":{"h":"כְּסִילָא","r":"K00925","html":"<div class=\"sense\"><b>1)</b> <i>fool</i>.—Pl. <span dir=\"rtl\">כְּסִילַיָּיא</span>. <span class=\"citation\">Targ. Ps. XLIX, 11</span> (Bxt. <i>sing</i>.). <span class=\"citation\">Ib. XCIV, 8</span> (some ed. <span dir=\"rtl\">כְּסִילֵי</span>). [In Targ. mostly <span dir=\"rtl\">סכלא</span>.]</div><div class=\"sense\"><b>—2)</b> <i>Orion</i>. <span class=\"citation\">Targ. Am. V, 8</span> (v. <a href=\"#\" data-headword=\"נִיפְלָא\">נִיפְלָא</a>).—<span class=\"citation\">Ber. 58ᵇ</span> <a href=\"#\" data-headword=\"כִּסְלָא I\">כִּסְלָא</a> (Ms. M. <a href=\"#\" data-headword=\"כּוּסְלָא\">כּוּסְלָא</a>, Ms. F. <a href=\"#\" data-headword=\"כִּיסְתָא II\">כִּיסְ׳</a>).</div>","alt":[]},"12788":{"h":"כְּסִיסְטָא","r":"K00926","html":"<div class=\"sense\"> (ξέστης, v. Sm. Ant. s. v.) <i>xestes, sextarius</i>, a dry and liquid measure (nearly a pint).—Pl. <span dir=\"rtl\">כְּסִיסְטָאוֹת</span>, <a href=\"#\" data-headword=\"כְּסוּ\">כְּסוּ׳</a>. <span class=\"citation\">Gen. R. s. 4</span>; <span class=\"citation\">Yalk. ib. 5</span>. [‘Rashi’ reads <span dir=\"rtl\">גְּזוּזְטְרָאוֹת</span>.]</div>","alt":["כְּסוּסְ׳"]},"12789":{"h":"כסיפא","r":"K00927","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כָּסִפְיָא\">כָּסִפְיָא</a></div>","alt":[]},"12790":{"h":"כְּסִיפוּתָא","r":"K00928","html":"<div class=\"sense\"> f. = <a href=\"#\" data-headword=\"כִּיסּוּפָא\">כִּיסּוּפָא</a>. <span class=\"citation\">B. Mets. 22ᵃ</span> <span dir=\"rtl\">משום כ׳</span> (Ms. M. <span dir=\"rtl\">מחמת כִּסּוּפָא</span>, v. <span class=\"citation\">Kidd. 52ᵇ</span>).</div>","alt":[]},"12791":{"h":"כְּסִיפְתָּא","r":"K00929","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּסַפְתָּא\">כְּסַפְתָּא</a></div>","alt":[]},"12792":{"h":"כְּסִיקַבְיָא","r":"K00930","html":"<div class=\"sense\"> = <span dir=\"rtl\">כִּיסּוּי קַבְיָא</span>. <span class=\"citation\">Tosef. Kel. B. Mets. II, 9</span> some ed. (ed. Zuck. <span dir=\"rtl\">כסי קמיא</span>).</div>","alt":[]},"12793":{"h":"כסירא","r":"K00931","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Y. Ex. IX, 31</span>, v. <a href=\"#\" data-headword=\"בְּשַׂר ²\"><span dir=\"rtl\">בְּסַר</span> II</a></div>","alt":[]},"12794":{"h":"כְּסִיתָא","r":"K00932","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (כְּסֵי II) [<i>the covered, rare</i>,] </div><div class=\"sense\"><b>1)</b> <i>coral</i>; </div><div class=\"sense\"><b>2)</b> <i>coral-wood</i>. <span class=\"citation\">B. Bath. 80ᵇ</span>, sq.; <span class=\"citation\">R. Hash. 23ᵃ</span>, v. <a href=\"#\" data-headword=\"אַלְמוּג\">אַלְמוּג</a>; <span class=\"citation\">Yalk. Is. 314</span> <a href=\"#\" data-headword=\"סכסיתא\">סכסיתא</a> (corr. acc.). R. Hash. l. c. <span dir=\"rtl\">דבי ארמאי מסקן כ׳</span> the light ships (v. <a href=\"#\" data-headword=\"בּוּרְנִי I\">בּוּרְנִי</a>) of the Romans are employed for fishing corals. Ib. (describing the diving process) … <span dir=\"rtl\">וקטר בכ׳</span> and flax ropes are tied to the coral plants &amp;c. <span class=\"citation\">Keth. 98ᵃ</span> כ׳ דיתמי Var. in Rashi (ed. <a href=\"#\" data-headword=\"כִּיסְתָא I\">כיסתא</a>) corals belonging to minor orphans.</div>","alt":[]},"12795":{"h":"*כְּסִיתָּא","r":"K00933","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> a phonetic rendition of <a href=\"#\" data-headword=\"קְשִׂיטָה\">קְשִׂיטָה</a> q. v. <span class=\"citation\">Gen. R. s. 79</span> (corr. vers. after Ar. s. v. <a href=\"#\" data-headword=\"קְשִׂיטָה\">קשיטה</a>) (they heard one woman say to another) <span dir=\"rtl\">אשאלי לי כְּסִיתְּתָךְ</span> (for <span dir=\"rtl\">קשיטתך</span>, meaning to say <span dir=\"rtl\">מרגליתיך</span>); (and furthermore) <span dir=\"rtl\">אפיק הדא כ׳ למרעיא</span> lead this <i>K’sitta</i> out to pasture (meaning to say <a href=\"#\" data-headword=\"אִימַּרְתָּא\">אִימַּרְתָּא</a>); [Ar. reads <span dir=\"rtl\">קשיט׳</span>].</div>","alt":[]},"12796":{"h":"כֶּסֶךְ","r":"K00934","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (transpos. of <a href=\"#\" data-headword=\"סִכְסֵךְ I\">סכסך</a> q. v.; cmp. <a href=\"#\" data-headword=\"גִּעְגֵּעַ\">גַּעְגֵּעַ</a>), pl. <span dir=\"rtl\">כְּסָכִים</span>, <span dir=\"rtl\">כַּסְכַּסִּים</span> <i>leather thongs</i> for crosswise fastening (cmp. b. h. <span dir=\"rtl\">שָׂרַךְ</span> a. <span dir=\"rtl\">שְׂרוֹךְ נַעַל</span>). <span class=\"citation\">Sabb. 138ᵇ</span> הגוד בכְסָכָיו Ar. (Ms. O. <span dir=\"rtl\">בכַסְכַּסָּיו</span>; ed. <span dir=\"rtl\">בכיסנא</span>, read: <span dir=\"rtl\">בכיסכא</span>; Ms. M. <span dir=\"rtl\">חגור בנסבא</span>, read: <span dir=\"rtl\">הגוד בכסכא</span>, v. Rabb. D. S. a. l.) it is permitted to stretch the milk (or wine) bag by its thongs, v. <a href=\"#\" data-headword=\"*גּוֹד\">גּוֹד</a>. Ib. 139ᵇ בכילה ובכְסָכֶיהָ Ar. (ed. <span dir=\"rtl\">ובכַסְכַּסֶּיהָ</span>) wrapt in a bed-curtain with the thongs attached.</div>","alt":["כַּסְכַּס"]},"12797":{"h":"כִּסְכּוּס","r":"K00935","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כִּסְכֵּס\">next w.</a>) <i>rubbing</i>. <span class=\"citation\">Zeb. 94ᵇ</span> <span dir=\"rtl\">כיבוס דלית ליה כ׳ וכ׳</span> washing without rubbing is not called <i>kibbus</i></div>","alt":[]},"12798":{"h":"כִּסְכֵּס","r":"K00936","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"כְּסַס\">כְּסַס</a>) </div><div class=\"sense\"><b>1)</b> <i>to rub, scour</i>. <span class=\"citation\">Nidd. IX, 7</span> <span dir=\"rtl\">וצריך לכַסְכֵּס וכ׳</span> one must scour with these substances three times. <span class=\"citation\">Sabb. 141ᵃ</span> <span dir=\"rtl\">מְכַסְכְּסוֹ מבפנים</span> he may rub the mud off from the inside. Y. ib. VII, 10ᵃ bot. <span dir=\"rtl\">ובלבד שלא יְכַסְכֵּס</span> provided that he does not rub.</div><div class=\"sense\"><b>—2)</b> <i>to chew, gnaw</i>, v. <a href=\"#\" data-headword=\"כָּסַס\">כָּסַס</a>.</div>","alt":[]},"12799":{"h":"כַּסְכֵּס","r":"K00937","html":"<div class=\"sense\">, <i>to rub, to polish</i>. <span class=\"citation\">Sabb. 140ᵃ</span> <span dir=\"rtl\">כַּסְכּוּסֵי</span>, v. <a href=\"#\" data-headword=\"כִּיתָּנִיתָא\">כִּיתָּנִיתָא</a>. <span class=\"citation\">M. Kat. 10ᵇ</span> <span dir=\"rtl\">לכַסְכּוּסֵי קירמי</span> to gloss fine clothes by rubbing with a substance. <span class=\"citation\">Zeb. 94ᵇ</span> top <span dir=\"rtl\">שכשוכי אין כסכוסי לא</span> (quot. in Sh’ilt. d’R. Aḥai s. 86; ed. <span dir=\"rtl\">שכשוך … כיבוס …</span>) cleansing by rinsing is permitted, by rubbing is forbidden. [<span class=\"citation\">Sabb. 147ᵃ</span> כגון כסכוסי מאנא דמחזי כמרזב Ms. M. a. Ar., a gloss, interpreting <span dir=\"rtl\">כיסי בבלייתא</span>.]</div>","alt":[]}};
